__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"lorePack",{enumerable:!0,get:function(){return f}});var n=r(d[0]),t=r(d[1]),l=r(d[2]),s=r(d[3]),o=r(d[4]),c=r(d[5]),h=r(d[6]),u=r(d[7]),w=r(d[8]),D=r(d[9]);const f={entries:{...n.chapters1,...t.chapters2,...l.classes,...s.races,...o.zones1,...c.zones2,...h.instances1,...u.instances2,...w.items,...D.terms},eras:{creation:{title:"Titanen und Alte G\xf6tter",when:"Vor aller \xfcberlieferten Geschichte"},"ancient-kalimdor":{title:"Das Reich der Kaldorei",when:"Zehntausend Jahre und mehr vor dem Dunklen Portal"},"elder-kingdoms":{title:"Die alten K\xf6nigreiche",when:"Etwa 7.000 bis 200 Jahre vor dem Dunklen Portal"},draenor:{title:"Die Orcs von Draenor",when:"Die Jahrzehnte vor dem Dunklen Portal"},"first-war":{title:"Der Erste Krieg",when:"Die \xd6ffnung des Dunklen Portals (Jahr 0)"},"second-war":{title:"Der Zweite Krieg",when:"Einige Jahre nach dem Dunklen Portal"},interwar:{title:"Zwischen den Kriegen",when:"Die Jahre nach dem Zweiten Krieg"},"third-war":{title:"Der Dritte Krieg",when:"Etwa zwanzig Jahre nach dem Dunklen Portal"},"new-homes":{title:"Eine neue Heimat in Kalimdor",when:"Die Jahre nach dem Dritten Krieg"},classic:{title:"Die \xc4ra von World of Warcraft",when:"Jahr 25 nach dem Dunklen Portal, die Zeit von Forever"},beyond:{title:"Nach Classic",when:"Sp\xe4tere Erweiterungen (nicht Teil von Forever)"}},categories:{chapter:"Die Geschichte von Warcraft",class:"Klassen",race:"V\xf6lker",zone:"Gebiete",instance:"Dungeons und Schlachtz\xfcge",item:"Legend\xe4re Gegenst\xe4nde",term:"Glossar"},notice:"Originaltext, verfasst f\xfcr WoW Forever Path. Die Fakten wurden mit den aufgef\xfchrten Quellen abgeglichen; Seiten von warcraft.wiki.gg (CC BY-SA 4.0) und Blizzard-Beitr\xe4ge dienten als Referenz, ihr Text wurde nicht \xfcbernommen. World of Warcraft und Blizzard sind Marken von Blizzard Entertainment, Inc."}},1709,[1721,1722,1723,1724,1725,1726,1727,1728,1729,1730]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"chapters1",{enumerable:!0,get:function(){return n}});const n={"chapter:titans-and-old-gods":{title:"Die Titanen und die Alten G\xf6tter",summary:"Lange vor allen sterblichen K\xf6nigreichen k\xe4mpften die Titanen des Pantheons gegen die Alten G\xf6tter um die Seele einer jungen Welt, und Azeroth tr\xe4gt die Narben bis heute.",when:"Vor aller \xfcberlieferten Geschichte",body:["Lange bevor Sterbliche etwas aufzeichneten, durchstreiften die Titanen das Gro\xdfe Dunkle Jenseits: Weltenseelen, die zu lebendigen Riesen herangewachsen waren. Die edelsten von ihnen schlossen sich zum Pantheon zusammen und suchten die Sterne nach schlafenden Weltenseelen wie ihren eigenen ab. Tief in Azeroth sp\xfcrten sie eine von au\xdfergew\xf6hnlicher Verhei\xdfung, doch dunklere M\xe4chte hatten sie zuerst gefunden.","Die Leerenf\xfcrsten hatten ihre Diener, die Alten G\xf6tter, auf die junge Welt geschleudert. Y'Shaarj, C'Thun, Yogg-Saron und N'Zoth gruben ihre Leiber in die Kruste und errichteten das Schwarze Imperium, mit den Elementarf\xfcrsten des Feuers, der Erde, der Luft und des Wassers als Feldherren. Als das Pantheon eintraf, zerschlugen seine titanengeschmiedeten Armeen die Zitadellen des Imperiums. Hochvater Aman'Thul riss Y'Shaarj aus dem Boden, doch der Schlag \xf6ffnete eine Wunde, aus der das arkane Lebensblut der Welt str\xf6mte. Die Titanen begriffen, dass die Vernichtung der \xfcbrigen Azeroth selbst t\xf6ten k\xf6nnte.","Also w\xe4hlten die H\xfcter Gef\xe4ngnisse. C'Thun, Yogg-Saron und N'Zoth wurden tief unter der Erde in Ketten gelegt, und die Elementarf\xfcrsten wurden auf die Elementarebene verbannt, zu deren Reichen Skywall und die Feuerlande geh\xf6ren. Die H\xfcter beruhigten die blutende Wunde zu einem schimmernden See, dem Brunnen der Ewigkeit, formten Berge und Meere und hinterlie\xdfen Titanengew\xf6lbe wie Uldaman. Nachdem ein monstr\xf6ser Protodrache namens Galakrond gefallen war, erhob das Pantheon f\xfcnf gro\xdfe Drachen zu Aspekten, die die Welt besch\xfctzen sollten, und zog dann zu den Sternen davon."]},"chapter:sargeras-and-the-burning-legion":{title:"Sargeras und die Brennende Legion",summary:"Der gr\xf6\xdfte Streiter des Pantheons verlor den Glauben an die Sch\xf6pfung und rief einen d\xe4monischen Kreuzzug ins Leben, um sie zu verbrennen; Azeroth wurde zu der Beute, die er am meisten begehrte.",when:"Lange vor den Nachtelfen",body:["Sargeras war der Streiter des Pantheons, der Titan, der D\xe4monen durch den Kosmos jagte und sie auf einer Gef\xe4ngniswelt namens Mardum einsperrte. In Zeitaltern des Krieges erkannte er, was die Leerenf\xfcrsten wirklich wollten: eine Weltenseele verderben und so einen eigenen dunklen Titanen geb\xe4ren. \xdcberzeugt, dass die Sch\xf6pfung unrettbar fehlerhaft war, beschloss er, es sei gn\xe4diger, alles zu verbrennen.","Er zerschmetterte das Gef\xe4ngnis Mardum und lie\xdf seine D\xe4monen als erste Reihen der Brennenden Legion frei. Auf der Welt Argus bot er den Eredar Wissen und Macht an; ihre Anf\xfchrer Kil'jaeden und Archimonde nahmen an, w\xe4hrend der Prophet Velen mit jenen floh, die ablehnten, dem Volk, das man sp\xe4ter Draenei nannte. Das Pantheon versuchte, seinen einstigen Streiter aufzuhalten, und fiel durch seine Hand.","Von da an zog die Legion von Welt zu Welt, angef\xfchrt von Sargeras und gedient von den Eredar, den Nathrezim genannten Schreckensf\xfcrsten und unz\xe4hligen niederen D\xe4monen. Azeroth bedeutete mehr als die meisten Welten: eine Weltenseele, die noch schlief und schon von den Alten G\xf6ttern gezeichnet war. Bis zur Zeit von World of Warcraft war die Legion zweimal in Azeroth eingefallen, und ihr Fl\xfcstern pr\xe4gte die Geschichte von Elfen, Orcs und Menschen gleicherma\xdfen."]},"chapter:rise-of-the-kaldorei":{title:"Der Aufstieg der Kaldorei",summary:"Trolle beherrschten das alte Kalimdor, bis ein Stamm, den es zum Brunnen der Ewigkeit zog, zu den Nachtelfen wurde, deren K\xf6nigin Azshara ein Reich von atemberaubender Magie erschuf.",when:"Etwa 15.000 bis 10.000 Jahre vor dem Dunklen Portal",body:["In den Zeitaltern nach dem Abschied der Titanen war Kalimdor ein einziger gro\xdfer Kontinent. Von den Zandalari angef\xfchrte Trolle f\xfchrten einen langen Krieg gegen die insektenartigen Aqir, \xdcberbleibsel der Diener der Alten G\xf6tter, und trieben sie in den hohen Norden und tiefen S\xfcden des Landes, wo ihre Nachfahren zu den Nerubern und den Qiraji werden sollten. Nach dem Sieg zerfielen die Trolle in rivalisierende Reiche wie die der Gurubashi und der Amani.","Ein Trollstamm w\xe4hlte einen ruhigeren Weg. Er lie\xdf sich an den Ufern des Brunnens der Ewigkeit nieder, und \xfcber Generationen ver\xe4nderte ihn die Macht des Brunnens: Sein Volk wurde gr\xf6\xdfer und langlebiger, verehrte die Mondg\xf6ttin Elune und nannte sich Kaldorei, \u201eKinder der Sterne\u201c. Geleitet vom Halbgott Cenarius und anderen uralten Geistern der Wildnis \xfcberstrahlten sie bald ihre Trollvettern.","Ihre gr\xf6\xdfte Herrscherin war K\xf6nigin Azshara, von ihrem Volk verehrt und von den Hochgeborenen umgeben, einer Aristokratie von Zauberern, die dem Brunnen immer mehr Macht entzogen. Ihr Palast in Zin-Azshari stand an seinem Ufer, und ihr Reich erstreckte sich \xfcber ganz Kalimdor. Der Hunger der Hochgeborenen nach Magie sandte jedoch Wellen weit \xfcber die Welt hinaus, und etwas Gewaltiges im Wirbelnden Nether sp\xfcrte sie."]},"chapter:war-of-the-ancients":{title:"Der Krieg der Ahnen",summary:"Azshara \xf6ffnete der Brennenden Legion den Weg, und die Welt w\xe4re beinahe untergegangen, bevor der Brunnen der Ewigkeit sich selbst zerriss.",when:"Etwa 10.000 Jahre vor dem Dunklen Portal",body:["Sargeras fl\xfcsterte Azshara und ihren Hochgeborenen ein und versprach eine Welt, die nach ihrem Ebenbild neu geschaffen w\xfcrde. Sie glaubten ihm und \xf6ffneten durch den Brunnen der Ewigkeit ein Tor f\xfcr die Brennende Legion. D\xe4monen unter Archimonde und Mannoroth str\xf6mten nach Kalimdor und begannen, eben jene Kaldorei abzuschlachten, \xfcber die die K\xf6nigin herrschte.","Der Widerstand sammelte sich um unwahrscheinliche Anf\xfchrer: Malfurion Sturmgrimm, den ersten Nachtelfen, der von Cenarius das Druidentum erlernte; seinen Zwillingsbruder Illidan, einen begabten Zauberer; und Tyrande Wisperwind, eine Priesterin der Elune. Die Halbg\xf6tter der Wildnis und die meisten Drachenschw\xe4rme k\xe4mpften an ihrer Seite. Der schwarze Aspekt Neltharion bot eine Waffe an, die Drachenseele, richtete sie aber gegen seine Verb\xfcndeten; dieser Verrat sollte ihm den Namen Todesschwinge einbringen.","Als Sargeras selbst durch das Portal treten wollte, st\xf6rten Malfurion und seine Verb\xfcndeten den Zauber der Hochgeborenen. Der instabile Brunnen implodierte, und es folgte die Gro\xdfe Teilung: Das Meer verschlang Zin-Azshari, Kalimdor brach auseinander, und wo der Brunnen gewesen war, begann ein Sturm namens Mahlstrom zu kreisen. Azshara und ihr Hof verschwanden unter den Wellen, um eines Tages als Naga zur\xfcckzukehren. Aus dem einen Kontinent gingen die L\xe4nder hervor, die heute als Kalimdor, die \xd6stlichen K\xf6nigreiche und Nordend bekannt sind."]},"chapter:the-long-watch-of-hyjal":{title:"Die lange Wacht am Hyjal",summary:"Die \xdcberlebenden lie\xdfen \xfcber einem zweiten Brunnen einen Weltenbaum wachsen, sperrten Illidan unter der Erde ein und hielten zehntausend Jahre lang Wache.",when:"Ab etwa 10.000 Jahren vor dem Dunklen Portal",body:["Die Nachtelfen, die der Teilung entkommen waren, sammelten sich auf dem Berg Hyjal. Dort entdeckten sie, dass Illidan Phiolen mit dem Wasser des alten Brunnens bei sich getragen und einen Teil davon in einen Bergsee gegossen hatte; so war ein neuer Brunnen der Ewigkeit entstanden. Aus Furcht, er k\xf6nnte eines Tages die Legion zur\xfcckrufen, sperrten Malfurion und Cenarius Illidan in den Barrow Deeps ein, einem Gef\xe4ngnis unter der Erde, in dem die W\xe4rterin Maiev Schattensang zehntausend Jahre lang \xfcber ihn wachen sollte.","Drei Aspekte, Alexstrasza, Ysera und Nozdormu, antworteten, indem sie Nordrassil, den Weltenbaum, \xfcber dem neuen Brunnen wachsen lie\xdfen. Seine Wurzeln versiegelten das Wasser, und sein Segen schenkte den Nachtelfen Unsterblichkeit und den Druiden eine Verbindung zum Smaragdgr\xfcnen Traum, in dem viele von ihnen jahrhundertelang schliefen. Tyrande f\xfchrte die Schwesternschaft der Elune und die Schildwachen, die die W\xe4lder h\xfcteten, w\xe4hrend die Druiden tr\xe4umten. Arkane Magie wurde unter den Kaldorei verboten.","Nicht alle Hochgeborenen gehorchten. Einige wurden \xfcber das Meer verbannt und gr\xfcndeten Quel'Thalas; andere, die Shen'dralar, verbargen sich in der Stadt Eldre'Thalas im heutigen Feralas. Ihre Ruinen sind heute als D\xfcsterbruch bekannt."]},"chapter:exiles-of-quelthalas":{title:"Die Verbannten von Quel'Thalas",summary:"Verbannte Hochgeborene \xfcberquerten das Meer, entfachten den Sonnenbrunnen und errichteten in den n\xf6rdlichen W\xe4ldern Lordaerons ein Elfenk\xf6nigreich.",when:"Etwa 6.800 Jahre vor dem Dunklen Portal",body:["Lange nach der Teilung konnte eine Gruppe von Hochgeborenen noch immer nicht vom Arkanen lassen. Ihre r\xfccksichtslosen Zauber beschworen St\xfcrme \xfcber dem Eschental herauf, und schlie\xdflich verbannten die Nachtelfen sie. Angef\xfchrt von Dath'Remar Sonnenwanderer segelten die Verbannten ostw\xe4rts \xfcber das Gro\xdfe Meer und durchstreiften jahrelang den neuen Kontinent auf der Suche nach einem Land, in dem die Magie stark floss.","Etwa 6.800 Jahre vor dem Dunklen Portal fanden sie es im Norden Lordaerons. Dath'Remar goss eine gestohlene Phiole mit Wasser aus dem Brunnen der Ewigkeit in einen See auf einem Knotenpunkt von Leylinien, und der Sonnenbrunnen flammte auf. Um ihn herum entstanden Quel'Thalas und seine Hauptstadt Silbermond. Weil die Verbannten unter der Sonne statt unter dem Mond lebten, ver\xe4nderten sie sich im Lauf der Jahrhunderte und wurden zu den Hochelfen, den Quel'dorei.","Das Land war nicht leer. Es barg uralte Ruinen, die den Amanitrollen heilig waren, und diese griffen die Neuank\xf6mmlinge in \xfcberw\xe4ltigender Zahl an. Die Elfen hielten sie mit Magie zur\xfcck und errichteten Ban'dinoriel, eine Barriere aus Runensteinen, die die Amani fernhielt. Rund viertausend Jahre lang gedieh Quel'Thalas hinter ihr, w\xe4hrend die Trolle auf Rache warteten."]},"chapter:arathor-and-the-troll-wars":{title:"Arathor und die Trollkriege",summary:"Die verstreuten St\xe4mme der Menschheit vereinten sich unter K\xf6nig Thoradin, und ein B\xfcndnis mit den Elfen zerschlug das Reich der Amani am Fu\xdf des Alteracgebirges.",when:"Etwa 2.800 Jahre vor dem Dunklen Portal",body:["Jahrtausendelang bek\xe4mpften sich die Menschenst\xe4mme der \xd6stlichen K\xf6nigreiche gegenseitig, w\xe4hrend Pl\xfcnderer der Amani aus dem Norden zuschlugen. Etwa 2.800 Jahre vor dem Dunklen Portal erkannte Thoradin vom Stamm der Arathi, dass eine gespaltene Menschheit untergehen w\xfcrde. Durch Heiraten, Versprechen und Eroberung vereinte er die St\xe4mme zum K\xf6nigreich Arathor und erbaute dessen Hauptstadt, die Festungsstadt Strom, im heutigen Arathihochland.","Die Amani, mit Hilfe der Zandalari wiedererstarkt, griffen Quel'Thalas in gewaltiger Zahl an. Die Elfen wandten sich an Arathor. Im Austausch f\xfcr menschliche Soldaten willigten sie ein, hundert auserw\xe4hlte Menschen in Magie zu unterweisen, die ersten menschlichen Magier. Gemeinsam zerschlugen Elfen und Menschen das Heer der Amani am Fu\xdf des Alteracgebirges, und das Feuer der Magier zerstreute die Trolle so gr\xfcndlich, dass sich ihr Reich nie wieder erholte.","Aus Dankbarkeit schworen die Elfen von Quel'Thalas der Blutlinie der K\xf6nige Arathors die Treue. Strom bl\xfchte auf, und sein Volk breitete sich \xfcber den Norden aus. Die Amani sollten sich noch oft erheben, und im Hinterland und im Arathihochland suchen Waldtrollst\xe4mme bis heute die Ruinen jenes alten Krieges heim."]},"chapter:guardians-and-the-seven-kingdoms":{title:"Die W\xe4chter und die Sieben K\xf6nigreiche",summary:"Menschliche Magie lockte D\xe4monen an, also gr\xfcndeten die Magier Dalaran und w\xe4hlten W\xe4chter, die im Verborgenen k\xe4mpften, w\xe4hrend Arathor in sieben K\xf6nigreiche zerfiel.",when:"Die Jahrtausende nach den Trollkriegen",body:["Die Magie verbreitete sich in Arathor schneller als die Weisheit. Die Zauber der Magier schw\xe4chten die Mauern der Welt und lenkten die Aufmerksamkeit von D\xe4monen auf sich, also gr\xfcndeten die Hochelfen und die menschlichen Magier den Rat von Tirisfal. Im Geheimen erw\xe4hlte der Rat einen einzigen W\xe4chter, der seine vereinte Macht tragen und die Agenten der Brennenden Legion jagen sollte.","Die Magier erbauten au\xdferdem eine eigene Stadt, Dalaran, in der die Kirin Tor herrschen sollten. Unterdessen zogen Arathors Erben von Strom fort, und im Lauf der Jahrhunderte zerfiel das Reich in sieben Menschenk\xf6nigreiche: Lordaeron, Stromgarde, Gilneas, Alterac, Kul Tiras, Dalaran und im S\xfcden Sturmwind, das lange das K\xf6nigreich Azeroth hie\xdf.","Die ber\xfchmteste W\xe4chterin war Aegwynn, die in Nordend einen Avatar des Sargeras selbst niederstreckte und seinen K\xf6rper in einem Grab unter dem Meer versiegelte. Sie ahnte nie, dass der Geist des dunklen Titanen in sie geschl\xfcpft war. Als sie einen Sohn gebar, Medivh, ging der Geist auf ihn \xfcber, und der letzte W\xe4chter wuchs mit einem Verr\xe4ter in seiner Seele heran. Von seinem Turm Karazhan aus sollte er eines Tages den Orcs die T\xfcr \xf6ffnen."]},"chapter:war-of-the-three-hammers":{title:"Der Krieg der drei H\xe4mmer",summary:"Die drei Zwergenclans von Eisenschmiede k\xe4mpften um den Thron, und ein besiegter Zauberthan beschwor Ragnaros, der das Land zum Schwarzfels verbrannte.",when:"Etwa 230 Jahre vor dem Dunklen Portal",body:["Unter dem Schnee von Dun Morogh schlugen die Zwerge Eisenschmiede in den Fels, ein K\xf6nigreich aus Stein und Handwerk, das seine Wurzeln auf die Irdenen der Titanen zur\xfcckf\xfchrte. Drei Clans teilten es sich in unruhiger Eintracht: die Bronzebarts, die Wildhammerzwerge und die zauberverliebten Dunkeleisenzwerge. Als Hochk\xf6nig Modimus Ambossar etwa 230 Jahre vor dem Dunklen Portal starb, entlud sich ihre Rivalit\xe4t in einem B\xfcrgerkrieg.","Die Bronzebarts siegten und vertrieben die anderen. Die Wildhammerzwerge erbauten Grim Batol im Osten, und die Dunkeleisenzwerge gr\xfcndeten im S\xfcden ein eigenes K\xf6nigreich im Rotkammgebirge. Zauberthan Thaurissan konnte die Niederlage nicht hinnehmen. Er griff beide Rivalen zugleich an, doch seine Heere wurden zerschlagen, und seine Frau Modgud fiel bei Grim Batol.","In seiner Verzweiflung griff Thaurissan nach einer gr\xf6\xdferen Macht und beschwor Ragnaros den Feuerf\xfcrsten, einen Elementarf\xfcrsten, den die Titanen eingekerkert hatten. Die Ankunft des Feuerf\xfcrsten t\xf6tete den Than, riss das Land zur Sengenden Schlucht und zur Brennenden Steppe auf und lie\xdf den Schwarzfels emporsteigen, in dem die \xfcberlebenden Dunkeleisenzwerge seine Sklaven wurden. Die Wildhammerzwerge verlie\xdfen das verfluchte Grim Batol und zogen ins Hinterland. Ihre gnomischen Nachbarn, deren Stadt Gnomeregan ganz in der N\xe4he lag, wurden zu treuen Freunden von Eisenschmiede."]},"chapter:corruption-of-the-orcs":{title:"Die Verderbnis der Orcs",summary:"Auf dem fernen Draenor verwandelte Kil'jaeden die schamanistischen Orcclans in eine blutr\xfcnstige Horde, gebunden durch D\xe4monenblut.",when:"Die Jahrzehnte vor dem Dunklen Portal",body:["Auf der Welt Draenor lebten die Orcs als stolze Clans von J\xe4gern und Schamanen, die ihre Ahnen und die Geister der Elemente ehrten. Sie teilten ihre Welt in unruhigem Nebeneinander mit den Draenei, den Eredar, die mit Velen von Argus geflohen waren. Kil'jaeden hatte nie aufgeh\xf6rt, diese Verbannten zu jagen, und in den Orcs sah er eine Waffe.","Als Geist von Ner'zhuls verstorbener Frau verkleidet, fl\xfcsterte der D\xe4monenf\xfcrst dem alten Schamanen ein und brachte ihn gegen die Draenei auf. Als Ner'zhul z\xf6gerte, fand Kil'jaeden in Gul'dan einen willigeren Sch\xfcler, der den geheimen Schattenrat gr\xfcndete und die Orcs Teufelsmagie lehrte; sie waren die ersten Hexenmeister. Die Elemente verstummten, und das gr\xfcne Land der Orcs begann zu sterben.","Bei einer gro\xdfen Versammlung tranken die Clanh\xe4uptlinge das Blut des Grubenlords Mannoroth, und Grom H\xf6llschrei vom Kriegshymnenklan trank als Erster. Erf\xfcllt von d\xe4monischer Raserei fiel die vereinte Horde \xfcber die Draenei her und l\xf6schte sie beinahe aus. Nur Durotans Frostwolfklan hielt sich teilweise abseits. Als das Morden vor\xfcber war, brauchte Gul'dan einen neuen Krieg, und Kil'jaedens Meister hielt bereits einen auf Azeroth bereit."]},"chapter:the-first-war":{title:"Das Dunkle Portal und der Erste Krieg",summary:"Medivh half den Orcs, das Dunkle Portal zu \xf6ffnen, und die Horde \xfcberrannte das K\xf6nigreich Sturmwind.",when:"Jahr 0: Das Dunkle Portal \xf6ffnet sich",body:["Vom besessenen Medivh geleitet, \xf6ffneten Gul'dans Hexenmeister und der W\xe4chter einen Riss zwischen Draenor und Azeroth im Schwarzen Morast, dem Sumpf, der sp\xe4ter zu den Verw\xfcsteten Landen verdorrte. Orcs str\xf6mten durch das, was als das Dunkle Portal bekannt wurde, und ihre Sp\xe4her fanden bald die reichen Felder des K\xf6nigreichs Azeroth, des heutigen Sturmwind.","K\xf6nig Llane Wrynn und sein Streiter Anduin Lothar wehrten sich jahrelang. Medivhs eigener Lehrling Khadgar entdeckte den Verrat seines Meisters und stellte den W\xe4chter zusammen mit Lothar und der Halborcin Garona in Karazhan, wo sie ihn t\xf6teten. Der Sieg kam zu sp\xe4t. Die Kriegstrupps der Horde brannten sich ihren Weg durch das K\xf6nigreich, und innerhalb der Horde st\xfcrzte der gerissene Orgrim Schicksalshammer Schwarzfaust und wurde Kriegsh\xe4uptling.","Garona, durch Gul'dans Zauber gebunden, ermordete K\xf6nig Llane, und die Stadt Sturmwind fiel und brannte. Lothar sammelte die \xdcberlebenden, unter ihnen Llanes jungen Sohn Varian, und f\xfchrte sie \xfcber das Meer nach Lordaeron. Weit im Osten, in den Riverglades, einer Region, die es nur in Forever gibt, machte die Horde den Ort Sunnyglade dem Erdboden gleich und verschleppte seine \xdcberlebenden als Sklaven."]},"chapter:the-second-war":{title:"Der Zweite Krieg",summary:"Die Menschenk\xf6nigreiche, Elfen, Zwerge und Gnome vereinten sich zur Allianz von Lordaeron und zerschlugen Schicksalshammers Horde an der Schwarzfelsspitze.",when:"Etwa f\xfcnf bis sechs Jahre nach dem Dunklen Portal",body:["Lothars Warnung bewog K\xf6nig Terenas Menethil von Lordaeron, die Menschenk\xf6nigreiche zusammenzurufen. Sie bildeten die Allianz von Lordaeron mit Lothar als oberstem Befehlshaber; die Zwerge von Eisenschmiede, die Gnome und, ihrem alten Eid an Arathors Blutlinie getreu, die Hochelfen von Quel'Thalas schlossen sich ihnen an. Um den Soldaten Hoffnung zu geben, gr\xfcndete Erzbischof Alonsus Faol die Ritter der Silbernen Hand, die ersten Paladine, mit Uther dem Lichtbringer an ihrer Spitze.","Auch Schicksalshammers Horde war gewachsen. Oger, Amanitrolle unter Zul'jin und Goblinsprengmeister k\xe4mpften an der Seite der Orcs; der Drachenmalclan nutzte Todesschwinges Drachenseele, um bei Grim Batol rote Drachen zu versklaven; Gul'dan erschuf die ersten Todesritter. Die Horde \xfcberrannte Khaz Modan, brannte Teile von Quel'Thalas nieder und belagerte Lordaerons Hauptstadt.","Im entscheidenden Moment verriet Gul'dan Schicksalshammer und segelte davon, um das Grabmal des Sargeras emporzuheben, und nahm zwei Clans mit sich, die Stormreaver und den Schattenhammer. Die geschw\xe4chte Horde zog sich zum Schwarzfels zur\xfcck. In der Schlacht an der Schwarzfelsspitze t\xf6tete Schicksalshammer Lothar, doch Lothars Leutnant Turalyon zerschlug die Horde, und Khadgar zerst\xf6rte das Dunkle Portal. Die \xfcberlebenden Orcs wurden in Internierungslager getrieben. In den Riverglades von Forever fanden Oger des Schattenhammers und Orcs der Stormreaver, die vor dem Grabmal flohen, eine neue Heimat."]}}},1721,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"chapters2",{enumerable:!0,get:function(){return n}});const n={"chapter:beyond-the-dark-portal":{title:"Jenseits des Dunklen Portals",summary:"Ner'zhul \xf6ffnete das Portal erneut und riss Draenor in St\xfccke, und Kil'jaeden formte den alten Schamanen zum Lichk\xf6nig um.",when:"Kurz nach dem Zweiten Krieg",body:["Nach Gul'dans Tod, und w\xe4hrend die Horde gefangen sa\xdf, sammelte der alte Ner'zhul die Orcs, die auf Draenor geblieben waren. Er \xf6ffnete das Dunkle Portal erneut und schickte Pl\xfcnderer nach Azeroth, um m\xe4chtige Artefakte zu stehlen, in der Hoffnung, Tore zu neuen Welten zu \xf6ffnen, in die sein Volk entkommen konnte.","Die Allianz antwortete mit einer Expedition durch das Portal unter Turalyon und Khadgar, zu der die Waldl\xe4uferin Alleria Windl\xe4ufer, der Zwerg Kurdran Wildhammer und der Krieger Danath Trollbann stie\xdfen. Sie bek\xe4mpften die neue Horde \xfcberall auf Draenor, doch Ner'zhuls Portale zerrissen die Welt bereits. Um Azeroth zu retten, zerst\xf6rte die Expedition das Dunkle Portal von der anderen Seite aus und schloss sich selbst in den zerschmetterten \xdcberresten ein, aus denen die Scherbenwelt werden sollte.","Ner'zhul entkam durch einen seiner Risse, geradewegs in die H\xe4nde Kil'jaedens. Der D\xe4mon riss ihm den K\xf6rper fort, behielt aber seinen Geist, band ihn in eine verzauberte R\xfcstung und versiegelte ihn zusammen mit der Runenklinge Frostgram in einem Eisblock. In die gefrorene \xd6dnis Nordends geschleudert, wurde der Frostthron zum Sitz einer neuen Macht: des Lichk\xf6nigs, dessen Aufgabe es war, eine Seuche des Untods zu verbreiten und Azeroth f\xfcr die R\xfcckkehr der Legion m\xfcrbe zu machen."]},"chapter:thrall-and-the-new-horde":{title:"Thrall und die neue Horde",summary:"Ein als Sklave aufgezogener Orc entkam aus Durnholde, entdeckte den Schamanismus neu und befreite sein Volk aus den Internierungslagern.",when:"Die Jahre vor dem Dritten Krieg",body:["In den Internierungslagern versanken die Orcs in einer seltsamen Lethargie, w\xe4hrend die d\xe4monische Raserei aus ihnen wich. Lord Aedelas Schwarzmoor von Burg Durnholde im Vorgebirge des H\xfcgellands hatte Jahre zuvor einen verwaisten Orcs\xe4ugling gefunden und ihn als Gladiator und k\xfcnftige Waffe aufgezogen. Er nannte den Jungen Thrall, ein Wort f\xfcr Sklave. Nur Taretha Foxton, eine Dienstmagd, begegnete ihm mit Freundlichkeit, und mit ihrer Hilfe gelang Thrall schlie\xdflich die Flucht.","Zum ersten Mal frei, suchte Thrall nach den Legenden seines eigenen Volkes. Grom H\xf6llschrei zeigte ihm, was ein Orc sein konnte, der betagte Orgrim Schicksalshammer machte ihn zu seinem Stellvertreter, und beim Frostwolfklan im Alteracgebirge lehrte ihn der Schamane Drek'Thar, mit den Elementen zu sprechen. Dort erfuhr er, dass er der Sohn Durotans war, des H\xe4uptlings der Frostw\xf6lfe.","Thrall, Grom und Schicksalshammer befreiten ein Lager nach dem anderen. Schicksalshammer fiel im Kampf und \xfcbergab Thrall seine schwarze R\xfcstung und seinen Hammer; Thrall wurde Kriegsh\xe4uptling einer neuen Horde, die auf Ehre und Schamanismus statt auf D\xe4monenblut gebaut war. Bei Durnholde besiegte er Schwarzmoor, doch Taretha \xfcberlebte nicht. Nun wollte Thrall nur noch eine Heimat, in der sein Volk in Frieden leben konnte."]},"chapter:the-lich-king-and-the-plague":{title:"Der Lichk\xf6nig und die Seuche",summary:"Von Nordend aus griff der Lichk\xf6nig nach S\xfcden, und der Erzmagier Kel'Thuzad verbreitete mit Lordaerons Getreide eine Seuche des Untods.",when:"Im Vorfeld des Dritten Krieges",body:["Obwohl er im Frostthron gefangen war, reichte der Geist des Lichk\xf6nigs \xfcber ganz Nordend. Er eroberte das Spinnenk\xf6nigreich Azjol-Nerub, erhob dessen Volk zu Dienern und errichtete in Eiskrone eine Festung um seinen Thron. Dann richtete er seinen Blick nach S\xfcden, auf die kriegsm\xfcden Menschenk\xf6nigreiche.","In Dalaran war der angesehene Erzmagier Kel'Thuzad der Nekromantie verfallen. Als die Kirin Tor seine Studien verwarfen, folgte er dem Ruf des Lichk\xf6nigs, reiste nach Nordend und kehrte als dessen Prophet zur\xfcck. Er gr\xfcndete den Kult der Verdammten, der den Armen Lordaerons Gleichheit und ewiges Leben versprach, und nutzte dessen Anh\xe4nger, um eine in Getreidelieferungen versteckte Seuche zu verbreiten.","Die Seuche t\xf6tete ihre Opfer und erhob sie dann als willenlose Untote, die Gei\xdfel. D\xf6rfer im Norden Lordaerons fielen eines nach dem anderen, w\xe4hrend die K\xf6nigreiche \xfcber Steuern und die Kosten der Internierungslager stritten. Als die Kirin Tor und die Silberne Hand die Gefahr begriffen, hatte sich die Seuche bereits \xfcber die n\xf6rdlichen Provinzen Lordaerons ausgebreitet. Schreckensf\xfcrsten der Brennenden Legion wachten \xfcber das Werk des Lichk\xf6nigs, denn es sollte ihren Meistern den Weg f\xfcr ihre R\xfcckkehr bereiten."]},"chapter:fall-of-lordaeron":{title:"Der Fall von Lordaeron",summary:"Prinz Arthas verfolgte die Seuche bis zu ihrem Ursprung, nahm Frostgram an sich und kehrte zur\xfcck, um sein eigenes K\xf6nigreich, Quel'Thalas und Dalaran zu vernichten.",when:"Der Dritte Krieg, etwa 20 Jahre nach dem Dunklen Portal",body:["Prinz Arthas Menethil, ein junger Paladin der Silbernen Hand, zog mit der Zauberin Jaina Prachtmeer aus, um die Seuche aufzuhalten. In Stratholme stellte er fest, dass das Getreide der Stadt bereits verseucht war, und befahl, die Bewohner zu t\xf6ten, bevor sie sich als Untote erheben konnten. Uther und Jaina weigerten sich, ihm zu folgen. Arthas verfolgte den Schreckensf\xfcrsten Mal'Ganis bis nach Nordend, verbrannte seine eigenen Schiffe, damit seine M\xe4nner nicht abziehen konnten, und nahm die Runenklinge Frostgram an sich. Das Schwert raubte ihm die Seele.","Arthas kehrte als Todesritter des Lichk\xf6nigs heim und ermordete seinen Vater, K\xf6nig Terenas, in dessen eigenem Thronsaal. Die Gei\xdfel \xfcberrollte Lordaeron. Uther fiel bei der Verteidigung der Urne mit Terenas' Asche, und Arthas f\xfchrte sein Heer nach Quel'Thalas, durchbrach die Verteidigung der Elfen und nutzte den Sonnenbrunnen, um Kel'Thuzad als Lich wiederzuerwecken. Sylvanas Windl\xe4ufer, die Waldl\xe4ufergeneralin von Silbermond, starb im Kampf gegen ihn und wurde als Banshee erhoben.","Kel'Thuzad beschwor daraufhin in Dalaran den D\xe4monenf\xfcrsten Archimonde, und die Brennende Legion kehrte nach Azeroth zur\xfcck. Dalaran wurde zerschmettert, und Lordaeron, das gr\xf6\xdfte Menschenk\xf6nigreich, war verloren. Im Norden blieben nur verstreute \xdcberlebende, Fl\xfcchtlinge und Eiferer zur\xfcck, w\xe4hrend Arthas' Untote das Land beherrschten."]},"chapter:battle-for-mount-hyjal":{title:"Die Schlacht um den Berg Hyjal",summary:"Von einem Propheten gewarnt, segelten Orcs und Menschen nach Kalimdor, wo sie sich mit den Nachtelfen verb\xfcndeten, um Archimonde am Weltenbaum aufzuhalten.",when:"Das Ende des Dritten Krieges",body:["Ein geheimnisvoller Prophet, der von den Toten zur\xfcckgekehrte Medivh, dr\xe4ngte Thrall und Jaina, westw\xe4rts nach Kalimdor zu segeln. Thralls Horde landete an seinen K\xfcsten, schloss Freundschaft mit den Tauren von Cairne Bluthuf und k\xe4mpfte sich durch das Brachland, und Jaina f\xfchrte Fl\xfcchtlinge aus Lordaeron auf denselben Kontinent. In den W\xe4ldern des Eschentals tranken Grom H\xf6llschrei und sein Kriegshymnenklan erneut D\xe4monenblut und t\xf6teten den Halbgott Cenarius.","Thrall und Jaina arbeiteten zum ersten Mal zusammen, um Grom zu retten. In einem letzten Zweikampf erschlug Grom Mannoroth und befreite die Orcs um den Preis seines eigenen Lebens vom Blutfluch. Unterdessen weckte Tyrande Wisperwind die Druiden und befreite Illidan aus den Barrow Deeps, in der Hoffnung, seine Macht w\xfcrde helfen. Stattdessen verschlang er den Sch\xe4del von Gul'dan, wurde zum Halbd\xe4mon und von seinem eigenen Bruder verbannt.","Archimonde marschierte auf Nordrassil zu, um ihm seine Macht zu entziehen. Nachtelfen, Menschen und Orcs hielten gemeinsam die H\xe4nge des Berges Hyjal und gewannen Zeit, w\xe4hrend Malfurion eine Falle vorbereitete. Als der D\xe4mon den Baum erreichte, st\xfcrzten sich Tausende Irrwische auf ihn, und die Macht Nordrassils zerriss ihn. Das Heer der Legion war zerschlagen, doch der Weltenbaum war schwer verwundet, und die Nachtelfen verloren die Unsterblichkeit, die er ihnen geschenkt hatte."]},"chapter:rise-of-the-forsaken":{title:"Die Verlassenen erheben sich",summary:"Als der Lichk\xf6nig schw\xe4cher wurde, riss sich Sylvanas Windl\xe4ufer mit anderen Untoten los und beanspruchte die Ruinen Lordaerons als die Verlassenen.",when:"Kurz nach dem Dritten Krieg",body:["Nach Archimondes Fall begann der Griff des Lichk\xf6nigs zu erlahmen. Illidan, nun im Dienst Kil'jaedens, griff den Frostthron an, und Arthas eilte nach Norden, um seinen Meister zu verteidigen. In Lordaeron versuchten die Schreckensf\xfcrsten, die Gei\xdfel f\xfcr sich selbst an sich zu rei\xdfen, und im Chaos gewannen viele Untote ihren eigenen Willen zur\xfcck.","Sylvanas Windl\xe4ufer war die Erste. Mit ihren Banshees und anderen freien Untoten, und mit dem Schreckensf\xfcrsten Varimathras, den sie in ihre Dienste zwang, besiegte sie ihre Rivalen und beanspruchte die zerst\xf6rte Hauptstadt Lordaerons. Darunter lagen die alten k\xf6niglichen Gr\xfcfte und Abwasserkan\xe4le, aus denen Unterstadt wurde. Ihr Volk nannte sich die Verlassenen: nicht mehr menschlich, von den Lebenden verschm\xe4ht und frei vom Lichk\xf6nig.","Arthas erreichte Eiskrone, setzte den Helm des Lichk\xf6nigs auf und verschmolz auf dem Frostthron mit ihm; dann verstummte er hinter dem Eis. Die von Feinden umringten Verlassenen schlossen sich Thralls Horde als unbequeme Verb\xfcndete an, w\xe4hrend die Gei\xdfel, der Scharlachrote Kreuzzug und die Reste von Lordaerons Adel um die Pestl\xe4nder k\xe4mpften. Die Geschichte von Forever setzt nach der Kampagne \u201eForsaken Kingdom\u201c aus Warcraft III: Reforged an, deren Ereignisse dieser Leitfaden noch nicht behandelt."],unknowns:["Was in der Kampagne \u201eForsaken Kingdom\u201c aus Warcraft III: Reforged geschieht, an die Forever ankn\xfcpft, beschreiben die Quellen dieses Leitfadens nicht."]},"chapter:durotar-and-theramore":{title:"Durotar und Theramore",summary:"Thrall gr\xfcndete Durotar und Orgrimmar, Jaina erbaute Theramore, und beide wahrten einen zerbrechlichen Frieden, selbst als Jainas Vater kam, um Krieg zu f\xfchren.",when:"Die Jahre nach dem Dritten Krieg",body:["Nach dem Hyjal f\xfchrte Thrall die Orcs in ein raues rotes Land an der Ostk\xfcste Kalimdors und benannte es nach seinem Vater Durotar. Ihre Hauptstadt Orgrimmar ehrte Orgrim Schicksalshammer. Die Tauren von Cairne Bluthuf siedelten im Grasland von Mulgore rund um die Tafelberge von Donnerfels, und die Dunkelspeertrolle von Vol'jin, die Thrall auf seiner Reise nach Westen gerettet hatte, lie\xdfen sich auf den Echoinseln vor Durotars K\xfcste nieder.","Jaina Prachtmeer gr\xfcndete Theramore auf einer Insel in den D\xfcstermarschen f\xfcr die menschlichen \xdcberlebenden, die sie aus Lordaeron mitgebracht hatte. Sie und Thrall hatten am Hyjal Seite an Seite gek\xe4mpft und vereinbarten, den Frieden zu wahren. Dieser Frieden wurde auf die Probe gestellt, als ihr Vater, Lordadmiral Daelin Prachtmeer von Kul Tiras, mit seiner Flotte eintraf, fest entschlossen, die Orcs zu vernichten.","Daelin griff Durotars K\xfcste an. Rexxar, ein halbogerischer Wanderer der Mok'Nathal, der zum Streiter der Horde wurde, vereinte Orcs, Trolle und Tauren gegen ihn, und Jaina, hin- und hergerissen zwischen ihrem Volk und ihrem Vater, lie\xdf die Horde seine Truppen bei Theramore angreifen. Daelin fiel in der Schlacht. Jaina betrauerte ihn, hielt aber ihr Wort, und der br\xfcchige Waffenstillstand zwischen Theramore und Orgrimmar wurde zu einer der wenigen Br\xfccken zwischen Allianz und Horde."]},"chapter:stormwind-in-shadow":{title:"Sturmwind im Schatten",summary:"Das wiederaufgebaute Sturmwind steht einer betrogenen Steinmetzgilde, einem verschwundenen K\xf6nig und einem Drachen am Hof gegen\xfcber, w\xe4hrend die Gnome ihre Stadt verloren haben.",when:"Jahr 25 nach dem Dunklen Portal",body:["Nach dem Zweiten Krieg baute die Steinmetzgilde unter Edwin van Cleef die Stadt Sturmwind aus der Asche wieder auf. Als die Arbeit getan war, weigerte sich das Haus der Adligen, sie zu bezahlen. Die Steinmetze rebellierten, wurden vertrieben und wurden zur Defiasbruderschaft, die nun aus versteckten Minen heraus Westfall heimsucht und gegen die Krone intrigiert.","K\xf6nig Varian Wrynn, der Junge, den Lothar einst gerettet hatte, verschwand auf dem Weg zu einem diplomatischen Treffen in Theramore; Ger\xfcchten zufolge verschleppten ihn die Defias und hielten ihn auf Alcaz Island fest. Sein junger Sohn Anduin wurde gekr\xf6nt, mit Hochlord Bolvar Fordragon als Regent. Bei Hofe gewann eine anmutige Adlige, Lady Katrana Prestor, gro\xdfen Einfluss. In Wahrheit war sie Onyxia, die Tochter Todesschwinges, die das K\xf6nigreich still dem Ruin entgegensteuerte.","Die Allianz hat sich ver\xe4ndert. Lordaeron ist verloren, und die Nachtelfen schlossen sich nach dem Hyjal der Allianz an. In Dun Morogh quollen Troggs aus der Tiefe und \xfcberrannten Gnomeregan; der verzweifelte Versuch der Gnome, sie mit Strahlung auszur\xe4uchern, vergiftete ihre eigene Stadt, und Hocht\xfcftler Mekkadrill f\xfchrte die \xdcberlebenden in den Schutz von Eisenschmiede. Dort herrscht K\xf6nig Magni Bronzebart, und seine Forscherliga gr\xe4bt auf der ganzen Welt nach den Geheimnissen der Titanen."]},"chapter:fire-beneath-blackrock":{title:"Feuer unter dem Schwarzfels",summary:"Im Schwarzfels dienen die Dunkeleisenzwerge Ragnaros, w\xe4hrend Nefarians Orcs die Spitze dar\xfcber halten, und Onyxia bewacht ihre Brut in den D\xfcstermarschen.",when:"Jahr 25 nach dem Dunklen Portal",body:["Zwei Jahrhunderte nach Thaurissans Fehler herrschen seine Nachfahren noch immer im Schwarzfels. Imperator Dagran Thaurissan h\xe4lt Hof in der Dunkeleisenstadt Schattenschmiede tief in den Schwarzfelstiefen, w\xe4hrend Ragnaros darunter im Geschmolzenen Kern brennt und die Zwerge f\xfcr ihn schuften. Prinzessin Moira Bronzebart, die Tochter K\xf6nig Magnis, kam als Gefangene in den Berg und blieb als Gemahlin des Imperators, zum Zorn ihres Vaters.","Die oberen Hallen geh\xf6ren dem schwarzen Drachenschwarm. Nefarian, Todesschwinges Sohn, herrscht in der Gestalt von Lord Victor Nefarius \xfcber den Pechschwingenhort und befehligt die Orcs des Schwarzfelsklans, die sich Thrall nie anschlossen, angef\xfchrt von Kriegsh\xe4uptling Rend Schwarzfaust in der Schwarzfelsspitze. Feuer und Schatten f\xfchren im selben Berg einen kalten Krieg, und die Brennende Steppe und die Sengende Schlucht leiden darunter.","Nefarians Schwester Onyxia, die falsche Lady Prestor, hat ihren Hort in den D\xfcstermarschen, wo sie ihre Brut bewacht. Um zu ihr zu gelangen, braucht man das Drachenfeueramulett, das man sich in einer langen Questreihe jeder Fraktion verdient, die durch die Schwarzfelsspitze f\xfchrt. In Forever ist Onyxias Hort einer von drei Schlachtz\xfcgen, die am 9. Dezember \xf6ffnen, neben zwei neuen Schlachtz\xfcgen am Berg Hyjal."]},"chapter:plaguelands-and-the-scarlet-crusade":{title:"Die Pestl\xe4nder und der Scharlachrote Kreuzzug",summary:"Kel'Thuzads Gei\xdfel h\xe4lt den Norden, Eiferer des Scharlachroten Kreuzzugs bek\xe4mpfen Untote wie Lebende, und einige standhafte Orden halten die Stellung.",when:"Jahr 25 nach dem Dunklen Portal",body:["Lordaerons Kernland sind heute die Pestl\xe4nder. Kel'Thuzad befehligt dort die Gei\xdfel von der schwebenden Nekropole Naxxramas aus, Baron Totenschwur herrscht \xfcber die Untoten im zerst\xf6rten Stratholme, und in der alten Schule der Familie Barov, der Scholomance, bildet der Kult der Verdammten neue Nekromanten aus.","\xdcberlebende der Silbernen Hand sammelten sich neu als Scharlachroter Kreuzzug, der geschworen hat, die Seuche aus dem Land zu brennen. Ihr Gro\xdfkreuzfahrer Saidan Dathrohan ist insgeheim der Schreckensf\xfcrst Balnazzar, und der Kreuzzug ist so fanatisch geworden, dass er jeden Au\xdfenstehenden t\xf6tet, den er der Verseuchung verd\xe4chtigt. Zu seinen Hochburgen geh\xf6ren das Scharlachrote Kloster in Tirisfal, Herdweiler, Tyrs Hand und eine Bastion in Stratholme. Selbst seine Helden tragen dunklere Geschichten: Renault Mograine lieferte seinen Vater Alexandros, den Aschenbringer, durch Verrat dem Tod aus.","Nicht jeder Paladin wurde zum Eiferer. Wer die Grausamkeit des Kreuzzugs ablehnte, gr\xfcndete die Argentumd\xe4mmerung, die von der Kapelle des Hoffnungsvollen Lichts aus mit jedem zusammenarbeitet, der die Gei\xdfel bek\xe4mpft. Der verbannte Paladin Tirion Fordring lebt als Einsiedler nahe Herdweiler, und die Verlassenen dr\xe4ngen von Tirisfal aus nach Norden. Das Schicksal Lordaerons ist noch nicht entschieden."]},"chapter:azeroth-in-year-twenty-five":{title:"Azeroth im Jahr 25",summary:"Die Welt im ersten Jahr von World of Warcraft, in der die Geschichte von Forever spielt: ein zerbrechlicher Frieden, alte Bedrohungen, die sich regen, und neue Orte auf der Karte.",when:"Jahr 25: die Zeit von Forever",body:["F\xfcnfundzwanzig Jahre nachdem sich das Dunkle Portal zum ersten Mal \xf6ffnete, ist Azeroth eine Welt von \xdcberlebenden. Die Allianz aus Sturmwind, Eisenschmiede, den Gnomen und den Nachtelfen steht einer Horde aus Orcs, Trollen, Tauren und Verlassenen gegen\xfcber, und keine Seite traut der anderen. An den R\xe4ndern der Karte erwachen alte Feinde: Diener des Alten Gottes C'Thun in Silithus, Priester des Blutgottes Hakkar in den Trollruinen des S\xfcdens und die Verderbnis des Smaragdgr\xfcnen Alptraums, die in die Tr\xe4ume der Druiden kriecht.","World of Warcraft: Forever spielt genau in diesem Moment. Blizzard h\xe4lt es dort auf unbestimmte Zeit, nach der Kampagne \u201eForsaken Kingdom\u201c aus Warcraft III: Reforged und vor The Burning Crusade, und erkl\xe4rt, dass seine Geschichte nicht die Kontinuit\xe4t des aktuellen World of Warcraft teilt. Forever f\xfcgt Orte hinzu, die das urspr\xfcngliche Spiel nie hatte: die Riverglades \xf6stlich des \xd6dlands, wo Farholde Keep dem Schattenhammer standh\xe4lt; ein Dalaran im Wiederaufbau, dessen verbergende Barriere gefallen ist; und Dungeons von den K\xf6nigsgr\xe4bern der Hall of Thanes bis zur Titanenanlage Shaper's Terrace.","Forever \xf6ffnet den Spielern au\xdferdem ein neues Volk: die Skyborne von Zephras Isle, einer Insel, die in Skywall schwebt, der Elementarebene der Luft. Ihre Luftelementare verschwanden vor Jahrhunderten, und die Magie, die die Insel in der H\xf6he h\xe4lt, schwindet; ihr High Order dient der Allianz, ihre Windshaper der Horde. Wie diese Geschichten enden, wird noch geschrieben. Blizzard hat neue Schlachtz\xfcge, Dungeons und eine legend\xe4re Questreihe f\xfcr 2027 angek\xfcndigt, und die Schlachtz\xfcge des Berges Hyjal \xf6ffnen am 9. Dezember."]},"chapter:after-classic":{title:"Epilog: Nach Classic",summary:"In der urspr\xfcnglichen Zeitlinie ging die Geschichte weiter, durch die Scherbenwelt, Nordend und dar\xfcber hinaus; Forever bleibt im Jahr 25 und erz\xe4hlt seine eigene.",when:"Sp\xe4tere Erweiterungen (nicht Teil von Forever)",body:["In der urspr\xfcnglichen Zeitlinie von World of Warcraft ging die Geschichte weiter. Das Dunkle Portal \xf6ffnete sich erneut, und The Burning Crusade f\xfchrte Abenteurer in die Scherbenwelt, wo Illidan und Kael'thas Sonnenwanderer fielen. In Wrath of the Lich King marschierten Allianz und Horde nach Nordend, und Arthas wurde auf der Eiskronenzitadelle besiegt. In Cataclysm brach Todesschwinge aus den Tiefen hervor und zerschmetterte das Antlitz der Welt, bevor die Aspekte und ihre sterblichen Verb\xfcndeten ihn niederstreckten.","Sp\xe4tere Erweiterungen f\xfchrten die Saga nach Pandaria, auf ein alternatives Draenor, zur endg\xfcltigen Niederlage der Brennenden Legion auf Argus, in den offenen Krieg zwischen den Fraktionen, in die Reiche der Toten, auf die Dracheninseln und in den langen Kampf um Azeroths eigene Weltenseele. Viele Orte in diesem Leitfaden ver\xe4nderten sich dabei bis zur Unkenntlichkeit.","World of Warcraft: Forever schl\xe4gt keinen dieser Wege ein. Es bleibt im Jahr 25, in einer \u201eZeitblase\u201c au\xdferhalb der Kontinuit\xe4t des aktuellen World of Warcraft, und baut seine Zukunft auf den Fundamenten der urspr\xfcnglichen Welt. Blizzards Fahrplan verspricht f\xfcr 2027 neue Schlachtz\xfcge, Dungeons, Quests und einen \xfcberarbeiteten ikonischen Schlachtzug, sodass die n\xe4chsten Kapitel dieser Geschichte Forever allein geh\xf6ren werden."]}}},1722,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"classes",{enumerable:!0,get:function(){return n}});const n={"class:mage":{title:"Magier",summary:"Erben der Hochgeborenen und der ersten menschlichen Magier: Magier formen rohe arkane Macht, und jedes Zeitalter der Geschichte h\xe4ngt an einem von ihnen.",body:["Magier wirken das Arkane, die rohe Magie der Ordnung, die einst aus dem Brunnen der Ewigkeit quoll. Die Hochgeborenen der Nachtelfen waren die ersten gro\xdfen Zauberer, und ihre verbannten Nachfahren, die Hochelfen von Quel'Thalas, lehrten die Kunst w\xe4hrend der Trollkriege hundert Menschen. Diese ersten menschlichen Magier gr\xfcndeten sp\xe4ter Dalaran, wo die Kirin Tor bis heute die Geheimnisse der Zauberkunst h\xfcten.","Jedes Zeitalter der Geschichte h\xe4ngt an einem Magier: Medivh, dem letzten W\xe4chter; seinem Lehrling Khadgar, der das Dunkle Portal zerst\xf6rte; Erzmagier Antonidas, der bei der Verteidigung Dalarans starb; und Jaina Prachtmeer, die heute \xfcber Theramore herrscht. Im Jahr 25 lernen neue Sch\xfcler im Magierviertel von Sturmwind und im Magieviertel von Unterstadt, und gnomische und trollische Magier stehen l\xe4ngst an der Seite von Menschen und Verlassenen. Forever \xf6ffnet den Weg f\xfcr Orcs, deren Zauberwirker einst nur Schamanismus und Teufelsmagie kannten, und f\xfcr den High Order, die einzigen Skyborne, die Magier werden k\xf6nnen."]},"class:warrior":{title:"Krieger",summary:"Jedes Volk Azeroths hat seine Krieger, und ein Gro\xdfteil der Geschichte der Welt wurde mit ihrem Stahl geschrieben.",body:["Jedes Volk Azeroths hat seine Krieger, und ein Gro\xdfteil seiner Geschichte wurde mit ihrem Stahl geschrieben. Die Soldaten Arathors hielten Thoradins Wall gegen die Amani; Zwergenthane k\xe4mpften im Krieg der drei H\xe4mmer f\xfcr Eisenschmiede; Orcclans lebten von der St\xe4rke ihrer Streiter, lange bevor die Horde geschmiedet wurde. Krieger vertrauen auf Ausbildung, R\xfcstung und den Zorn der Schlacht statt auf Zauber.","Ihre Helden f\xfcllen die Chroniken: Anduin Lothar, der L\xf6we von Azeroth, der die Allianz f\xfchrte, bis er an der Schwarzfelsspitze fiel; Grom H\xf6llschrei, dessen Opfer am Berg Hyjal die Orcs vom D\xe4monenblut befreite; und Danath Trollbann, der mit der Expedition der Allianz auf Draenor zur\xfcckblieb. Im Jahr 25 dienen Krieger unter jedem Banner, von den Wachen Sturmwinds bis zu den Grunzern Orgrimmars, und jedes spielbare Volk kann zu den Waffen greifen. Forever f\xfcgt ihren Reihen die Skyborne beider Orden hinzu."]},"class:paladin":{title:"Paladin",summary:"Heilige Krieger, im Zweiten Krieg entstanden: Die Paladine der Silbernen Hand wurden von einem der Ihren zerschlagen und k\xe4mpfen heute unter neuen Bannern weiter.",body:["Paladine sind Kriegerpriester des Heiligen Lichts. Erzbischof Alonsus Faol gr\xfcndete ihren Orden, die Ritter der Silbernen Hand, w\xe4hrend des Zweiten Krieges, um der Allianz Streiter zu geben, die heilen ebenso wie k\xe4mpfen konnten. Uther der Lichtbringer war der Erste von ihnen, und Turalyon, Tirion Fordring und Prinz Arthas Menethil legten alle den Eid ab.","Der Orden wurde von einem der Seinen zerschlagen. Arthas ermordete Uther und half, Lordaeron zu vernichten, und die \xdcberlebenden der Silbernen Hand zerstreuten sich: auf der einen Seite die Eiferer des Scharlachroten Kreuzzugs, auf der anderen die Argentumd\xe4mmerung und der verbannte Tirion. Auch die Zwerge von Eisenschmiede tragen das Licht in die Schlacht. Die \xfcberraschendste \xc4nderung in Forever ist, dass nun auch die Verlassenen Paladine werden k\xf6nnen, auch wenn die hier verwendeten Quellen noch nicht erkl\xe4ren, wie Untote dazu kamen, das Licht zu f\xfchren."],unknowns:["Wie die Paladine der Verlassenen in Forever dazu kamen, das Licht zu f\xfchren, erkl\xe4ren die Quellen dieses Leitfadens nicht."]},"class:hunter":{title:"J\xe4ger",summary:"Waldl\xe4ufer, Sch\xfctzen und Tierf\xfchrer: J\xe4ger leben vom Bogen, vom Gewehr und von der Bindung an ein treues Tier.",body:["J\xe4ger leben vom Bogen, vom Gewehr und von der Bindung an ein Tier. Die Waldl\xe4ufer von Quel'Thalas, \xfcber Generationen von der Familie Windl\xe4ufer angef\xfchrt, bewachten die W\xe4lder der Elfen; Zwergensch\xfctzen und die Greifenreiter der Wildhammerzwerge k\xe4mpften im Zweiten Krieg; Schildwachen der Nachtelfen und trollische Kopfj\xe4ger durchstreifen die W\xe4lder Kalimdors und des Schlingendorntals.","Einige der z\xe4hesten \xdcberlebenden der Geschichte sind J\xe4ger. Alleria Windl\xe4ufer zog jenseits des Dunklen Portals und kehrte nie zur\xfcck, ihre Schwester Sylvanas k\xe4mpfte bis zum letzten Atemzug gegen Arthas, und der Tierf\xfchrer Rexxar wurde zum Streiter der Horde gegen Daelin Prachtmeer. In Forever k\xf6nnen auch Menschen diesem Ruf folgen, und beide Orden der Skyborne z\xe4hlen J\xe4ger zu ihrem Volk."]},"class:rogue":{title:"Schurke",summary:"Spione, Diebe und Meuchler: Schurken handeln dort, wo die Ehre z\xf6gern w\xfcrde, und manche ihrer Gilden haben im Stillen Geschichte geschrieben.",body:["Schurken handeln dort, wo die Ehre z\xf6gern w\xfcrde. Diebe, Spione und Meuchelm\xf6rder gibt es in jeder Stadt, doch einige ihrer Organisationen pr\xe4gen die Geschichte: Sturmwinds Geheimdienst SI:7 unter Mathias Shaw; die Assassinen von Rabenholdt, versteckt im Alteracgebirge; das Syndikat, hervorgegangen aus Alteracs entehrtem Adel; und die Defiasbruderschaft, die Westfall heimsucht.","Die ber\xfchmteste Schurkin der fr\xfchen Kriege war Garona Halforcen, die Halborc-Spionin, deren Klinge K\xf6nig Llane t\xf6tete. Im Jahr 25 lehren Schurkenlehrer in der Altstadt von Sturmwind und im Schurkenviertel von Unterstadt, und jedes spielbare Volk au\xdfer den Tauren kann das Handwerk erlernen. Forever f\xfcgt den Schatten die Skyborne beider Orden hinzu."]},"class:priest":{title:"Priester",summary:"Priester dienen dem Heiligen Licht, der Mondg\xf6ttin Elune oder \xe4lteren, dunkleren M\xe4chten; sie heilen Verb\xfcndete und vernichten, wenn es sein muss, ihre Feinde.",body:["Priester dienen dem Glauben in vielen Formen. Die Kirche des Heiligen Lichts der Menschen, deren Mittelpunkt die Kathedrale des Lichts in Sturmwind ist und die einst Erzbischof Alonsus Faol f\xfchrte, lehrt, dass das Licht in der Tugend lebt statt in einem einzelnen Gott, und auch die Zwerge nahmen es an. Die Priesterinnen der Nachtelfen dienen der Mondg\xf6ttin Elune in einer Schwesternschaft, die Tyrande Wisperwind seit dem Krieg der Ahnen anf\xfchrt.","Andere gehen dunklere Wege. Priester der Verlassenen pflegen einen eigenen, d\xfcsteren Glauben, Trollpriester ehren die Loa ihrer Ahnen, und Schattenmagie geh\xf6rt zum Handwerk vieler Priester. In Forever k\xf6nnen die Gnome, lange als Volk der Ingenieure bekannt, zum ersten Mal Priester werden, und Blizzard gab ihnen eigene volksspezifische Priesterzauber."]},"class:shaman":{title:"Schamane",summary:"Schamanen bitten die Geister von Erde, Feuer, Wasser und Luft um Beistand; eine Generation lang war die Tradition den Orcs verloren, bis Thrall sie erneuerte.",body:["Schamanen sprechen mit den Geistern von Erde, Feuer, Wasser und Luft, und sie bitten, statt zu befehlen. Auf Draenor waren die Orcschamanen die Wegweiser ihres Volkes, bis Ner'zhuls Verderbnis sie durch Hexenmeister ersetzte, und eine Generation lang antworteten die Elemente den Orcs \xfcberhaupt nicht. Thrall erneuerte die Tradition, unterwiesen von Drek'Thar vom Frostwolfklan, und baute die Horde um sie herum neu auf.","Die Tauren von Mulgore und die Dunkelspeertrolle pflegen ihre eigenen schamanischen Br\xe4uche, und Thrall f\xfchrt noch immer die Schamanen von Orgrimmar. Forever f\xfcgt zwei Neulinge hinzu: Zwerge, die im urspr\xfcnglichen Spiel keine Schamanen hatten, und die Windshaper-Skyborne von Zephras Isle, deren Insel in Skywall schwebt, der Elementarebene der Luft."],unknowns:["Wie Zwerge in Forever zum Schamanismus kamen, erkl\xe4ren die Quellen dieses Leitfadens nicht."]},"class:warlock":{title:"Hexenmeister",summary:"Meister der Teufelsmagie und gebundener D\xe4monen: Hexenmeister kamen mit der Horde nach Azeroth und wandeln auf einem schmalen Grat zwischen Macht und Untergang.",body:["Hexenmeister sch\xf6pfen Macht aus Teufelsmagie und zwingen D\xe4monen unter ihren Willen. Die Kunst kam mit der Horde nach Azeroth: Kil'jaeden lehrte sie Gul'dan, dessen Schattenrat die Orcschamanen zu Hexenmeistern machte und Draenors Leben aufzehrte, um ihre Zauber zu n\xe4hren. Todesritter und der Fluch des D\xe4monenbluts geh\xf6rten zu ihren finstersten Fr\xfcchten.","Nicht jeder Hexenmeister dient der Legion. Menschliche Hexenmeister treffen sich heimlich unter der Taverne Zum Geschlachteten Lamm in Sturmwind, Gnome und Verlassene studieren die Kunst, und Thralls Horde duldet ihre orcischen Hexenmeister mit Argwohn. Jeder Hexenmeister geht denselben schmalen Grat: Die Macht ist echt, und ebenso die Gefahr, von ihr verschlungen zu werden. In Forever k\xf6nnen auch Trolle Hexenmeister werden."]},"class:druid":{title:"Druide",summary:"Gestaltwandelnde H\xfcter der Natur, zuerst vom Halbgott Cenarius unterwiesen: Druiden wahren das Gleichgewicht der Welt, von der Mondlichtung bis zum Smaragdgr\xfcnen Traum.",body:["Druiden h\xfcten das Gleichgewicht der Natur und k\xf6nnen die Gestalt von Tieren annehmen. Malfurion Sturmgrimm lernte die Kunst vom Halbgott Cenarius und wurde der erste Druide; seine Anh\xe4nger schliefen jahrhundertelang im Smaragdgr\xfcnen Traum, w\xe4hrend die Schildwachen \xfcber die W\xe4lder der Nachtelfen wachten. Der Zirkel des Cenarius, der seinen Sitz in der heiligen Mondlichtung hat, vereint heute Druiden aller V\xf6lker.","Nach dem Dritten Krieg lehrte Malfurion die Tauren die druidischen K\xfcnste, und Hamuul Runentotem wurde der erste Taurendruide. Im Jahr 25 plagen die Druiden ernste Sorgen: Der Weltenbaum Nordrassil ist verwundet, Teldrassil wuchs ohne den Segen der Aspekte, und ein Alptraum breitet sich im Smaragdgr\xfcnen Traum aus. In Forever z\xe4hlen beide Orden der Skyborne Druiden zu ihrem Volk."]}}},1723,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"races",{enumerable:!0,get:function(){return n}});const n={"race:human":{title:"Menschen",summary:"Erben Arathors und R\xfcckgrat der Allianz: Die Menschen haben f\xfcr jeden Krieg in Azeroths Geschichte bezahlt und bauen dennoch immer wieder auf.",body:["Die Menschen stammen von den St\xe4mmen ab, die K\xf6nig Thoradin fast dreitausend Jahre vor dem Dunklen Portal zu Arathor vereinte. Arathors Erben gr\xfcndeten die sieben Menschenk\xf6nigreiche, die Elfen bildeten ihre ersten Magier aus, und ihr Glaube an das Heilige Licht brachte sp\xe4ter die Paladine hervor. Die Menschheit trug die Allianz durch den Ersten, Zweiten und Dritten Krieg und zahlte einen hohen Preis: Sturmwind brannte einmal nieder, und Lordaeron fiel an die Gei\xdfel.","Im Jahr 25 ist Sturmwind das Herz menschlicher Macht, in wei\xdfem Stein wiedererrichtet und doch geplagt von den Defias, dem verschwundenen K\xf6nig Varian und einem Hof im Bann von Lady Prestor. Neue Menschen beginnen in der Abtei von Nordhain im Wald von Elwynn. Forever erlaubt Menschen, J\xe4ger zu werden, eine Berufung, die das urspr\xfcngliche Spiel anderen V\xf6lkern vorbehielt."]},"race:gnome":{title:"Gnome",summary:"Brillante T\xfcftler, deren Ahnen titanengeschmiedete Maschinen waren: Die Gnome haben ihre Stadt Gnomeregan verloren und leben im Exil in Eisenschmiede.",body:["Gnome sind klein von Gestalt und gewaltig an Erfindungsgeist. Ihre Ahnen, die Mechagnome, waren titanengeschmiedete Maschinen, die sp\xe4ter der Fluch des Fleisches traf und in lebende Wesen verwandelte. In Dun Morogh erbauten sie Gnomeregan, eine Stadt aus Zahnr\xe4dern und Dampf, und wurden treue Verb\xfcndete der Zwerge des nahen Eisenschmiede, an deren Seite sie im Zweiten Krieg k\xe4mpften.","Diese Stadt ist verloren. Troggs dr\xe4ngten aus der Tiefe herauf, und Robogenieur Sicco Thermapluggs Rat, Gnomeregan mit Strahlung zu fluten, vergiftete die Stadt stattdessen; viele Gnome starben, und manche \xdcberlebende wurden zu entstellten Lepragnomen. Hocht\xfcftler Gelbin Mekkadrill f\xfchrte die \xfcbrigen ins Exil nach Eisenschmiede, w\xe4hrend Thermaplugg \xfcber die Ruinen herrscht. Forever \xf6ffnet den Gnomen zum ersten Mal den Weg des Priesters."]},"race:night-elf":{title:"Nachtelfen",summary:"Die uralten Kaldorei wachten zehntausend Jahre lang \xfcber Kalimdor; nun sterblich, haben sie einen neuen Weltenbaum gepflanzt und sich der Allianz angeschlossen.",body:["Die Nachtelfen oder Kaldorei sind das \xe4lteste der spielbaren V\xf6lker. Als Nachfahren von Trollen, die der Brunnen der Ewigkeit verwandelte, errichteten sie ein Reich der Magie, \xfcberlebten den Krieg der Ahnen und lebten zehntausend Jahre lang als zur\xfcckgezogenes Volk von Druiden und Schildwachen im Schatten des Berges Hyjal. Arkane Magie ist bei ihnen noch immer verboten.","Der Dritte Krieg kostete sie ihre Unsterblichkeit, als Nordrassil verwundet wurde, um Archimonde zu vernichten. W\xe4hrend Malfurion im Smaragdgr\xfcnen Traum verloren war, lie\xdf Erzdruide Fandral Hirschhaupt vor der K\xfcste der Dunkelk\xfcste einen neuen Weltenbaum wachsen, Teldrassil, und in seinen \xc4sten erhob sich die Hauptstadt Darnassus. Unter Tyrande Wisperwind schlossen sich die Nachtelfen der Allianz an. Neue Nachtelfen beginnen auf den Lichtungen Teldrassils."]},"race:dwarf":{title:"Zwerge",summary:"Kinder der Irdenen der Titanen: Die Zwerge von Eisenschmiede sind sture Verb\xfcndete, unerm\xfcdliche Forscher und H\xfcter eines gespaltenen Erbes.",body:["Zwerge sind stur, warmherzig und aus Stein geboren: Ihre Ahnen waren die Irdenen, titanengeschmiedete W\xe4chter, die der Fluch des Fleisches verwandelte. Eisenschmiede, in einen Berg in Dun Morogh gehauen, ist seit Ewigkeiten ihre Hauptstadt. Der Krieg der drei H\xe4mmer spaltete die Clans: Die Bronzebarts behielten die Stadt, die Wildhammerzwerge lie\xdfen sich im Hinterland nieder, und die Dunkeleisenzwerge gerieten in Ragnaros' Dienste.","Unter K\xf6nig Magni Bronzebart haben die Zwerge in jedem Krieg der Allianz gek\xe4mpft, und die Forscherliga, in der sein Bruder Brann eine f\xfchrende Rolle spielt, durchgr\xe4bt Titanenruinen wie Uldaman auf der Suche nach dem Ursprung der Zwerge. Magnis Tochter Moira ist die Gemahlin des Dunkeleisenimperators geworden, eine Wunde, die der K\xf6nig pers\xf6nlich nimmt. Forever f\xfcgt die Hall of Thanes unter Eisenschmiede hinzu, die Ruhest\xe4tte der Zwergenherrscher, in die nun Eindringlinge eingebrochen sind, die man f\xfcr Dunkeleisenzwerge h\xe4lt, und Zwerge k\xf6nnen den Weg des Schamanen gehen."]},"race:skyborne-high-order":{title:"Skyborne: High Order",body:["Die Skyborne sind das neue spielbare Volk von World of Warcraft: Forever, und der High Order ist der Zweig, der an der Seite der Allianz steht. Ihre Heimat ist Zephras Isle, eine Insel, die in Skywall schwebt, der Elementarebene der Luft; sie wird von der Hoch\xe4ltesten Talaanis Shadowsong regiert, und ihre wichtigste Siedlung ist die Stadt Valanaar. Die Luftelementare, die einst mit den Skyborne auf der Insel lebten, verschwanden vor Jahrhunderten, ihre tragende Magie schwindet, und der Kontakt zu den Schwesterinseln Anvilas und Siroccas ist abgerissen, w\xe4hrend Fl\xfcchtlinge nach Zephras fliehen.","Abenteurer des High Order verlassen die Insel mit dem Luftschiff von Valanaar nach Dalaran im Alteracgebirge. Sie k\xf6nnen Krieger, J\xe4ger, Schurken, Druiden oder Magier sein und sind die einzigen Skyborne, die das Arkane studieren. Ihre Gaben spiegeln ihre Heimat: Sie gleiten auf dem Wind hinab, handeln mit beschleunigtem Tempo, treffen Elementare h\xe4rter und lesen nahe Leylinien, um Gesundheit und Mana wiederherzustellen. Um sie zu spielen, braucht man das optionale Skyborne Heroic oder Epic Pack."]},"race:skyborne-windshaper":{title:"Skyborne: Windshaper",body:["Die Windshaper sind die Skyborne, die an der Seite der Horde stehen. Wie der High Order stammen sie von Zephras Isle in Skywall, der Elementarebene der Luft, einer Insel, deren Luftelementare vor Jahrhunderten verschwanden und deren tragende Magie langsam versagt. W\xe4hrend Inseln wie Anvilas und Siroccas verstummen, dr\xe4ngen sich Fl\xfcchtlinge auf Zephras, und selbst Zephras hat begonnen zu zerfallen.","Windshaper verlassen Valanaar mit dem Luftschiff zum Skywatcher Plateau in Mulgore. Sie k\xf6nnen Krieger, J\xe4ger, Schurken, Druiden oder Schamanen sein und sind die einzigen Skyborne, die den Weg des Schamanen gehen. Sie gleiten auf dem Wind, k\xe4mpfen mit beschleunigtem Tempo und treffen Elementare h\xe4rter, und ihre eigene Gabe, Skysight, beschleunigt ihre Reisen und h\xe4lt in der N\xe4he einer elementaren Konvergenz weit l\xe4nger an. Wie der High Order erfordern sie das optionale Skyborne Heroic oder Epic Pack."]},"race:orc":{title:"Orcs",summary:"Einst vom D\xe4monenblut versklavt, wurden die Orcs von Thrall befreit und bauen nun im roten Land Durotar ihre Ehre wieder auf.",body:["Die Orcs kamen als Horde von Draenor nach Azeroth, getrieben von D\xe4monenblut und von Gul'dans Hexenmeistern. Im Zweiten Krieg besiegt, siechten sie in Internierungslagern dahin, bis Thrall, der Sohn des Frostwolfh\xe4uptlings Durotan, sie befreite und die schamanischen Wege ihrer Ahnen erneuerte.","Nach dem Dritten Krieg f\xfchrte Thrall sein Volk nach Kalimdor und gr\xfcndete Durotar mit seiner Hauptstadt Orgrimmar, von wo aus der Kriegsh\xe4uptling nun eine Horde regiert, die sie mit den Tauren, den Dunkelspeertrollen und den Verlassenen teilen. Orcs sind stolz, direkt und unersch\xfctterlich loyal, doch ihre blutige Vergangenheit lebt fort in den Kultisten der Brennenden Klinge in Durotar und im Schwarzfelsklan, der sich Thrall nie anschloss. Neue Orcs beginnen im Tal der Pr\xfcfungen. In Forever k\xf6nnen Orcs auch Magier werden."]},"race:tauren":{title:"Tauren",summary:"Sanfte Riesen der Ebenen, die die Erdmutter ehren: Die Tauren fanden in Mulgore eine Heimat und schlossen sich aus Dankbarkeit der Horde an.",body:["Die Tauren sind h\xfcnenhafte, friedliche Nomaden, die die Erdmutter ehren und seit Urzeiten die Ebenen Kalimdors durchstreifen. In den Jahren des Dritten Krieges wurden sie von den Zentauren gehetzt, bis Thralls gerade eingetroffene Horde Cairne Bluthufs Volk half, die Sicherheit von Mulgore zu erreichen.","Cairne vereinte viele verstreute St\xe4mme und gr\xfcndete Donnerfels auf gro\xdfen Tafelbergen \xfcber dem Grasland von Mulgore, und die Tauren schlossen sich aus Dankbarkeit und Achtung der Horde an. Ihre Druiden lernten bei Malfurion Sturmgrimm pers\xf6nlich, und ihre Schamanen und J\xe4ger halten alte Traditionen am Leben. Rivalisierende St\xe4mme wie die Grimmtotem, die das B\xfcndnis mit den Orcs ver\xfcbeln, bleiben eine st\xe4ndige Sorge. Junge Tauren beginnen im Camp Narache in Mulgore."]},"race:troll":{title:"Trolle",summary:"Erben gefallener Reiche: Die meisten Trolle hassen die anderen V\xf6lker noch immer, doch der Stamm der Dunkelspeere schwor Thrall und der Horde die Treue.",body:["Trolle herrschten einst \xfcber gewaltige Reiche: die Gurubashi in den s\xfcdlichen Dschungeln, die Amani in den W\xe4ldern des Nordens und die Zandalari, die sich die ersten aller Trolle nennen. Kriege gegen die Nachtelfen, die Hochelfen und die Menschen zerschlugen diese Reiche, und die meisten St\xe4mme hegen noch immer alten Hass und beten zu den Loa, den Geisterg\xf6ttern ihrer Ahnen.","Der Stamm der Dunkelspeere ist anders. Von rivalisierenden St\xe4mmen aus dem Schlingendorntal vertrieben, k\xe4mpften die Dunkelspeere um ihre Inselheimat, als Thralls sturmgepeitschte Flotte eintraf; ihr H\xe4uptling Sen'jin fiel dort, und sein Sohn Vol'jin schwor den Stamm auf die Horde ein. Sie siedelten auf den Echoinseln vor Durotar, doch die dunkle Magie des Hexendoktors Zalazane hat sie in das Dorf der Sen'jin auf dem Festland getrieben. In Forever k\xe4mpfen au\xdferdem Darkspear Raiders um die Darkspear Islands vor den D\xfcstermarschen, und Trolle k\xf6nnen Hexenmeister werden."]},"race:undead":{title:"Untote",summary:"Auferstandene Opfer der Seuche, die sich vom Lichk\xf6nig befreiten: Die Verlassenen herrschen \xfcber Unterstadt unter den Ruinen Lordaerons und trauen niemandem.",body:["Die Verlassenen waren einst B\xfcrger Lordaerons, von der Seuche get\xf6tet und von der Gei\xdfel erhoben, die ihren freien Willen zur\xfcckgewannen, als die Macht des Lichk\xf6nigs ins Wanken geriet. Angef\xfchrt von der Bansheek\xf6nigin Sylvanas Windl\xe4ufer beanspruchten sie die Ruinen von Lordaerons Hauptstadt und machten Unterstadt darunter zu ihrer Heimat. Ihre Lande, Tirisfal und der Silberwald, sind zwischen der Gei\xdfel und dem Scharlachroten Kreuzzug umk\xe4mpft.","Die Verlassenen schlossen sich der Horde als Verb\xfcndete aus Not an; nur wenige Lebende trauen ihnen, und die geheime Arbeit der K\xf6niglichen Apothekervereinigung an einer neuen Seuche gibt ihren Partnern guten Grund dazu. Neue Verlassene erheben sich in Todesend in Tirisfal. Forever f\xfcgt den Dungeon Ruins of Lordaeron hinzu, in dem die Verlassenen die zerschmetterte Stadt \xfcber Unterstadt zur\xfcckzuerobern versuchen, und erlaubt Paladine der Verlassenen, eine Verbindung, die die hier verwendeten Quellen noch nicht erkl\xe4ren."],unknowns:["Wie es in Forever zu Paladinen der Verlassenen kam, erkl\xe4ren die Quellen dieses Leitfadens nicht."]}}},1724,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"zones1",{enumerable:!0,get:function(){return n}});const n={"zone:dun-morogh":{title:"Dun Morogh",summary:"Verschneite T\xe4ler rund um Eisenschmiede, Heimat der Zwerge und der Gnome, die ihre Stadt verloren haben.",body:["Von den Gipfeln Khaz Modans umringt, ist Dun Morogh ein Land aus Schneefeldern, gefrorenen Seen und zwergischen Wacht\xfcrmen. Sein Herz ist Eisenschmiede, die Bergstadt des Bronzebartclans unter K\xf6nig Magni, w\xe4hrend junge Zwerge und Gnome im gesch\xfctzten Eisklammtal und rund um das Brauerdorf Kharanos zum ersten Mal zu den Waffen greifen. Frostm\xe4hnentrolle und w\xfchlende Troggs plagen die T\xe4ler.","Im Westen liegt Gnomeregan, das Wunder gnomischer Ingenieurskunst, verloren, als Troggs aus der Tiefe heraufquollen und die verzweifelte Strahlenflut der Verteidiger die Stadt vergiftete. Seine \xdcberlebenden leben nun als G\xe4ste in Eisenschmiede. In Forever wurde in die K\xf6nigsgr\xe4ber der Hall of Thanes unter der Stadt eingebrochen, und man verd\xe4chtigt Eindringlinge der Dunkeleisenzwerge."]},"zone:durotar":{title:"Durotar",summary:"Die raue rote K\xfcste, die Thrall nach seinem Vater benannte und an der die Orcs Orgrimmar erbauten.",body:["Als Thrall die Horde nach Kalimdor f\xfchrte, nahm er diesen sonnenrissigen Streifen der Ostk\xfcste in Besitz und nannte ihn nach seinem Vater Durotan Durotar. Die rote Erde und die steinigen Schluchten erinnerten die Orcs an Draenor. Sie vertrieben die Stacheleber aus dem Land und erbauten in einer Bergsenke im Norden Orgrimmar, benannt nach Orgrim Schicksalshammer.","Junge Orcs und Trolle bew\xe4hren sich im Tal der Pr\xfcfungen, bevor sie weiter nach Klingenh\xfcgel ziehen. An der K\xfcste halten die Dunkelspeertrolle das Dorf der Sen'jin, nachdem der Hexendoktor Zalazane ihre Sippe auf den Echoinseln versklavt hat, und kul tiranische Soldaten harren in der Burg Tiragarde aus. Kultisten der Brennenden Klinge lauern in den H\xfcgeln, und ihr Schwesterkult, die Sengende Klinge, verbirgt sich im Flammenschlund unter der Hauptstadt."]},"zone:elwynn-forest":{title:"Wald von Elwynn",summary:"Das gr\xfcne Herzland des K\xf6nigreichs Sturmwind, wo viele menschliche Helden ihre ersten Schritte tun.",body:["Der Wald von Elwynn ist das sanfte Herz des K\xf6nigreichs Sturmwind: Eichenw\xe4lder, H\xf6fe und Seen rund um die wei\xdfen Mauern der Stadt Sturmwind, die wiederaufgebaut wurde, nachdem die Horde sie im Ersten Krieg zerst\xf6rt hatte. Novizen werden in der Abtei von Nordhain ausgebildet, und Reisende rasten im Gasthaus Zur H\xf6hle des L\xf6wen in Goldhain.","Der Frieden ist d\xfcnner, als er aussieht. Kobolde haben die Minen besetzt, Flusspfotengnolle \xfcberfallen die westlichen H\xf6fe, Murlocs dr\xe4ngen sich an den Seen, und Banditen der Defias breiten sich aus dem benachbarten Westfall aus. In der Hauptstadt selbst ist das Verlies an einen Aufstand gefangener Defias gefallen."]},"zone:mulgore":{title:"Mulgore",summary:"Die windgepeitschten Ebenen der Tauren, gekr\xf6nt von den Tafelbergen von Donnerfels.",body:["Mulgore ist das angestammte Grasland der Tauren, ein gr\xfcner Kessel aus Ebenen und Tafelbergen, umschlossen von Gebirgen, mit nur einem Pass nach Osten ins Brachland. Generationenlang wurden die nomadischen Tauren von Zentauren gehetzt, bis Thralls Horde Gro\xdfh\xe4uptling Cairne Bluthuf half, sein Volk heimzuf\xfchren. Hier errichteten sie ihre ersten dauerhaften Siedlungen: das Dorf der Bluthufe und die Hauptstadt Donnerfels, erbaut auf hoch aufragenden Tafelbergen, die durch Seilbr\xfccken verbunden sind.","Junge Tauren \xfcben im Camp Narache auf dem Red Cloud Mesa, w\xe4hrend Gnolle, Stacheleber und Prospektoren der Venture Company die Ebenen heimsuchen. In Forever kommen die Skyborne der Horde mit dem Luftschiff von Zephras Isle am Skywatcher Plateau an."]},"zone:teldrassil":{title:"Teldrassil",summary:"Der neue Weltenbaum der Nachtelfen vor der Nordk\xfcste Kalimdors, mit Darnassus in seinen \xc4sten.",body:["Nachdem der Dritte Krieg sie ihre Unsterblichkeit gekostet hatte, lie\xdfen die Druiden der Nachtelfen vor der Nordk\xfcste Kalimdors einen neuen Weltenbaum wachsen. Sie nannten ihn Teldrassil, \u201eKrone der Erde\u201c, und erbauten in seinen \xc4sten Darnassus, eine Stadt mondbeschienener Tempel, in der Hohepriesterin Tyrande Wisperwind ihr Volk f\xfchrt.","Der Baum wurde ohne den Segen der Drachenaspekte gepflanzt, und sein Wachstum verlief nicht rein. Verderbnis ist in seine Tierwelt gekrochen und hat die Gnarlpine-Furbolgs verwildern lassen. Novizen der Nachtelfen beginnen im Laubschattental, und Boote aus dem Dorf Rut'theran an den Wurzeln verbinden die Insel mit der Dunkelk\xfcste."]},"zone:tirisfal-glades":{title:"Tirisfal",summary:"D\xfcstere Lichtungen rund um die Ruinen von Lordaerons Hauptstadt, heute das Kernland der Verlassenen.",body:["In Tirisfal lag einst die Hauptstadt Lordaerons, und der Rat von Tirisfal, der Orden, der die W\xe4chter erw\xe4hlte, tr\xe4gt seinen Namen nach seinen geheimen Treffen in diesen stillen H\xfcgeln. Die Seuche und der Fall des K\xf6nigreichs lie\xdfen das Land unter einem kr\xe4nklich gr\xfcnen Himmel zur\xfcck. Unter dem zerst\xf6rten Palast haben Sylvanas Windl\xe4ufers Verlassene Unterstadt zu ihrer Heimat gemacht; ihre neu erhobenen Toten erwachen in Todesend und sammeln sich im Ort Brill.","Von allen Seiten dr\xe4ngen Feinde heran: \xdcberreste der Gei\xdfel suchen die H\xf6fe heim, und die Eiferer des Scharlachroten Kreuzzugs halten das Scharlachrote Kloster im Nordosten. In Forever versuchen die Verlassenen, die zerschmetterte Stadt \xfcber ihnen zur\xfcckzuerobern, wo in den Ruins of Lordaeron angeblich ein Nekromant Macht um sich sammelt."]},"zone:zephras-isle":{title:"Zephras Isle",summary:"Eine fliegende Insel in Skywall, der Elementarebene der Luft, und das Startgebiet der Skyborne aus Forever.",body:["Zephras Isle ist das Startgebiet der Skyborne, des neuen spielbaren Volkes von World of Warcraft: Forever, freigeschaltet mit dem optionalen Skyborne Heroic oder Epic Pack. Die Insel schwebt in Skywall, der Elementarebene der Luft, wo die Skyborne sie einst mit Luftelementaren teilten. Diese Elementare verschwanden vor mehreren Jahrhunderten, und die Magie, die die Insel in der H\xf6he h\xe4lt, schwindet seither. Mit ihnen ging auch der Kontakt zu den anderen Skyborne-Inseln, Anvilas und Siroccas, verloren.","Nun st\xfcrzen diese Inseln ein, Fl\xfcchtlinge fliehen nach Zephras, und Zephras selbst hat begonnen auseinanderzubrechen. Die Hoch\xe4lteste Talaanis Shadowsong regiert von der Stadt Valanaar aus, deren Luftschiffanleger Schiffe f\xfcr die Allianz nach Dalaran im Alteracgebirge und f\xfcr die Horde zum Skywatcher Plateau in Mulgore schicken."],unknowns:["Warum die Luftelementare verschwanden, erkl\xe4ren die Quellen dieses Leitfadens nicht.","Den tieferen Ursprung der Skyborne und ihrer Orden behandeln die Quellen dieses Leitfadens noch nicht.","Die fr\xfcheren Herrscher der Insel, die Shal\u2019nan, werden nur genannt, nicht beschrieben."]},"zone:darkshore":{title:"Dunkelk\xfcste",summary:"Eine neblige, ruinen\xfcbers\xe4te K\xfcste, die die Nachtelfen vom Hafen Auberdine aus bewachen.",body:["Die Dunkelk\xfcste ist ein langer, regendunkler Streifen an Kalimdors Nordwestk\xfcste, \xfcbers\xe4t mit den zerfallenden Ruinen von St\xe4dten der Kaldorei aus der Zeit vor der Gro\xdfen Teilung. Die Nachtelfen beanspruchen sie als Teil ihres neuen Reiches, und Schildwachen patrouillieren auf der Stra\xdfe, die vom Hafen Auberdine nach S\xfcden zum Eschental f\xfchrt.","Abseits der Stra\xdfe lauert Gefahr: Geister wandeln durch die alten Ruinen, Naga und Murlocs pirschen an den Str\xe4nden, Furbolgs verwildern in den W\xe4ldern, und Kultisten des Schattenhammers und des Dark Strand lauern in den H\xfcgeln. Auberdines Schiffe segeln nach Teldrassil, zum Hafen von Menethil und in Forever auch nach Sturmwind; eine neue Route aus Forever kommt au\xdferdem aus S\xfcderstade."]},"zone:loch-modan":{title:"Loch Modan",summary:"Ein zwergisches Hochlandtal, dessen gro\xdfer See vom Stonewrought Dam zur\xfcckgehalten wird.",body:["\xd6stlich von Dun Morogh liegt Loch Modan, ein k\xfchles Hochlandtal aus Kiefern und Birken rund um einen gro\xdfen See, den der Stonewrought Dam zur\xfcckh\xe4lt, eines der Wunder zwergischer Ingenieurskunst. Nur wenige erinnern sich, dass ein Baumeister der Dunkeleisenzwerge ihn entwarf. Der Ort Thelsamar wacht \xfcber die Stra\xdfe, und die Station Algaz bewacht den Pass nach Norden ins Sumpfland.","Das Tal erinnert sich an den Zweiten Krieg, als die Horde es \xfcberrannte, bevor die Zwerge von Eisenschmiede sie zur\xfcckdr\xe4ngten. Heute steigt die Gefahr von unten auf: Ausgrabungen wie die von Ironband haben Troggs aus der Tiefe geweckt, Mo'grosh-Oger halten die H\xfcgel, und Dunkeleisenzwerge greifen den Damm selbst an."]},"zone:silverpine-forest":{title:"Silberwald",summary:"Ein heimgesuchter Kiefernwald an Lordaerons Westk\xfcste, umk\xe4mpft von Verlassenen, Worgen und den letzten seiner Menschen.",body:["Der Silberwald erstreckt sich entlang Lordaerons zerkl\xfcfteter Westk\xfcste; seine silbrigen Kiefern sind heute kr\xe4nklich und in Nebel geh\xfcllt. Die Verlassenen halten den Norden von der Grabst\xe4tte aus, w\xe4hrend menschliche \xdcberlebende und aus Dalaran entsandte Magier sich an Amberm\xfchle und den S\xfcden klammern. Dahinter hat sich Gilneas hinter dem Graum\xe4hnenwall abgeriegelt.","Der tiefste Schatten des Waldes ist Burg Schattenfang, einst die Burg von Baron Silberlein. Im Dritten Krieg beschwor der dalaranische Erzmagier Arugal Worgen, um gegen die Gei\xdfel zu k\xe4mpfen, verlor die Kontrolle \xfcber sie und verfiel dem Wahnsinn; nun nennt er die Bestien seine Kinder. Sein Fluch hat das nahe Dorf Pyrewood erreicht, dessen Bewohner sich bei Einbruch der Nacht in Worgen verwandeln."]},"zone:westfall":{title:"Westfall",summary:"Sturmwinds verlassene Kornkammer, heute das Gebiet der Defiasbruderschaft.",body:["Westfall war einst die Kornkammer Sturmwinds, eine K\xfcste aus goldenen Feldern und Windm\xfchlen. Seit dem Zweiten Krieg liegt vieles davon brach, und das K\xf6nigreich hatte weder Geld noch Soldaten \xfcbrig. In diese L\xfccke trat die Defiasbruderschaft: die Steinmetze, die Sturmwind wiederaufbauten und zu Gesetzlosen wurden, nachdem die Adligen sich weigerten, sie zu bezahlen, angef\xfchrt von Edwin van Cleef.","Die Defias herrschen \xfcber den zerst\xf6rten Ort Mondbruch und verbergen in den Todesminen darunter eine Werft, w\xe4hrend Gnolle und verwilderte Erntegolems die verbliebenen H\xf6fe heimsuchen. Nur die Volksmiliz, die Gryan Starkmantel auf der Sp\xe4herkuppe aufgestellt hat, stellt sich ihnen noch entgegen."]},"zone:barrens":{title:"Brachland",summary:"Eine weite Savanne im Herzen Kalimdors, durchzogen von der Goldstra\xdfe und gr\xf6\xdftenteils in der Hand der Horde.",body:["Das Brachland ist eine weitl\xe4ufige Savanne aus Dornb\xe4umen, Oasen und trockenen Flussbetten im Herzen Kalimdors. Vor der Gro\xdfen Teilung standen hier St\xe4dte der Nachtelfen; heute h\xe4lt die Horde das Land vom Wegekreuz und vom Camp Taurajo aus, die Goblins von Ratschet treiben auf dem Seeweg Handel mit der Beutebucht, und Soldaten der Allianz halten von der Feste Nordwacht aus Wache. In Forever handelt Durotar Supply and Logistics von einem Lager westlich des Wegekreuzes aus.","Zentauren der Kolkar, Stacheleber und Harpyien \xfcberfallen Reisende entlang der Goldstra\xdfe. Unter der Erde liegen drei alte Wunden: die H\xf6hlen des Wehklagens, wo der Traum eines Druiden zum Alptraum wurde, und die dornigen Bauten des Kral der Klingenhauer und der H\xfcgel der Klingenhauer, die den Stachelebern heilig sind."]},"zone:redridge-mountains":{title:"Rotkammgebirge",summary:"Rote H\xfcgel und ein stiller See \xf6stlich von Elwynn, wo Seenhain gegen Gnolle und Orcs des Schwarzfelsklans standh\xe4lt.",body:["\xd6stlich von Elwynn erhebt sich das Rotkammgebirge, ein Land aus rotem Stein, hohen Ulmen und rauschenden Fl\xfcssen, das Holz, Fisch und Getreide nach Sturmwind liefert. Sein Hauptort Seenhain liegt am Ufer des Lake Everstill, und die Kreuzung Three Corners verbindet ihn mit Elwynn und dem D\xe4mmerwald.","Der Frieden hier ist zerbrechlich. Gnolle des Rotkammgebirges \xfcberfallen die H\xf6fe, und Orcs des Schwarzfelsklans aus der Brennenden Steppe haben die Stonewatch Keep besetzt und lagern im Render's Valley. Vor langer Zeit errichteten die Dunkeleisenzwerge in diesen Bergen ein K\xf6nigreich, bis Thaurissans Beschw\xf6rung des Ragnaros die Lande im Norden versengte. In Forever treibt die Azeroth Commerce Authority bei Three Corners Handel, und P\xe4sse f\xfchren nach Osten in die Riverglades."]},"zone:stonetalon-mountains":{title:"Steinkrallengebirge",summary:"Zerkl\xfcftete Gipfel westlich des Brachlands, Nachtelfen und Tauren heilig und von der Holzf\xe4llerei der Goblins gezeichnet.",body:["Das Steinkrallengebirge erhebt sich westlich des Brachlands, die angestammte Heimat der Harpyien, auch wenn sich ihre Schw\xe4rme seither weit dar\xfcber hinaus verbreitet haben. Der h\xf6chste Gipfel, der Steinkrallengipfel, ist Nachtelfen wie Tauren heilig; die Nachtelfen unterhalten nahe dem Gipfel ein H\xfcgelgrab und eine Lichtung, die Tauren halten Sonnenfels in den zentralen H\xf6hen, und die Dunkelspeertrolle lagern bei Malaka'jin.","Den gr\xf6\xdften Schaden hat die Venture Company angerichtet: Ihre Goblins haben den Windshear Crag fast v\xf6llig abgeholzt, die Luft mit Ru\xdf erstickt und das Wasser mit \xd6l verseucht. Grimmtotem-Tauren, Kobolde und die gef\xe4hrlichen Tiere des Charred Vale machen die Wege nicht sicherer."]},"zone:ashenvale":{title:"Eschental",summary:"Der angestammte Wald der Nachtelfen, in dem der Krieg mit der Horde um sein Holz begann.",body:["Das Eschental ist der angestammte Wald der Nachtelfen, ein tiefer Wald voll violetter Schatten und uralter B\xe4ume, der sich vom Zoram Strand bis an die Grenzen des Brachlands erstreckt. Die Kaldorei halten Astranaar und eine Reihe von Au\xdfenposten, und die Schildwachen h\xfcten ihre Haine erbittert.","Im Dritten Krieg drangen Grom H\xf6llschreis Kriegshymnenorcs in diese W\xe4lder ein, tranken erneut D\xe4monenblut und erschlugen den Halbgott Cenarius; Grom starb sp\xe4ter, als er den Grubenlord Mannoroth an dem Ort t\xf6tete, der heute D\xe4monensturz hei\xdft. Die Orcs holzen den Osten noch immer vom Splitterholzposten und den Lagern der Kriegshymne aus ab, und der alte Streit schwelt weiter. Satyrn suchen die Ruinen heim, und an der K\xfcste liegt die Tiefschwarze Grotte, ein versunkener Tempel der Elune."]},"zone:duskwood":{title:"D\xe4mmerwald",summary:"Ein einst heller Winkel von Elwynn, verschlungen von endloser Nacht und gehalten von den sturen Bewohnern von Dunkelhain.",body:["Der D\xe4mmerwald war einst der s\xfcdliche Teil des Waldes von Elwynn, Heimat der Orte, die man heute Dunkelhain und Rabenflucht nennt. Dann fiel ein Schatten, der sich nie wieder hob, verkn\xfcpft mit dem Schicksal der Sense der Elune der Nachtelfen. Unter seiner endlosen D\xe4mmerung wuchsen die B\xe4ume knorrig, und Worgen, Untote und Oger aus dem Gebirgspass der Totenwinde kamen auf Beutezug.","Sturmwind hat die Region weitgehend sich selbst \xfcberlassen. Die Nachtwache von Dunkelhain bewacht die Hauptstra\xdfe, der Friedhof von Rabenflucht f\xfcllt sich mit ruhelosen Toten, und tief im Wald birgt der D\xe4mmerhain einen gro\xdfen Baum und ein Portal in den Smaragdgr\xfcnen Traum."]},"zone:wetlands":{title:"Sumpfland",summary:"Graue, regendurchtr\xe4nkte Marschen, die die Stra\xdfe zwischen Khaz Modan und Lordaeron bewachen.",body:["Das Sumpfland ist eine kalte, nebelverhangene Marsch zwischen den Bergen von Khaz Modan und dem Meer. Einst s\xe4umten zwergische Festungen die Region; der Krieg hat die meisten von ihnen zerst\xf6rt. Der Hafen von Menethil ist hier der Anker der Allianz, ein Hafen, dessen Schiffe nach Theramore und in Forever weiter nach S\xfcderstade segeln. Reisende kommen durch das belagerte Dun Algaz oder \xfcber den besch\xe4digten Thandol\xfcbergang.","Im Osten ragt Grim Batol auf, die verfluchte Stadt der Wildhammerzwerge, in der der Drachenmalclan im Zweiten Krieg die roten Drachen gefangen hielt; Abtr\xfcnnige des Drachenmalclans streifen noch immer durch die Marsch, und Dunkeleisenzwerge halten Dun Modr. In Forever f\xfchren seltsamer Nebel und Lichtblitze \xfcber Whelgar's Excavation Site zu einem Dungeon voller Konstrukte der Titanen."]},"zone:hillsbrad-foothills":{title:"Vorgebirge des H\xfcgellands",summary:"Gr\xfcne H\xfcgel, in denen sich S\xfcderstade und Tarrens M\xfchle nahe den Ruinen von Durnholde belauern.",body:["Die gr\xfcnen, fruchtbaren H\xfcgel des Vorgebirges liegen direkt s\xfcdlich des alten K\xf6nigreichs Alterac. Hier stehen sich zwei Orte gegen\xfcber: S\xfcderstade der Allianz an der K\xfcste und der Au\xdfenposten der Verlassenen in Tarrens M\xfchle in den H\xfcgeln, und ihre Fehde h\xe4lt die Felder blutig. Murlocs und das Syndikat versch\xe4rfen die Lage.","Auf einer Anh\xf6he im Osten steht Burg Durnholde, einst das Hauptquartier der Internierungslager der Orcs, wo Lord Aedelas Schwarzmoor den jungen Thrall als Gladiator aufzog, bevor dieser entkam, um sein Volk zu befreien; heute h\xe4lt das Syndikat ihre Ruinen. In Forever beginnen in beiden Orten die Quests, die den Weg in die City of Dalaran \xf6ffnen, und Schiffe legen in S\xfcderstade an."]},"zone:thousand-needles":{title:"Tausend Nadeln",summary:"Eine Schlucht aus Steint\xfcrmen und Salzebenen, in der sich Tauren, Zentauren und rennbegeisterte Goblins unruhig den Boden teilen.",body:["Tausend Nadeln ist eine riesige, trockene Schlucht voller hoch aufragender Tafelberge im S\xfcden Kalimdors, die man vom Brachland aus \xfcber den Gro\xdfen Aufzug erreicht. Die Tauren des Freiwindpostens leben auf den Gipfeln der Tafelberge, w\xe4hrend die Grimmtotem, ein Taurenclan, der Cairne Bluthuf feindlich gesinnt ist, die Darkcloud Pinnacle halten. Zentauren der Galak streifen \xfcber den Schluchtgrund, und Harpyien nisten zwischen den Nadeln.","Im Osten \xf6ffnet sich die Schlucht zur Schimmernden Ebene, einer glei\xdfenden Salzpfanne, auf der Ingenieure der Goblins und Gnome auf der Mirage Raceway mit ihren Maschinen um die Wette fahren."]},"zone:alterac-mountains":{title:"Alteracgebirge",summary:"Das zerbrochene K\xf6nigreich Alterac und die abgeschirmten Ruinen Dalarans, umk\xe4mpft von Ogern und dem Syndikat.",body:["Das Alteracgebirge war einst das K\xf6nigreich Alterac, dessen Herrscher Aiden Perenolde im Zweiten Krieg die Allianz an die Horde verriet. Das K\xf6nigreich wurde aufgel\xf6st; heute hausen Crushridge-Oger in den Ruinen von Alterac, und das Syndikat des Aliden Perenolde, Erbe des entehrten Hauses, beherrscht Strahnbrad. Die Schurken von Rabenholdt bleiben in den H\xfcgeln unter sich.","Am Lordamere-See liegen die \xdcberreste Dalarans, der Stadt der Magier, die Archimonde im Dritten Krieg zerst\xf6rte. Die Kirin Tor bauen sie hinter einer magischen Barriere wieder auf. In Forever ist diese Barriere gefallen, und arkanes Chaos quillt aus der Stadt; hier kommen auch die Skyborne der Allianz mit dem Luftschiff von Zephras Isle an."]},"zone:arathi-highlands":{title:"Arathihochland",summary:"Das alte Kernland Arathors, wo Stromgarde in Tr\xfcmmern liegt und drei Parteien um die Reste k\xe4mpfen.",body:["Das Arathihochland war das Kernland Arathors, des ersten Menschenreiches, das K\xf6nig Thoradin mit der Hauptstadt Strom gr\xfcndete. Sein Nachfolger Stromgarde liegt heute im S\xfcdwesten gr\xf6\xdftenteils in Tr\xfcmmern, wo die Verteidiger von Prinz Galen Trollbann einen Guerillakrieg an zwei Fronten gegen das Syndikat und die Boulderfist-Oger f\xfchren. Thoradins Wall markiert noch immer die alte Grenze im Westen.","Die Allianz sammelt sich in der Zuflucht. Die Horde h\xe4lt Hammerfall, ein fr\xfcheres Internierungslager, benannt zu Ehren von Kriegsh\xe4uptling Orgrim Schicksalshammer, der bei der Befreiung seines Volkes fiel. Trolle der Witherbark suchen die H\xfcgel heim, und der Thandol\xfcbergang verbindet das Hochland mit dem Sumpfland."]},"zone:desolace":{title:"Desolace",summary:"Eine graue, aschebedeckte \xd6dnis voller Kodoknochen und verfeindeter Zentaurenst\xe4mme.",body:["Desolace ist eine trostlose \xd6dnis aus grauer Asche, toten B\xe4umen und den Sch\xe4deln uralter Kodos, die zum Sterben auf den Kodofriedhof kommen. Die Ruinen von St\xe4dten der Hochgeborenen, von der Gro\xdfen Teilung zerschmettert, zerfallen auf seinen H\xfcgeln, und D\xe4monen und Satyrn sammeln sich noch immer dort, wo alte Magie nachwirkt.","Es ist die Heimat der Zentauren, die in den H\xf6hlen von Maraudon aus der Verbindung von Zaetar, dem Sohn des Cenarius, und der Erdprinzessin Theradras hervorgingen. Ihre vier St\xe4mme, die Kolkar, Gelkis, Magram und Maraudine, bek\xe4mpfen einander so erbittert wie Fremde. Die Allianz h\xe4lt Nijel's Point, die Horde das Dorf Shadowprey."]}}},1725,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"zones2",{enumerable:!0,get:function(){return n}});const n={"zone:stranglethorn-vale":{title:"Schlingendorntal",summary:"Ein dampfender Dschungel voller gefallener Trollst\xe4dte, J\xe4ger, Piraten und dem Goblinhafen Beutebucht.",body:["Das Schlingendorntal war das Kernland der Gurubashitrolle, deren Reich einst von Zul'Gurub aus den Dschungel beherrschte. Ihre Steinst\xe4dte zerfallen nun unter den Ranken, noch immer von Dschungeltrollen heimgesucht, w\xe4hrend Oger, Naga und die ber\xfcchtigten W\xfcrgedornen des Tals jeden Pfad gef\xe4hrlich machen. J\xe4ger str\xf6men zu Nesingwarys Expedition, die Horde h\xe4lt das Basislager von Grom'gol, und Rebellen der Allianz lagern im Norden.","An der S\xfcdspitze betreiben die Goblins der Beutebucht einen gesetzlosen Hafen neben den Piraten der Blackwater Raiders, und K\xe4mpfer aller V\xf6lker treffen sich in der alten Arena der Gurubashi. In Forever sind westlich von Grom'gol uralte Trollruinen aus dem Meer aufgestiegen: die Drowned City, in der nun Trolle und Naga umgehen."]},"zone:badlands":{title:"\xd6dland",summary:"Eine rissige Schluchtenw\xfcste, in der Zwerge nach Geheimnissen der Titanen graben und die Horde von Kargath aus Wache h\xe4lt.",body:["Das \xd6dland ist eine rissige, sonnenverbrannte W\xfcste aus Felsbrocken und gewundenen Schluchten im S\xfcden Khaz Modans. Prospektoren aus Eisenschmiede durchk\xe4mmen es nach Relikten der Titanen, angezogen von Uldaman, einem riesigen versch\xfctteten Gew\xf6lbe, das die ersten Hinweise auf den Ursprung der Zwerge als Wesen aus lebendem Stein offenbarte. Aus langem Schlaf befreite Troggs metzelten die erste Expedition nieder und verteidigen nun seine Hallen.","Dunkeleisenzwerge halten die Angor Fortress, Dustbelcher-Oger lagern \xfcberall in der \xd6dnis, und schwarze Drachenbrut nistet in der Lethlor Ravine. Die Horde h\xe4lt vom Au\xdfenposten Kargath aus Wache, nahe der Stra\xdfe zur Sengenden Schlucht."]},"zone:dustwallow-marsh":{title:"D\xfcstermarschen",summary:"Ein dampfender Sumpf, der Theramore, Onyxias Hort und das lange versiegelte Gef\xe4ngnis von Alcaz Island verbirgt.",body:["Die D\xfcstermarschen sind ein uralter, ewig nasser Sumpf an der Ostk\xfcste Kalimdors, voller Krokilisken, Raptoren und Murlocs. Vor ihrer K\xfcste liegt die Insel Theramore, die Festungsstadt, die Jaina Prachtmeer f\xfcr die \xdcberlebenden gr\xfcndete, die ihr nach Westen folgten; die Horde antwortet vom Dorf Brackenwall am Rand der Marsch aus. Im S\xfcden verseuchen schwarze Drachen den Wyrmbog rund um den Hort Onyxias.","Seit Langem ranken sich Ger\xfcchte um Alcaz Island, dessen Gef\xe4ngnis hochrangige Gefangene festgehalten haben soll, sogar K\xf6nig Varian Wrynn. In Forever \xf6ffnen sich seine Tore endlich und enth\xfcllen, dass im Inneren die Defiasbruderschaft und Naga gegeneinander Krieg f\xfchren."]},"zone:riverglades":{title:"Riverglades",summary:"Ein umk\xe4mpftes Flussland im S\xfcdosten Khaz Modans, neu in Forever, wo die Ritter von Farholde noch einen Krieg f\xfchren, den Sturmwind zur\xfccklie\xdf.",body:["Die Riverglades liegen \xf6stlich des \xd6dlands und der Brennenden Steppe und geh\xf6rten einst zum K\xf6nigreich Sturmwind. Im Ersten Krieg pl\xfcnderte die Horde den Ort Sunnyglade und versklavte seine Bewohner. Einige Familien flohen und gr\xfcndeten Windstead, w\xe4hrend Ritter, die die Gefangenen befreiten, Meadowsbrook gr\xfcndeten und dann eine K\xfcsteninsel als Farholde befestigten. Im Glauben, das Land sei verloren, wandte sich Sturmwind anderen Sorgen zu.","Gegen Ende des Zweiten Krieges flohen Oger des Schattenhammers und Orcs der Stormreaver vom Grabmal des Sargeras hierher, und jahrelange \xdcberf\xe4lle endeten in der Belagerung von Farholde. Im Jahr 25 k\xe4mpft die Brotherhood of the Horse von Ritterkommandant Demar Brant noch immer weiter, der Schattenhammer h\xe4lt das zerst\xf6rte Sunnyglade, und die Bolder'ok-Oger haben sich der Horde angeschlossen."],unknowns:["Wer die Truppen der Horde in Rog'mar und Bolder'ok anf\xfchrt, nennen die Quellen nicht.","Dass Cho\u2019gall nach dem Zweiten Krieg in die Region kam, ist nur ein Ger\xfccht.","Was der Gesang bedeutet, der nach Einbruch der Nacht aus der Krol\u2019dok Stronghold zu h\xf6ren ist, bleibt offen."]},"zone:swamp-of-sorrows":{title:"S\xfcmpfe des Elends",summary:"Ein brackiges Sumpfland, in dem gr\xfcne Drachen den versunkenen Tempel von Atal'Hakkar bewachen und die Horde Steinard h\xe4lt.",body:["Die S\xfcmpfe des Elends sind ein stehendes Moor aus Trauerb\xe4umen und Brackwasser im S\xfcden der \xd6stlichen K\xf6nigreiche, nahe der Stelle, an der sich das Dunkle Portal zum ersten Mal \xf6ffnete. Die Horde nutzt die Entfernung zu Sturmwind gut aus: Die Orcstadt Steinard ist hier ihre Hochburg. Krokilisken, Sumpfbestien und eine Gruppe verbannter Draenei teilen sich das tr\xfcbe Wasser.","Im Herzen des Sumpfes liegt der Tempel von Atal'Hakkar, das versunkene Heiligtum, in dem Priester der Atal'ai einst versuchten, ihren Blutgott Hakkar zu beschw\xf6ren. Heute bewachen ihn die gr\xfcnen Drachen des Aspekts Ysera und warnen, dass sich darin noch immer ein Schrecken regt."]},"zone:feralas":{title:"Feralas",summary:"Ein \xfcppiger, regengen\xe4hrter Wald aus Riesenb\xe4umen, von Ogern besetzten Ruinen und der alten Stadt der Hochgeborenen, Eldre'Thalas.",body:["Feralas ist ein \xfcppiger, regendurchtr\xe4nkter Wald aus Riesenb\xe4umen an Kalimdors S\xfcdwestk\xfcste, einst Teil des alten Reiches der Nachtelfen. Seine gr\xf6\xdfte Ruine ist Eldre'Thalas, heute D\xfcsterbruch genannt, wo die Shen'dralar, Hochgeborene, die die Gro\xdfe Teilung \xfcberlebten, zehntausend Jahre lang unter sich blieben. Gordunni-Oger haben die alten Elfenruinen \xfcberrannt und ihre Verderbnis im ganzen Land verbreitet.","Die Schildwachen der Mondfederfeste beobachten die K\xfcste von der Insel Sardor aus, w\xe4hrend die Tauren des Camps Mojache f\xfcr die Horde Abtr\xfcnnige der Grimmtotem jagen. Naga halten die westlichen Inseln, St\xf6cke der Silithiden sind aufgetaucht, und gr\xfcne Drachen bewachen das Traumge\xe4st, ein Tor zum Smaragdgr\xfcnen Traum."]},"zone:hinterlands":{title:"Hinterland",summary:"Wilde n\xf6rdliche H\xfcgel der Greifenreiter und Waldtrolle, Heimat der Wildhammerzwerge am Nistgipfel.",body:["Das Hinterland ist ein zerkl\xfcftetes, bewaldetes Hochland im Norden Lordaerons. Nach dem Krieg der drei H\xe4mmer verlie\xdfen die Wildhammerzwerge das verfluchte Grim Batol und lie\xdfen sich hier am Nistgipfel nieder, wo sie die wilden Greifen der Region z\xe4hmen und treue Verb\xfcndete der Allianz bleiben. Ein paar Hochelfen halten noch die Quel'Danil Lodge.","Die H\xfcgel geh\xf6ren ebenso den Waldtrollen. Der Stamm der Revantusk hat sich Thralls Horde angeschlossen, w\xe4hrend die Vilebranch \xfcber die gro\xdfe Tempelstadt Jintha'Alor herrschen und die Witherbark rund um Shadra'Alor lauern. Im Norden birgt der uralte Baum Seradane ein Portal in den Smaragdgr\xfcnen Traum, bewacht von gr\xfcnen Drachen."]},"zone:tanaris":{title:"Tanaris",summary:"Ein Meer aus D\xfcnen, von Gadgetzan aus regiert, das die H\xf6hlen der Zeit und die Trollstadt Zul'Farrak verbirgt.",body:["Tanaris ist eine endlose W\xfcste aus D\xfcnen und Sandst\xfcrmen im S\xfcdosten Kalimdors. Die Goblins des Dampfdruckkartells regieren sie von Gadgetzan und dem Dampfdruckpier aus und wahren eine br\xfcchige Neutralit\xe4t, w\xe4hrend Wastewander-Banditen, S\xfcdmeerpiraten und Dunemaul-Oger Reisende \xfcberfallen.","Die W\xfcste verbirgt \xe4ltere M\xe4chte. In den H\xf6hlen der Zeit wacht Nozdormus bronzener Drachenschwarm \xfcber den Lauf der Geschichte; weit im S\xfcden liegen die Titanenruinen von Uldum; und die Sandtrolle von Zul'Farrak bewachen im Nordwesten ihre ummauerte Stadt. In Forever verbindet ein Schiff vom Dampfdruckpier die W\xfcste mit Powderfuse Port in den Riverglades."]},"zone:searing-gorge":{title:"Sengende Schlucht",summary:"Eine versengte Grube voller Minen der Dunkeleisenzwerge und Sklavenarbeit, geschw\xe4rzt von der Beschw\xf6rung des Ragnaros.",body:["Die Sengende Schlucht ist ein geschw\xe4rztes Land aus Schlacke und geschmolzenem Gestein im S\xfcden Khaz Modans. Ihre Narben verdankt sie derselben Katastrophe, die die Brennende Steppe verbrannte: Zauberthan Thaurissans Beschw\xf6rung des Ragnaros, die den Krieg der drei H\xe4mmer beendete. Heute beherrschen die Dunkeleisenzwerge die Schlucht und treiben Sklaven an, im gro\xdfen Riss des Kessels Erz abzubauen.","Nicht jeder Dunkeleisenzwerg dient dem Feuerf\xfcrsten. Die Thoriumbruderschaft, Meisterschmiede, die sich von ihrem Clan losgesagt haben, treibt von der Thoriumspitze aus Handel mit Au\xdfenstehenden. Im S\xfcden ragt der Schwarzfels auf, das Reich der Dunkeleisenzwerge in seinen Tiefen und die Spitze dar\xfcber in der Hand von Orcs und schwarzen Drachen."]},"zone:azshara":{title:"Azshara",summary:"Eine K\xfcste des ewigen Herbstes \xfcber den versunkenen Ruinen von K\xf6nigin Azsharas Hauptstadt.",body:["Azshara ist eine zerrissene K\xfcste des ewigen Herbstes im Nordosten Kalimdors, deren B\xe4ume in Rot und Gold leuchten. Hier stand Zin-Azshari, die gr\xf6\xdfte Stadt der alten Nachtelfen, bis die Gro\xdfe Teilung den Gro\xdfteil davon ins Meer schleuderte. Zerst\xf6rte Terrassen klammern sich noch an die Klippen, heimgesucht von ruhelosen Geistern der Hochgeborenen; Naga und Satyrn streifen am Ufer umher, und die Allianz am Talrendis Point und die Horde bei Valormok unterhalten kleine Lager.","In Forever \xf6ffnet sich in Azshara ein lange versiegeltes Tor zur Blackmaw Hold, einer gro\xdfen Stadt der Furbolgs, deren Stamm gegen eine Verderbnis k\xe4mpft, die sich durch ihre Haine und Tunnel ausbreitet. Ihre Tiefen sind mit den Barrow Deeps verbunden und f\xfchren noch weiter hinab."]},"zone:blasted-lands":{title:"Verw\xfcstete Lande",summary:"Eine rote, zerst\xf6rte W\xfcste rund um das stille Dunkle Portal, bewacht von den Magiern und Paladinen der Burg Nethergarde.",body:["Die Verw\xfcsteten Lande waren einst Teil des Schwarzen Morasts, bis die Magie, die das Dunkle Portal \xf6ffnete, sie zu einer roten W\xfcste aus rissigem Lehm verformte. Das gro\xdfe Portal, durch das die Horde zuerst einfiel, steht noch immer hier; sein steinerner Rahmen ist seit seiner Zerst\xf6rung dunkel und still. Burg Nethergarde, eine Festung Sturmwinds mit Magiern und Paladinen, h\xe4lt dar\xfcber Wache.","In der versengten \xd6dnis lebt kaum etwas au\xdfer Skorpionen, Basilisken, Dreadmaul-Ogern und ein paar verbannten Draenei. Auch D\xe4monen verweilen hier: Der Verdammnislord Kazzak sammelt die \xdcberreste der Brennenden Legion im Tainted Scar."]},"zone:felwood":{title:"Teufelswald",summary:"Ein einst lieblicher, von D\xe4monen vergifteter Wald, in dem die Furbolgs der Holzschlund und die Druiden gegen die F\xe4ulnis k\xe4mpfen.",body:["Der Teufelswald war einst ein Paradies aus B\xe4chen und Wiesen, gepflegt von den Nachtelfen. Im Dritten Krieg verdarb die Brennende Legion ihn mit der Macht des Sch\xe4dels von Gul'dan, und das Land erholte sich nie: Seine Fl\xfcsse flie\xdfen gr\xfcn vor Gift, seine Urtume und Treants verrotten, wo sie stehen, und Satyrn, H\xf6llenbestien und der d\xe4monenanbetende Schattenrat von Jaedenar suchen seine Lichtungen heim.","Nachtelfen in der Talonbranch Glade, die Horde am Blutgiftposten und die Druiden des Emerald Sanctuary versuchen, die Verderbnis zur\xfcckzudr\xe4ngen. Im Norden bewachen die Holzschlund, einer der letzten unverdorbenen Furbolgst\xe4mme, die Tunnel, die zur Mondlichtung und nach Winterquell f\xfchren."]},"zone:un-goro-crater":{title:"Krater von Un'Goro",summary:"Ein urzeitlicher Dschungelkrater voller Dinosaurier, lebender Elemente und stiller Titanenpylonen.",body:["Der Krater von Un'Goro ist ein dampfender, urzeitlicher Dschungel, eingesenkt zwischen den W\xfcsten des s\xfcdlichen Kalimdor, eine Welt f\xfcr sich, in der Teufelssaurier jagen, Elementare aus den hei\xdfen Quellen steigen und in seinem Herzen der Fire Plume Ridge schwelt. Forscher versammeln sich in Marshals Zuflucht, um seine roten, blauen, gr\xfcnen und gelben Kristalle zu untersuchen und die r\xe4tselhaften Pylonen auf den Kraterk\xe4mmen, die das Werk der Titanen zu sein scheinen.","Im S\xfcden sind Silithiden aufgetaucht, die sich aus dem benachbarten Silithus ausbreiten. In Forever \xf6ffnet sich hoch \xfcber dem Krater eine uralte Anlage der Titanen, Shaper's Terrace, f\xfcr Abenteurer, die Energiekristalle aus ganz Un'Goro mitbringen."]},"zone:burning-steppes":{title:"Brennende Steppe",summary:"Aschegeschw\xe4ngertes Hochland unter dem Schwarzfels, gehalten von Orcs des Schwarzfelsklans, Fire-Gut-Ogern und schwarzen Drachen.",body:["Die Brennende Steppe ist ein verw\xfcstetes Hochland aus Asche, Lava und schwelendem Stein, versengt, als Thaurissans Beschw\xf6rung des Ragnaros den Krieg der drei H\xe4mmer beendete; die Ruinen der alten Dunkeleisenstadt Thaurissan stehen hier noch immer. Die Steppe tr\xe4gt den einzigen Landweg zwischen Sturmwind und Khaz Modan, doch das K\xf6nigreich hat sie so gut wie aufgegeben.","\xdcber ihr ragt der Schwarzfels auf. Die Schwarzfelsspitze, im Zweiten Krieg die gro\xdfe Festung der Horde, wird von Orcs des Schwarzfelsklans und schwarzen Drachen unter Nefarian gehalten, w\xe4hrend die Dunkeleisenzwerge darunter in der Tiefe herrschen. Fire-Gut-Oger streifen \xfcber die Ebenen, und nur der Au\xdfenposten der Allianz in Morgans Wacht und das Lager der Horde am Flammenkamm halten stand."]},"zone:western-plaguelands":{title:"Westliche Pestl\xe4nder",summary:"Lordaerons verseuchtes Ackerland, wo die Gei\xdfel Andorhal h\xe4lt und Uthers Grabmal der letzte geweihte Boden ist.",body:["Die Westlichen Pestl\xe4nder geh\xf6rten einst zu den reichsten Ackerl\xe4ndern Lordaerons; heute h\xe4ngt grauer Nebel \xfcber kranken Feldern, und Untote ziehen durch verlassene Geh\xf6fte. Der zerst\xf6rte Ort Andorhal, wo Kel'Thuzads Kult sein verseuchtes Getreide verteilte, ist hier die gr\xf6\xdfte Hochburg der Gei\xdfel, und Seuchenkessel vergiften die Felder ringsum. Auf einer Insel im Darrowmere-See verbirgt Caer Darrow, die Burg der Familie Barov, die Scholomance, eine Schule der Nekromantie.","Der Scharlachrote Kreuzzug k\xe4mpft von Herdweiler im Norden aus, die Allianz vom Lager K\xfchlwind, und die Verlassenen halten das Bollwerk an der Grenze zu Tirisfal. Uthers Grabmal, die Ruhest\xe4tte des Lichtbringers, ist der einzige geweihte Ort des Friedens."]},"zone:eastern-plaguelands":{title:"\xd6stliche Pestl\xe4nder",summary:"Der am schlimmsten verw\xfcstete Winkel des gefallenen Lordaeron, beherrscht von der Gei\xdfel aus der verbrannten Stadt Stratholme.",body:["Die \xd6stlichen Pestl\xe4nder sind der am schwersten verw\xfcstete Rest des K\xf6nigreichs Lordaeron: braune, kranke Erde, B\xe4ume, die zu riesigen Pilzen aufgequollen sind, und Luft voll orangefarbenen Nebels. In ihrer Mitte liegt Stratholme, die Stadt, deren Bewohner Prinz Arthas im Dritten Krieg niedermetzeln lie\xdf, heute geteilt zwischen der Gei\xdfel und dem Scharlachroten Kreuzzug.","Das Hauptheer des Kreuzzugs h\xe4lt Tyrs Hand und bek\xe4mpft die Untoten mit gro\xdfem Eifer, aber wenig Erfolg, w\xe4hrend die Argentumd\xe4mmerung in der Kapelle des Hoffnungsvollen Lichts jeden willkommen hei\xdft, der helfen will. Geisterst\xe4dte wie Darrowshire und Corins Kreuzung zeugen von verlorenen Schlachten, und Amanitrolle schlagen von Zul'Mashar im Norden aus zu, um ihre alten Lande zur\xfcckzuerobern."]},"zone:winterspring":{title:"Winterquell",summary:"Ein verschneites Tal an den H\xe4ngen des Hyjal, das sich Goblinh\xe4ndler, Frosts\xe4bler, blaue Drachen und D\xe4monen teilen.",body:["Winterquell ist ein Tal fast ewigen Schnees an den H\xe4ngen des Berges Hyjal, wo die Nachtelfen nach der Gro\xdfen Teilung zuerst mit dem Wiederaufbau begannen. Die Goblinstadt Ewige Warte handelt mit jedem, Nachtelfen halten noch das Dorf Starfall, und die Ausbilder am Frosts\xe4blerfelsen ziehen die wei\xdfen Raubkatzen des Tals auf. Blaue Drachen hausen in den H\xf6hlen von Mazthoril.","Der S\xfcden des Tals ist in der Darkwhisper Gorge an D\xe4monen gefallen, und die Furbolgs der Winterfell sind verwildert. In Forever erreicht man einen der Eing\xe4nge zum Schlachtzug Barrow Deeps \xfcber Winterquell."]},"zone:deadwind-pass":{title:"Gebirgspass der Totenwinde",summary:"Ein toter, windzerrissener Pass, beherrscht von Karazhan, dem Turm des letzten W\xe4chters Medivh.",body:["Der Gebirgspass der Totenwinde ist eine zerkl\xfcftete Schlucht voller versteinerter, blattloser B\xe4ume zwischen dem D\xe4mmerwald und den S\xfcmpfen des Elends, durch die unabl\xe4ssig ein heulender Wind fegt. In seiner Mitte steht Karazhan, der elfenbeinerne Turm Medivhs, des letzten W\xe4chters von Tirisfal, dessen Besessenheit durch Sargeras der Horde den Weg \xf6ffnete. Obwohl Medivh l\xe4ngst tot ist, sickert aus seinem Turm noch immer dunkle Magie ins Land.","Oger der Totenwinde, D\xe4monen und ruhelose Geister streifen durch den Pass, die Gr\xe4ber von Morgan's Plot finden keine Ruhe, und Reisende fl\xfcstern, eine neue Macht habe den Turm beansprucht. Die meisten eilen schnell hindurch."]},"zone:moonglade":{title:"Mondlichtung",summary:"Ein friedliches Heiligtum der Druiden im Norden Kalimdors, Heimat des Zirkels des Cenarius.",body:["Die Mondlichtung ist ein verborgenes Tal im Norden Kalimdors, das den Druiden seit Tausenden von Jahren heilig ist. Malfurion Sturmgrimm versammelte hier Druiden, um den Zirkel des Cenarius zu gr\xfcnden, und das Spiegelbild des Tals im Smaragdgr\xfcnen Traum ist der heiligste Ort jenes Reiches. In der Stadt Nachthafen wacht Bewahrer Remulos, der Sohn des Cenarius, \xfcber den Orden.","Seit dem Dritten Krieg hat der Zirkel die Mondlichtung allen ge\xf6ffnet, die dem Weg der Druiden folgen, und Tauren und Nachtelfen teilen sich ihre Ufer heute in Frieden. Die W\xe4chter der Mondlichtung dulden im Heiligtum keine Gewalt, und jedes Jahr feiert Nachthafen das Mondfest."]},"zone:silithus":{title:"Silithus",summary:"Eine sonnenverbrannte W\xfcste voller Insektenst\xf6cke im S\xfcdwesten Kalimdors, wo der Zirkel des Cenarius die versiegelten Tore von Ahn'Qiraj bewacht.",body:["Silithus ist eine gl\xfchende W\xfcste im \xe4u\xdfersten S\xfcdwesten Kalimdors, nur unterbrochen von den hoch aufragenden St\xf6cken der Silithiden. Seit dem Krieg der Treibsande sind die insektenhaften Qiraji hinter dem Skarab\xe4uswall eingeschlossen, den die Drachenschw\xe4rme errichteten, doch ihre Silithidenschw\xe4rme vermehren sich weiter.","Der Zirkel des Cenarius beobachtet die Bedrohung von der Burg Cenarius aus, w\xe4hrend Kultisten des Schattenhammers sich zu eigenen Zwecken in Lagern \xfcberall in den D\xfcnen sammeln. Hinter dem Wall wartet der Festungstempel von Ahn'Qiraj."]}}},1726,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"instances1",{enumerable:!0,get:function(){return n}});const n={"instance:hall-of-thanes":{title:"Hall of Thanes",summary:"Die k\xf6nigliche Gruft von Eisenschmiede, in die Eindringlinge eingebrochen sind \u2013 die Zwerge verd\xe4chtigen die Dunkeleisenzwerge.",body:["Unter Eisenschmiede liegt die Hall of Thanes, wo die Zwerge ihre Herrscher zur letzten Ruhe betten und die Gr\xe4ber mit Sorgfalt pflegen. Ihr Eingang befindet sich an der Schwelle zum Hohen Sitz im Herzen der Stadt: ein kurzer Weg f\xfcr die Allianz, ein waghalsiges Eindringen f\xfcr jede Gruppe der Horde. Nun haben sich Eindringlinge gewaltsam Zugang zu den geweihten Gr\xe4bern verschafft. Die Zwerge verd\xe4chtigen den Dunkeleisenklan, und der alte Stein ist erf\xfcllt von geisterhaftem Fl\xfcstern.","Die meisten Quests sind f\xfcr die Allianz gedacht und beginnen in Kharanos oder rund um Eisenschmiede, eine der Quests im Inneren vergibt jedoch ein neutraler Geist. Vier Gegner versperren den Weg: Faldrim Anvilmar, Magmatus, Plunder und Durgen Dirgehammer."],unknowns:["Wer die Eindringlinge wirklich sind; der offizielle Text sagt nur, dass die Zwerge den Dunkeleisenklan verd\xe4chtigen.","Was sich in den Hallen geregt hat und welche Geschichte hinter jedem der vier Gegner steckt."]},"instance:ragefire-chasm":{title:"Flammenschlund",summary:"Vulkanische H\xf6hlen unter Orgrimmar, in denen Troggs und ein Kult im Dienst der D\xe4monen die neue Hauptstadt der Horde bedrohen.",body:["Unter Orgrimmar erstreckt sich ein Labyrinth aus lavaerhellten H\xf6hlen, und die Horde hat erfahren m\xfcssen, dass ihre neue Hauptstadt nicht in Frieden ruht. Troggs, die man die Flammenschlund nennt, sind aus den tiefen Tunneln heraufgestiegen, und als die Tauren-\xc4lteste Magatha Grimmtotem Frieden mit ihnen schlie\xdfen wollte, schlug ihr nur Gewalt entgegen.","Schlimmer noch: Eine Sekte namens Sengende Klinge, die dem d\xe4monischen Schattenrat ergeben ist, hat sich im Schlund versteckt, um gegen alles zu intrigieren, was Thralls Volk aufgebaut hat. Angef\xfchrt wird sie von Taragaman dem Hungerleider, einer Teufelswache, an dessen Seite der Hexenmeister Jergosh der Herbeirufer und der Satyr Bazzalan stehen. F\xfcr viele junge Helden der Horde sind diese H\xf6hlen der erste Dungeon."]},"instance:ruins-of-lordaeron":{title:"Ruins of Lordaeron",summary:"Die zerst\xf6rte Hauptstadt \xfcber Unterstadt, in der die Verlassenen ihre Vergangenheit zur\xfcckfordern, w\xe4hrend ein Nekromant Macht sammelt.",body:["Die Verlassenen versuchen, die zerst\xf6rte Hauptstadt \xfcber ihrer Unterstadt zur\xfcckzuerobern. In den Tr\xfcmmern liegen noch gesch\xe4tzte Erbst\xfccke und Erinnerungen, doch die Gei\xdfel spukt durch die zerbrochenen Stra\xdfen, und es hei\xdft, innerhalb der Mauern sammle ein Nekromant Macht. Abenteurer werden gerufen, um die Stadt sicher zu machen.","Gruppen der Horde erreichen den Eingang bequem von Unterstadt aus, w\xe4hrend Gruppen der Allianz sich in Hordegebiet wagen m\xfcssen. Beide Fraktionen finden Quests: Die der Horde beginnen in Unterstadt, im Silberwald und in Tirisfal, die der Allianz in den Ruinen selbst. Der Weg f\xfchrt an Witherfang, The Baron, Viktor the Vile, The Abandoned und Bjork vorbei zum letzten Gegner, Rath'mael."],unknowns:["Wer der Nekromant ist und wof\xfcr die gesammelte Macht bestimmt ist.","Wie viel von der alten Hauptstadt die Verlassenen wieder aufbauen wollen."]},"instance:deadmines":{title:"Die Todesminen",summary:"Die verlassene Goldmine im Westfall, in der Edwin VanCleefs Defiasbruderschaft insgeheim ein Kriegsschiff baut.",body:["Vor dem Ersten Krieg waren diese Stollen die reichsten Goldminen im Land der Menschen; als die Orcs Sturmwind pl\xfcnderten, blieben sie leer zur\xfcck. Nun hat die Defiasbruderschaft sie zu ihrer geheimen Festung gemacht. Ihr Anf\xfchrer Edwin VanCleef war ein Steinmetzmeister, der nach dem Krieg half, Sturmwind wieder aufzubauen, bis die Adligen der Stadt sich weigerten, seine Gilde zu bezahlen. Verraten wurden seine Arbeiter zu Gesetzlosen und breiteten sich \xfcber den Westfall aus.","Der Weg hinein beginnt im zerst\xf6rten Dorf Mondbruch. Tief unten helfen Goblins wie Sneed und Gilnid den Defias, in einer versteckten Bucht ein gro\xdfes Schiff fertigzustellen, bewacht von Handlanger Pein und Kapit\xe4n Gr\xfcnhaut."]},"instance:wailing-caverns":{title:"Die H\xf6hlen des Wehklagens",summary:"H\xf6hlen unter dem Brachland, in denen der Traum des Druiden Naralex von einer Erneuerung zum Albtraum wurde.",body:["Die H\xf6hlen des Wehklagens verdanken ihren Namen dem St\xf6hnen von Wind und Dampf, die durch Spalten im Fels fahren. Der Nachtelfendruide Naralex entdeckte sie und hoffte, ihre unterirdischen Quellen mit dem Smaragdgr\xfcnen Traum zu verbinden, damit sich gr\xfcnes Leben wieder \xfcber das trockene Brachland ausbreite. Doch w\xe4hrend er meditierte, \xfcberw\xe4ltigte ihn stattdessen der Smaragdgr\xfcne Albtraum.","Im Schlaf gefangen, ergie\xdft Naralex diese Verderbnis nun in die H\xf6hlen. Ihre Kreaturen sind zu entarteten Bestien verkommen, und die meisten seiner J\xfcnger wurden wahnsinnig und zu den Druiden des Giftzahns, unter ihnen Lady Anacondra und die Lords Kobrahn, Pythas und Serpentis. Wer Naralex wecken will, muss sich Mutanus dem Verschlinger stellen."]},"instance:shadowfang-keep":{title:"Burg Schattenfang",summary:"Eine Spukburg im Silberwald, in der der wahnsinnige Erzmagier Arugal den Worgen Unterschlupf gew\xe4hrt, die er selbst entfesselt hat.",body:["Die Kirin Tor verloren im Dritten Krieg den Kampf gegen die Gei\xdfel, und jeder Magier, der fiel, erhob sich bald wieder auf der Seite des Feindes. Erzmagier Arugal schlug die Warnungen seiner Kollegen in den Wind, suchte jenseits der Welt nach Hilfe und rief die wilden Worgen herbei. Sie zerfleischten die Untoten, dann die Reihen Dalarans selbst, und \xfcberrannten die Burg von Baron Silberlein auf dem H\xfcgel \xfcber Pyrewood.","Die Schuld zerbrach Arugals Verstand. Er nennt die Wolfsmenschen nun seine Kinder und verbirgt sich mit ihnen in der Burg, die jetzt Schattenfang hei\xdft und vom gro\xdfen Wolf Fenrus bewacht wird. Der Geist des Barons hat sie nie verlassen, und die Verlassenen des Silberwalds wollen den Erzmagier tot sehen."]},"instance:excavation-site-wetlands":{title:"Excavation Site: Wetlands",summary:"Eine Grabung bei Whelgar's Excavation Site hat einen Ort freigelegt, den die Zeit unber\xfchrt lie\xdf, bewacht von versprengten Konstrukten der Titanen.",body:["In den H\xfcgeln des Sumpflands, nahe dem Thelgenfelsen und Dun Algaz, ist etwas erwacht. Nebel kriecht die H\xe4nge \xfcber Whelgar's Excavation Site hinab, und am Horizont flackert Licht. Jenseits der Grabung scheint das Land von den Zeitaltern unber\xfchrt; versprengte Maschinen der Titanen und wilde Tiere bewachen Geheimnisse, die die Forscherliga unbedingt l\xfcften will.","Die Quests der Allianz beginnen im Hafen von Menethil, in Greenwarden's Grove und in Seenhain, die der Horde in Orgrimmar und Hammerfall. Saltspine und Shadetooth versperren den Weg zum Relic Guardian, dessen Niederlage ein Relikt der Titanen hinterl\xe4sst, mit dem f\xfcr beide Fraktionen eine Quest beginnt."],unknowns:["Was jenseits der Grabung erwacht ist und was den Nebel und die Lichter verursacht.","Wer den Ort erbaut hat und wozu das Relikt der Titanen dient."]},"instance:stormwind-stockade":{title:"Das Verlies",summary:"Das Gef\xe4ngnis von Sturmwind, das seine eigenen Insassen bei einem von den Defias angef\xfchrten Aufstand erobert haben.",body:["Das Verlies liegt im Herzen der Stadt Sturmwind und beherbergt Diebe, M\xf6rder und politische Gefangene. Vor Kurzem erhoben sich die Insassen, bekannten sich zur Defiasbruderschaft und vertrieben die Wachen; nun beherrschen sie die Zellentrakte selbst.","Ihr R\xe4delsf\xfchrer ist Bazil Thredd, ein Agent der Defias. Unter den Gefangenen sind der Schwarzfelsorc Targorr der Schreckliche, der Dunkeleisenzwerg Kam Tiefenzorn und der Grabr\xe4uber Dextren Ward. Mehrere von ihnen wurden zum Tode verurteilt, doch die B\xfcrokratie des Adels verz\xf6gerte die Urteile immer wieder, und so schicken Seenhain, Dunkelhain und sogar Eisenschmiede insgeheim Abenteurer hinein, um die Sache zu erledigen."]},"instance:city-of-dalaran":{title:"City of Dalaran",summary:"Die Stadt der Kirin Tor im Alteracgebirge, wo die Barriere \xfcber ihrem Wiederaufbau gefallen ist und die Magie au\xdfer Kontrolle ger\xe4t.",body:["Eine Zeit lang verbarg eine magische Barriere die Arbeiten am Wiederaufbau Dalarans. Nun ist dieser Schild gefallen, und die Stadt liegt offen im arkanen Chaos da: Zauber gehen fehl, Konstrukte laufen frei herum, und rohe Magie ergie\xdft sich durch die Stra\xdfen. Die Kirin Tor brauchen Hilfe, aber nur von Leuten, denen sie vertrauen.","Helden der Allianz gewinnen dieses Vertrauen, indem sie bei Emissary Jacques in S\xfcderstade beginnen; Helden der Horde beginnen bei Magus Wordeen Voidglare in Tarrens M\xfchle. Beide Wege f\xfchren zu einem Abbild der Erzmagierin Modera am S\xfcdufer des Lordamere-Sees, die den Dalaran Sewer Key aush\xe4ndigt. Von der Kanalisation aus w\xe4hlen die Gruppen ihren eigenen Weg durch die Stadt zur Quelle des \xdcbels; der letzte Gegner ist der Shade of the Archmage."],unknowns:["Was die St\xf6rung verursacht hat und wessen Schatten der letzte Gegner ist.","Wie weit der Wiederaufbau Dalarans gediehen ist."]},"instance:blackfathom-deeps":{title:"Tiefschwarze Grotte",summary:"Ein versunkener Tempel der Elune an der K\xfcste des Eschentals, heute ein Heiligtum, in dem Kultisten eine Bestie der Alten G\xf6tter umsorgen.",body:["Ein von Treppen umschlossener Schacht am Zoram Strand des Eschentals f\xfchrt hinab in \xfcberflutete Hallen, die einst einen Tempel der Elune bildeten, der Mondg\xf6ttin der Nachtelfen. Die Gro\xdfe Teilung zerbrach das Heiligtum und zog es unter das Meer, wo es zeitalterlang schlief, bis Naga und Satyrn kamen, um es zu erkunden, gierig nach der Macht, die dort noch immer verweilt.","Heute betet der Schattenhammer unter Twilight Lord Kelris in den tiefsten Becken und umsorgt Aku'mai, eine monstr\xf6se Bestie, die den Alten G\xf6ttern teuer ist. Schamanen des Irdenen Rings sind gekommen, um sie aufzuhalten, denn sie wissen, dass jede Beschw\xf6rung der Alten G\xf6tter die ganze Welt in Gefahr bringt."]},"instance:razorfen-kraul":{title:"Kral der Klingenhauer",summary:"Der Stammsitz der Stacheleber, gewachsen aus den Dornen, die aus dem Blut eines gefallenen Halbgottes sprossen.",body:["Die Stacheleber verehren Agamaggan, den gro\xdfen Eberhalbgott, der im Krieg der Ahnen get\xf6tet wurde. Wo sein Blut zu Boden fiel, brachen riesige Dornenranken aus der Erde, und ihr gr\xf6\xdftes Geflecht, im \xe4u\xdfersten S\xfcden des Brachlands, ist der Razorfen, den die Stacheleber als sein Grab ehren.","Der Kral der Klingenhauer ist ihre angestammte Heimat, ein Labyrinth aus dornengedeckten Bauen und Tunneln, \xfcber das Charlga Klingenflanke, die Vettel, herrscht. Priester des Stammes Death's Head wandeln bereits durch seine G\xe4nge, und Sp\xe4her berichten, dass sich in der Gegend Untote sammeln \u2013 eine Sorge, dass die Gei\xdfel Kalimdor ins Visier genommen hat."]},"instance:gnomeregan":{title:"Gnomeregan",summary:"Die verlorene Hauptstadt der Gnome in Dun Morogh, vergiftet von einer Strahlungss\xe4uberung nach einer Invasion der Troggs und dem Rat eines Verr\xe4ters.",body:["Tief im Innern der Berge von Dun Morogh erbaut, war Gnomeregan das gr\xf6\xdfte Ingenieurswunder der Gnome. Dann quollen Troggs aus der Tiefe herauf und \xfcberrannten die Stadt. Hocht\xfcftler Mekkadrill folgte dem Rat seines Beraters Sicco Thermaplugg und flutete die Stadt mit Strahlung, um die Eindringlinge zu t\xf6ten, doch die S\xe4uberung t\xf6tete auch die meisten Gnome. Die \xdcberlebenden flohen nach Eisenschmiede.","Es war Verrat. Thermaplugg blieb zur\xfcck, kr\xf6nte sich zum Herrn der Ruinen und befehligt nun Lepragnome, Troggs und verr\xfcckt gewordene Maschinen wie den Elektrokutor 6000 und den Meuteverpr\xfcgler 9-60. Die Verbannten haben geschworen, ihre Heimat zur\xfcckzuerobern."]},"instance:scarlet-monastery-graveyard":{title:"Scharlachrotes Kloster: Friedhof",summary:"Die Gr\xfcfte des Klosters des Scharlachroten Kreuzzugs, wo sein Verh\xf6rmeister arbeitet und die Toten keine Ruhe finden.",body:["Das Kloster im Norden von Tirisfal wurde als Haus der Studien f\xfcr die Priester Lordaerons erbaut. Nachdem die Gei\xdfel im Dritten Krieg \xfcber das K\xf6nigreich hinweggefegt war, nahmen die Eiferer des Scharlachroten Kreuzzugs es ein und machten es zu ihrer Festung. Sie verd\xe4chtigen jeden Nichtmenschen, die Seuche in sich zu tragen, und empfangen Fremde mit Klingen statt mit Fragen.","Der Friedhof ist der erste Fl\xfcgel, den die meisten Gruppen besuchen. Seine Zellen geh\xf6ren Verh\xf6rmeister Vishas, Blutmagier Thalnos lauert zwischen den Gr\xe4bern, und ruhelose Tote wie Azshir der Schlaflose, Eisenstachel und der gefallene Champion streifen durch die Gr\xfcfte."]},"instance:scarlet-monastery-library":{title:"Scharlachrotes Kloster: Bibliothek",summary:"Das Archiv des Scharlachroten Kreuzzugs, in dem ein Hundemeister und ein Arkanist die B\xfccher des Ordens bewachen.",body:["Einst kamen die Priester Lordaerons in dieses Kloster in Tirisfal, um zu studieren. Der Scharlachrote Kreuzzug, der es nach dem Dritten Krieg einnahm, behielt die B\xfccher, verlor aber die Sanftmut: Seine Eiferer glauben, dass jeder Nichtmensch die Seuche verbreiten k\xf6nnte, und sie bewachen ihr Archiv so erbittert wie ihre Mauern.","Hundemeister Loksey und seine Hunde jagen Eindringlinge in den \xe4u\xdferen Hallen, und Arkanist Doan wacht \xfcber die inneren Regale. Viele kommen wegen der B\xfccher selbst: Gelehrte in Eisenschmiede wollen einen Band \xfcber die Mythologie der Titanen, w\xe4hrend die Verlassenen die eigene Chronik des Kreuzzugs \xfcber die Gefallenen suchen."]},"instance:drowned-city":{title:"Drowned City",summary:"Uralte Trollruinen, die vor dem Schlingendorntal aus dem Meer aufgestiegen sind und in denen nun Trolle und Naga umherstreifen.",body:["Vor dem Schlingendorntal, westlich von Grom'gol, ist eine Trollstadt, die das Meer verschlungen hatte, wieder aufgetaucht. Stra\xdfen, die seit Zeitaltern niemand mehr betreten hat, liegen nun offen unter freiem Himmel, Trolle und Naga sind bereits eingezogen, und ein Piratenschiff in der N\xe4he scheint ein sehr b\xf6ses Ende gefunden zu haben.","Um hineinzugelangen, tauchen die Gruppen und suchen den Weg unterhalb der Wasserlinie. Drinnen k\xe4mpfen sie unter freiem Himmel, w\xe4hrend sich das Wetter verschlechtert: Aus Nebel wird Regen und aus Regen bis zum letzten Kampf ein ausgewachsener Sturm."],unknowns:["Warum die Stadt gerade jetzt aufgestiegen ist und welches Trollvolk sie erbaut hat.","Wer die Trolle und Naga im Inneren anf\xfchrt; die Daten dieses F\xfchrers nennen noch keine Bosse.","Was dem Piratenschiff widerfahren ist."]},"instance:scarlet-monastery-armory":{title:"Scharlachrotes Kloster: Waffenkammer",summary:"\xdcbungsgel\xe4nde und Arsenal des Scharlachroten Kreuzzugs, beherrscht von seinem Champion Herod.",body:["Hinter den Mauern des Klosters in Tirisfal drillt der Scharlachrote Kreuzzug seine Soldaten. Der Orden entstand aus dem Untergang Lordaerons im Dritten Krieg und glaubt, dass jeder, der kein Mensch ist, die Seuche in sich tragen k\xf6nnte; deshalb lernen seine Rekruten, als Erste zuzuschlagen.","Die Waffenkammer umfasst die \xdcbungspl\xe4tze, Kasernen und Waffenlager, und ihr Herr ist Herod, der scharlachrote Champion, ein riesiger Rohling, der eine gewaltige Axt schwingt und wirbelnd durch seine Angreifer fegt. Wer ihn besiegt, beweist, dass die Gruppe f\xfcr die Kathedrale im Herzen des Klosters bereit ist."]},"instance:razorfen-downs":{title:"H\xfcgel der Klingenhauer",summary:"Die uralten Begr\xe4bnisst\xe4tten der Stacheleber, von der Gei\xdfel unter dem Lich Amnennar dem K\xe4ltebringer erobert.",body:["Der H\xfcgel der Klingenhauer w\xe4chst aus denselben riesigen Dornen wie der Kral, und hier bestatten die Stacheleber ihre Toten. Ihre Hohepriester vom Stamm Death's Head hielten diese St\xe4tten einst heilig. Das \xe4nderte sich, als die Gei\xdfel Kalimdor erreichte: Der Lich Amnennar der K\xe4ltebringer nahm die Priester des Stammes in seinen Dienst und f\xfcllte das Dornengestr\xfcpp mit auferstandenen Toten.","Freie Stacheleber k\xe4mpfen nun darum, ihre Totenstadt zur\xfcckzugewinnen, bevor sich die Macht des Lichs \xfcber den Rest des Brachlands ausbreitet. Eine Gruppe muss sich an Tuten'kash, Mordresh Feuerauge, Vielfra\xdf und Seuchenschlund dem Faulenden vorbeik\xe4mpfen, um zu Amnennar selbst zu gelangen."]},"instance:scarlet-monastery-cathedral":{title:"Scharlachrotes Kloster: Kathedrale",summary:"Das Herz des Scharlachroten Klosters, wo Kommandant Mograine die Gl\xe4ubigen anf\xfchrt und Hochinquisitorin Wei\xdfstr\xe4hne die Gefallenen auferweckt.",body:["Die Kathedrale ist das Herz des Klosters des Scharlachroten Kreuzzugs in Tirisfal und der Sitz seiner dortigen Anf\xfchrer. Der scharlachrote Kommandant Mograine befehligt die eifernde Besatzung, doch die wahre Macht liegt bei Hochinquisitorin Wei\xdfstr\xe4hne, einer Priesterin, die ihren gefallenen Champion zur\xfcckrufen kann, damit er erneut k\xe4mpft.","Der Kreuzzug entstand aus dem Fall Lordaerons und sieht die Seuche noch immer in jedem Fremden. Hier brennt seine \xdcberzeugung am hei\xdfesten: Der Kommandant k\xe4mpft bis zuletzt, und wenn er f\xe4llt, tritt Wei\xdfstr\xe4hne aus dem Chorraum, um weiterzuk\xe4mpfen und ihn erneut zu erwecken."]}}},1727,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"instances2",{enumerable:!0,get:function(){return n}});const n={"instance:kroldok-stronghold":{title:"Krol'dok Stronghold",summary:"Eine Ogerfestung in den Riverglades, deren Pl\xfcnderer Reisende verschleppen und aus der nach Einbruch der Dunkelheit Ges\xe4nge aufsteigen.",body:["Krol'dok ist die Ogerfestung der Riverglades, und ihre Geschichte reicht zur\xfcck in die Jahre nach dem Zweiten Krieg. Als die Truppen der alten Horde in der Region Farholde Keep belagerten, schlich sich Fern Crimsonleaf in ihr Lager und t\xf6tete ihre Anf\xfchrer. F\xfchrerlos verlor das gr\xf6\xdfere Heer eine verlustreiche Schlacht gegen die Brotherhood of the Horse und floh zur\xfcck nach Krol'dok.","Nun schlagen ihre Oger-Vorreiter \xfcberall in den Riverglades zu, verschleppen Reisende und pl\xfcndern Siedlungen. Ihre Spur endet an einer weitl\xe4ufigen Festung aus Werkst\xe4tten, Lagern und streng bewachten G\xe4ngen. Gruppen dringen ein, um den \xdcberf\xe4llen ein Ende zu setzen und herauszufinden, was der seltsame Gesang bedeutet, der nach Einbruch der Dunkelheit aus der Festung aufsteigt."],unknowns:["Wer die Festung heute befehligt; die Daten dieses F\xfchrers nennen noch keine Bosse.","Was der Gesang ist und wer ihn anf\xfchrt.","Wie diese Oger mit dem Schattenhammer und den Bolder'ok-Ogern anderswo in den Riverglades zusammenh\xe4ngen."]},"instance:uldaman":{title:"Uldaman",summary:"Ein Gew\xf6lbe der Titanen im \xd6dland, in dem zwergische Ausgr\xe4ber die Troggs weckten und Hinweise auf ihre eigene Herkunft fanden.",body:["Uldaman ist ein Gew\xf6lbe, das die H\xfcter der Titanen tief im Innern der Berge von Khaz Modan versiegelten, im heutigen \xd6dland. Es sollte die Troggs verwahren, eine fr\xfche Sch\xf6pfung, die die Titanen als misslungen ansahen. Vor dem Dritten Krieg brachen Ausgr\xe4ber aus Eisenschmiede hinein, und die Troggs, die sie weckten, metzelten den gr\xf6\xdften Teil der Expedition nieder.","Nun k\xe4mpfen die Forscherliga, Dunkeleisenpl\xfcnderer und Troggst\xe4mme um seine Hallen. Tief im Innern liegen die Scheiben von Norgannon, Aufzeichnungen der Titanen, die enth\xfcllen, dass die Zwerge von den steinh\xe4utigen Irdenen abstammen. Sie werden von dem titanengeschmiedeten Archaedas bewacht, der sich noch immer gegen jeden erhebt, der sein Gew\xf6lbe st\xf6rt."]},"instance:zulfarrak":{title:"Zul'Farrak",summary:"Die sonnenverbrannte Stadt der Sandw\xfctertrolle in Tanaris, in der ein Hydragott in einem heiligen Teich schl\xe4ft.",body:["Tanaris war einst Dschungel und geh\xf6rte zu den L\xe4ndern der Gurubashitrolle, und Zul'Farrak war eine ihrer St\xe4dte. Als die Gro\xdfe Teilung die Region in eine W\xfcste verwandelte, passten sich die Farraki-Trolle, die dort zur\xfcckblieben, an und wurden zu Sandtrollen. Heute geh\xf6rt die Stadt dem Stamm der Sandw\xfcter, der f\xfcr seine Grausamkeit und seine dunkle Magie gef\xfcrchtet ist.","Abenteurer kommen aus vielen Gr\xfcnden. Ger\xfcchten zufolge liegen beide H\xe4lften des zerbrochenen Trollschwerts Sul'thraze der Peitscher hinter ihren Mauern, eine S\xf6ldnertruppe auf der Flucht aus Gadgetzan ist hineingestolpert und gefangen genommen worden, und in einem heiligen Teich im Herzen der Stadt schl\xe4ft Gahz'rilla, eine Hydra, die die Sandw\xfcter als Halbgott verehren und nur wecken, wenn sie Opfer darzubringen haben."]},"instance:alcaz-prison":{title:"Alcaz Prison",summary:"Ein lange nur ger\xfcchteweise bekanntes Gef\xe4ngnis auf Alcaz Island in den D\xfcstermarschen, das endlich offen steht und in dem Defias und Naga Krieg f\xfchren.",body:["In den D\xfcstermarschen wird seit Langem \xfcber Alcaz Island und die hochrangigen Gefangenen getuschelt, die dort angeblich festgehalten werden; manche Ger\xfcchte nennen sogar K\xf6nig Varian Wrynn von Sturmwind. Niemand konnte das Gef\xe4ngnis erreichen, um die Wahrheit herauszufinden. Nun stehen seine Tore offen.","Im Inneren bek\xe4mpfen sich die Defiasbruderschaft und die Naga. Gruppen nutzen das Chaos, um die Zellen zu durchsuchen, sich denen zu stellen, die sie kontrollieren, und neue Hinweise auf ein R\xe4tsel zu sammeln, das die K\xf6nigreiche bereits gut kennen."],unknowns:["Ob K\xf6nig Varian Wrynn hier gefangen ist oder war; der offizielle Text gibt nur Ger\xfcchte wieder.","Wer das Gef\xe4ngnis leitet und warum Defias und Naga gegeneinander k\xe4mpfen.","Welche Bosse im Inneren warten; die Daten dieses F\xfchrers nennen noch keine."]},"instance:maraudon":{title:"Maraudon",summary:"Heilige H\xf6hlen der Zentauren in Desolace, vergiftet von der Trauer der Erdprinzessin Theradras.",body:["Eine Legende erz\xe4hlt eine d\xfcstere Geschichte \xfcber die Geburt der Zentauren. Ihr Vater war Zaetar, ein Sohn des Halbgottes Cenarius; ihre Mutter war Prinzessin Theradras, die Tochter des Elementarf\xfcrsten der Erde. Die ersten Zentauren wandten sich gegen Zaetar und t\xf6teten ihn, und die trauernde Theradras soll seinen Geist in Maraudon gebunden haben \u2013 eine Tat, deren Verderbnis die H\xf6hlen bis heute vergiftet.","Die Zentaurenclans verehren Maraudon als heilige Grabst\xe4tte, doch nun f\xfcllen ruhelose Zentaurengeister, verdrehte Elementare und giftige Pflanzenwesen die Wicked Grotto, die Foulspore Cavern und die Earth Song Falls. Celebras, Zaetars Neffe, kam, um den Geist seines Onkels zu befreien, und erlag selbst der Verderbnis. Ganz unten wartet Theradras."]},"instance:temple-of-atalhakkar":{title:"Tempel von Atal'Hakkar",summary:"Der Versunkene Tempel in den S\xfcmpfen des Elends, wo Priester der Atal'ai noch immer ihren Blutgott Hakkar herbeizurufen versuchen.",body:["Die Atal'ai waren Trollpriester, die Hakkar den Seelenschinder, den Blutgott, in die Welt holen wollten, und der Kampf, sie aufzuhalten, zerriss vor mehr als tausend Jahren das Reich der Gurubashi. Geschlagen und vertrieben, errichteten sie in den S\xfcmpfen des Elends einen Tempel, um seine R\xfcckkehr vorzubereiten, bis der Aspekt Ysera den Plan entdeckte und den Tempel im Morast versenkte.","Seitdem bewachen gr\xfcne Drachen die versunkenen Ruinen, doch die Atal'ai haben \xfcberdauert und beten unter Jammal'an dem Propheten noch immer zu Hakkar. Weiter unten verweilt der Schemen von Eranikus, Yseras Gef\xe4hrte, dessen Geist vom Smaragdgr\xfcnen Albtraum verdunkelt ist."]},"instance:blackrock-depths":{title:"Schwarzfelstiefen",summary:"Die Stadt der Schattenschmiede, die Hauptstadt der Dunkeleisenzwerge tief im Schwarzfels, regiert von Imperator Dagran Thaurissan im Schatten Ragnaros'.",body:["Vor mehr als zwei Jahrhunderten versuchte der Dunkeleisen-Zauberthan Thaurissan, einen verlorenen Krieg mit einer verzweifelten Beschw\xf6rung zu gewinnen, und rief stattdessen Ragnaros den Feuerf\xfcrsten herbei. Die Explosion t\xfcrmte den Schwarzfels auf und band seinen Clan an den Willen des Feuerf\xfcrsten. Ihre Nachkommen schuften noch heute in den brennenden Tunneln unter dem Berg f\xfcr Ragnaros.","Die Schwarzfelstiefen sind ihr Reich: ein Gef\xe4ngnis, die Arena namens Ring des Gesetzes, die Taverne Zum Grimmigen S\xe4ufer, die Schwarze Schmiede und die Stadt der Schattenschmiede selbst. Dort sitzt Imperator Dagran Thaurissan auf seinem Thron, an seiner Seite Prinzessin Moira Bronzebart, deren Vater, K\xf6nig Magni von Eisenschmiede, glaubt, dass sie durch einen Zauber dort festgehalten wird."]},"instance:warpwood-quarter":{title:"Warpwood Quarter",summary:"Der \xf6stliche Bezirk des zerst\xf6rten Eldre'Thalas, \xfcberwuchert von verderbten Pflanzen unter dem Satyr Alzzin dem Wildformer.",body:["D\xfcsterbruch in Feralas war einst Eldre'Thalas, eine Stadt, in der die verschwiegensten Arkanisten K\xf6nigin Azsharas ihr kostbares Wissen h\xfcteten. Die Gro\xdfe Teilung lie\xdf sie zerbrochen zur\xfcck, und im Lauf der Zeitalter zogen Oger, Satyrn und noch seltsamere Wesen in ihre Bezirke.","Das Warpwood Quarter im Osten ist Alzzin dem Wildformer anheimgefallen, einem Satyr, der die Frucht der Fruchtbarkeit verdarb, sodass sie nun abscheuliche Teufelsranken hervorbringt. Verdrehte Urtume, Peitscher, D\xe4monen und Satyrn gehorchen ihm, und der ganze Bezirk ist verwildert. Selbst der schelmische Wichtel Pusillin liefert Eindringlingen eine fr\xf6hliche Verfolgungsjagd durch die Hallen."]},"instance:blackmaw-hold":{title:"Blackmaw Hold",summary:"Eine gro\xdfe Furbolgstadt hinter einem lange versiegelten Tor in Azshara, in der der Blackmaw-Clan gegen eine sich ausbreitende Verderbnis k\xe4mpft.",body:["Hinter einem Tor in Azshara, das sehr lange verschlossen blieb, liegt eine gro\xdfe Stadt der Furbolgs. Der Blackmaw-Clan, der dort lebt, k\xe4mpft gegen eine Verderbnis, die durch seine Haine und entlang der gewundenen Tunnel unter den Bergen sickert.","Die Festung ist ein langes Abenteuer f\xfcr Gruppen auf der H\xf6chststufe, mit mehreren Routen und vielen Bossen. In ihren tiefsten Bereichen soll sich ein Weg verbergen, der noch weiter unter Azeroth hinabf\xfchrt, und Blizzards Raid\xfcbersicht nennt Blackmaw Hold als einen der Zug\xe4nge zu den Barrow Deeps."],unknowns:["Was die Verderbnis ist und woher sie kommt.","Wer das Tor versiegelt hat und warum.","Welche Bosse im Inneren warten; die Daten dieses F\xfchrers nennen noch keine."]},"instance:lower-blackrock-spire":{title:"Untere Schwarzfelsspitze",summary:"Die unteren Hallen der Spitze auf dem Schwarzfels, Kaserne der Dunklen Horde von Rend Schwarzfaust.",body:["Jahrhundertelang war die Spitze, die den Schwarzfels kr\xf6nt, eine Festung der Dunkeleisenzwerge. Das endete, als Nefarian, der Sohn Todesschwinges, mit seiner Drachenbrut ihre oberen Ebenen einnahm und sich gegen die Zwerge wandte. Er fand einen Verb\xfcndeten in Rend Schwarzfaust, einem Orc, der sich Kriegsh\xe4uptling einer Dunklen Horde nennt, die Thrall nicht folgen will.","Die Untere Schwarzfelsspitze ist die Kaserne dieser Dunklen Horde. Legionen von Schwarzfelsorcs, Oger der Spirestone unter Hochlord Omokk, Trolle der Smolderthorn unter Schattenj\xe4ger Vosh'gajin und die Spinnen um Mutter Glimmernetz teilen sich ihre verfallenen Hallen unter dem Oberanf\xfchrer Wyrmthalak. Die Elite und die Drachen warten noch weiter oben, in der Oberen Schwarzfelsspitze."]},"instance:capital-gardens":{title:"Capital Gardens",summary:"Der westliche Bezirk von Eldre'Thalas, in dem sich die letzten Hochgeborenen der Shen'dralar von einem gefangenen D\xe4mon n\xe4hren.",body:["Eldre'Thalas, heute D\xfcsterbruch genannt, wurde erbaut, um die arkanen Geheimnisse K\xf6nigin Azsharas zu bewahren, und seine H\xfcter, die Shen'dralar, \xfcberlebten die Gro\xdfe Teilung. Abgeschnitten von der Macht des Brunnens der Ewigkeit, lie\xdf ihr Anf\xfchrer, Prinz Tortheldrin, f\xfcnf Pylonen errichten, um den D\xe4mon Immol'thar einzusperren, und sein Volk zapfte dessen Energie an, um unsterblich zu bleiben.","Im Lauf der Jahrhunderte wurde das Gef\xe4ngnis schw\xe4cher. Um seine eigene Macht zu bewahren, wandte sich Tortheldrin gegen die anderen Shen'dralar und saugte sie aus. Die Capital Gardens, einst Park und Hof der Hochgeborenen, beherbergen nun seine letzten treuen Anh\xe4nger, verdorrte B\xe4ume, zornige Urtume und den gefangenen D\xe4mon selbst."]},"instance:scholomance":{title:"Scholomance",summary:"Kel'Thuzads Schule der Nekromantie in den Gr\xfcften unter Caer Darrow, von der Familie Barov der Gei\xdfel \xfcberlassen.",body:["Auf einer Insel im Darrowmere-See in den Westlichen Pestl\xe4ndern steht Caer Darrow, einst die Burg der adligen Familie Barov. Als der Zauberer Kel'Thuzad Anh\xe4nger f\xfcr seinen Kult der Verdammten sammelte, versprach er im Namen des Lichk\xf6nigs Unsterblichkeit, und die Barovs \xfcberlie\xdfen ihm ihre Burg samt Gr\xfcften. Der Kult machte aus den Gr\xfcften die Scholomance, eine Schule, in der Nekromanten ausgebildet wurden, um die Seuche zu verbreiten.","Die Barovs bekamen ihren Wunsch auf die schlimmste Weise erf\xfcllt und spuken nun als Untote durch die Hallen. Der Lich Ras Frostraunen beherrscht die Schule f\xfcr die Gei\xdfel, Dunkelmeister Gandling dient als ihr Schulleiter, und der Ravenier lauert in der Tiefe, bereit, schwache Sch\xfcler zu verschlingen."]},"instance:shapers-terrace":{title:"Shaper's Terrace",summary:"Eine uralte Anlage der Titanen in den n\xf6rdlichen H\xfcgeln des Kraters von Un'Goro, die mit \xfcberall im Krater gesammelten Machtkristallen betrieben wird.",body:["Auf den n\xf6rdlichen H\xf6hen des Kraters von Un'Goro blickt eine uralte Anlage der Titanen auf ein Land hinab, das die Zeit verschont zu haben scheint. Dinosaurier, Teergruben, Bauwerke der Titanen und leuchtende Kristalle geh\xf6ren alle zu dieser Expedition, die f\xfcr Gruppen nahe der H\xf6chststufe gedacht ist.","Ihr R\xe4tsel reicht \xfcber die Mauern hinaus: Die Gruppen sammeln drau\xdfen im Krater Machtkristalle und setzen sie an Konsolen im Inneren der Terrasse ein, sodass das, was sie in der Wildnis finden, die Herausforderungen im Inneren pr\xe4gt."],unknowns:["Wer die Terrasse erbaut hat und wozu sie diente.","Was die Konsolen bewirken und welche Bosse im Inneren warten; die Daten dieses F\xfchrers nennen noch keine."]},"instance:stratholme":{title:"Stratholme",summary:"Die brennende Ruine der gro\xdfen Stadt im Norden Lordaerons, geteilt zwischen der Gei\xdfel von Baron Totenschwur und dem Scharlachroten Kreuzzug.",body:["Stratholme war die stolzeste Stadt im Norden Lordaerons und der Geburtsort des Ordens der Silbernen Hand. Im Dritten Krieg lie\xdf Prinz Arthas die Stadt niedermachen, statt zuzulassen, dass sich ihre von der Seuche ber\xfchrten Bewohner als Untote erhoben, und brach damit mit seinem Mentor Uther. Bald darauf zog die Gei\xdfel ein, und seither brennt die Stadt.","Heute teilen sich zwei Feinde die Stadt. Der Scharlachrote Kreuzzug h\xe4lt die eine Seite unter Gro\xdfkreuzz\xfcgler Dathrohan und ahnt nicht, dass dieser in Wahrheit der verkleidete Schreckenslord Balnazzar ist. Die andere Seite geh\xf6rt der Gei\xdfel und dem Todesritter Baron Totenschwur, einem reichen Grundbesitzer aus Stratholme und Freund Kel'Thuzads, bevor er sich dem Kult der Verdammten anschloss."]},"instance:gordok-commons":{title:"Gordok Commons",summary:"Der n\xf6rdliche Bezirk von D\xfcsterbruch, Sitz von K\xf6nig Gordok und seinen Ogern, wo derjenige die Krone erh\xe4lt, der den K\xf6nig t\xf6tet.",body:["Oger vom Clan der Gordunni haben das n\xf6rdliche Viertel des alten Eldre'Thalas \xfcbernommen, der zerst\xf6rten Stadt der Hochgeborenen, die heute D\xfcsterbruch hei\xdft. Ihre st\xe4rksten Krieger, die Gordok, herrschen von den Commons aus, und ihr K\xf6nig tr\xe4gt den Namen K\xf6nig Gordok.","Der Brauch der Oger ist hier einfach: Wer den K\xf6nig erschl\xe4gt, wird der neue K\xf6nig Gordok. Geschickte Gruppen schleichen an den Wachen Mol'dar, Fengus und Slip'kik, an Stampfer Kreeg und Hauptmann Krombruch vorbei, um nur den K\xf6nig anzugreifen, und die \xfcberlebenden Oger behandeln die Sieger als ihre neuen Herrscher und zahlen ihnen Tribut. Cho'Rush der Beobachter steht an der Seite des K\xf6nigs."]},"instance:barrow-deeps":{title:"Barrow Deeps",summary:"Ein Schlachtzug f\xfcr zehn Spieler in das Gef\xe4ngnis unter Kalimdor, das Illidan Sturmgrimm zehntausend Jahre lang festhielt.",body:["Tief unter Kalimdor hielten die Barrow Deeps Illidan Sturmgrimm zehntausend Jahre lang gefangen. Nun steht der Weg in ihre Tunnel offen, und Schlachtz\xfcgler steigen hinab, um herauszufinden, was mit denen geschehen ist, die in der Dunkelheit zur\xfcckblieben, und was die W\xe4chterinnen gegen die Bedrohung tun wollen, die sich in der Tiefe regt.","Drei Wege f\xfchren hinein, verbunden mit dem Berg Hyjal, mit Winterquell und mit Blackmaw Hold. Auf dem Weg hinab stellen sich zehn Spieler acht Bossen, von der Deepscar Matriarch und Khalith the Dreadspinner bis zu Del'lynar Songwood und ganz zuletzt Sonya Darkhallow."],unknowns:["Wer die Durchg\xe4nge ge\xf6ffnet hat und was die Gefahr in der Tiefe ist.","Wer die W\xe4chterinnen sind und welche Geschichten die acht Bosse haben."]},"instance:hyjal-summit":{title:"Hyjal Summit",summary:"Ein Schlachtzug f\xfcr zwanzig Spieler auf dem Gipfel des Berges Hyjal nahe dem Weltenbaum Nordrassil, mit dreizehn Bossen und vielen Wegen.",body:["Hyjal Summit liegt auf dem Gipfel des Berges Hyjal, nahe dem Weltenbaum Nordrassil. Ein uralter W\xe4chter versperrt zu Beginn den Weg; danach w\xe4hlen die Schlachtz\xfcgler ihre eigenen Routen \xfcber den Berg, durch Ruinen an der Oberfl\xe4che und darunter, und bek\xe4mpfen alles, was Hyjal bedroht, bis sich der Weg zu den letzten K\xe4mpfen \xf6ffnet.","Zwanzig Spieler stellen sich dreizehn Bossen, darunter Bandalar, dem Time-Lost Battalion, dem Council of Thorns, dem Wild King und dem Ancient of Decay. Der letzte von allen ist Nythus the Dreambound."],unknowns:["Welche Macht Hyjal bedroht; die offizielle \xdcbersicht nennt sie nicht.","Wer der uralte W\xe4chter ist und wer Nythus the Dreambound ist."]},"instance:onyxias-lair":{title:"Onyxias Hort",summary:"Der Hort Onyxias, der Brutmutter des schwarzen Drachenschwarms, in den D\xfcstermarschen; nur Tr\xe4ger des Drachenfeueramuletts d\xfcrfen eintreten.",body:["Im Wyrmbog der D\xfcstermarschen bewacht Onyxia, Tochter Todesschwinges und Schwester Nefarians, ihre Brut in einer H\xf6hle aus Feuer. Ihre gr\xf6\xdfere Waffe ist die T\xe4uschung. In menschlicher Gestalt als Lady Katrana Prestor fl\xfcstert sie am Hof von Sturmwind und arbeitet daran, die K\xf6nigreiche der Sterblichen gegeneinander aufzuhetzen.","Vierzig Spieler stellen sich ihr in einem Kampf aus Flammen mit drei Phasen, daher sammeln Schlachtz\xfcge zuerst Feuerwiderstand. Jedes Mitglied muss au\xdferdem das Drachenfeueramulett tragen, das man sich durch eine lange Questreihe verdient: die Allianz \xfcber die Flucht von Marschall Windsor aus den Schwarzfelstiefen und die Entlarvung in Sturmwind, die Horde \xfcber Rexxar und den Drachen Glutsturm; beide enden bei General Drakkisath in der Oberen Schwarzfelsspitze."]}}},1728,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"items",{enumerable:!0,get:function(){return n}});const n={"item:demon-soul":{title:"Die Drachenseele (D\xe4monenseele)",summary:"Eine goldene Scheibe, die Neltharion schmiedete, um alle Drachen zu beherrschen; sie lie\xdf Todesschwinge entstehen und kettete Zeitalter sp\xe4ter den roten Drachenschwarm an die Horde.",body:["Vor dem Krieg der Ahnen lie\xdf der Erdw\xe4chter Neltharion von seinen Goblindienern eine schlicht wirkende goldene Scheibe anfertigen, die heimlich von der Verderbnis der Alten G\xf6tter durchdrungen war. Er \xfcberredete die anderen Aspekte, einen Teil ihrer Macht hineinzugie\xdfen, um die Brennende Legion zu bek\xe4mpfen, und richtete sie dann gegen D\xe4monen und Verb\xfcndete gleicherma\xdfen. Die Energien der Drachenseele zerrissen seinen K\xf6rper, und Neltharion wurde zu Todesschwinge.","Nach der Gro\xdfen Teilung verbargen die Aspekte die Scheibe tief unter dem heutigen Rotkammgebirge. Den Visionen Todesschwinges folgend, barg der Drachenmalclan sie, nannte sie D\xe4monenseele und versklavte damit Alexstrasza in Grim Batol. Dort wurde sie schlie\xdflich zerschmettert, und die roten Drachen kamen frei."]},"item:atiesh":{title:"Atiesh, Hohestab des W\xe4chters",summary:"Der Stab der W\xe4chter von Tirisfal, zuletzt von Medivh getragen, sp\xe4ter zerbrochen und von Kel'Thuzad gejagt.",body:["Atiesh ging \xfcber Generationen von W\xe4chter zu W\xe4chter und endete bei Medivh, dem letzten von ihnen. Legenden besagen, dass er aus einem \u201eSamen des Hasses\u201c wuchs und seinem Tr\xe4ger endlose Macht verleiht; Raben sammeln sich um ihn, und er kann einen Weg nach Karazhan \xf6ffnen. Nach Medivhs Sturz schlossen die Kirin Tor den Stab in Dalaran weg, wo jeder Magier, der ihn ber\xfchrte, ein grausiges Ende fand.","Als Archimonde Dalaran zerst\xf6rte, zerbrach Atiesh in Dutzende St\xfccke, die sich \xfcber ganz Azeroth verstreuten, und Kel'Thuzad machte sich daran, sie zu sammeln. Im urspr\xfcnglichen Spiel entrissen Schlachtz\xfcgler die Splitter seiner Nekropole Naxxramas, lie\xdfen den Rahmen mit Hilfe des bronzenen Drachen Anachronos wiederherstellen und mussten den Stab dann in Stratholme reinigen, indem sie den in ihm gefangenen D\xe4mon besiegten."]},"item:scepter-of-the-shifting-sands":{title:"Das Szepter der Sandst\xfcrme",summary:"Der Schl\xfcssel zum Skarab\xe4uswall, der Ahn'Qiraj versiegelte, zerbrochen von einem trauernden Fandral Hirschhaupt.",body:["Fast tausend Jahre vor dem Ersten Krieg str\xf6mten die insektoiden Qiraji aus Ahn'Qiraj hervor, angestachelt vom Alten Gott C'Thun. Erzdruide Fandral Hirschhaupt f\xfchrte die Nachtelfen gegen sie, doch sein Sohn Valstann wurde vor seinen Augen niedergemacht, und das Kriegsgl\xfcck wendete sich. Erst mit der Hilfe von vier Drachenschw\xe4rmen wurden die Schw\xe4rme zur\xfcckgedr\xe4ngt und hinter dem Skarab\xe4uswall eingeschlossen.","Der Wall lie\xdf sich nur \xf6ffnen, indem man mit diesem Szepter den Skarab\xe4usgong schlug. Fandral zerschmetterte es in der Wut seiner Trauer, und seine Teile wurden verstreut. Im urspr\xfcnglichen Spiel setzten Abenteurer das Szepter wieder zusammen, schlugen den Gong und \xf6ffneten Ahn'Qiraj erneut."]},"item:doomhammer":{title:"Schicksalshammer",summary:"Der Erbkriegshammer der Familie Schicksalshammer, den Orgrim durch zwei Kriege trug und Thrall \xfcbergab.",body:["Vor langer Zeit auf Draenor geschmiedet, ging der gro\xdfe Hammer aus schwarzem Stein innerhalb einer einzigen Orcfamilie vom Vater auf den Sohn \xfcber, und \xfcber ihm hing eine alte Prophezeiung des Schwarzfelsklans: Der Letzte der Linie werde den Orcs zuerst die Erl\xf6sung und dann den Untergang bringen, bevor ein Fremder den Hammer f\xfcr die Gerechtigkeit erhebe. Orgrim Schicksalshammer f\xfchrte ihn im Ersten und Zweiten Krieg und erschlug damit Anduin Lothar, wobei er die Runenklinge des Ritters zerschmetterte.","Nach der Niederlage der Horde entkam Orgrim der Gefangenschaft und k\xe4mpfte darum, sein Volk aus den Internierungslagern zu befreien. In einer dieser Schlachten t\xf6dlich verwundet, gab er den Hammer Thrall, der weder seinem Clan noch seinem Blut angeh\xf6rte. Thrall trug ihn als Symbol einer wiedergeborenen Horde, und die Prophezeiung fand ihren Fremden."]},"item:book-of-medivh":{title:"Das Buch des Medivh",summary:"Medivhs letztes erhaltenes Zauberbuch, mit dem zweimal der Weg zwischen den Welten aufgerissen wurde.",body:["Nach Medivhs Tod wurde sein Zauberbuch in der k\xf6niglichen Bibliothek des wiederaufgebauten Sturmwind aufbewahrt, bis Agenten Alteracs es stahlen. Durch einen Handel zwischen dem K\xf6nig von Alterac und dem Todesritter der Horde Teron Blutschatten gelangte es zu den Orcs, und auf Draenor nutzte Ner'zhul es zusammen mit anderen Relikten, um neue Portale zu \xf6ffnen \u2013 Risse, die seine Welt zerrissen. Bevor das Dunkle Portal fiel, holte Khadgar das Buch zur\xfcck und schickte es per Greif nach Hause.","Die Kirin Tor versiegelten es in einem Gew\xf6lbe in Dalaran. Im Dritten Krieg zerschmetterte Kel'Thuzad dieses Gew\xf6lbe und \xf6ffnete mit der Macht des Buches den Riss, durch den Archimonde und die Brennende Legion Azeroth betraten. Danach blieb das Buch in den H\xe4nden des Lichs."]},"item:frostmourne":{title:"Frostgram",summary:"Die Runenklinge des Lichk\xf6nigs, die im Eis von Nordend die Seele von Arthas Menethil forderte.",body:["Frostgram war an das Gef\xe4ngnis des Lichk\xf6nigs in Eiskrone gebunden, und Ner'zhul stie\xdf es aus dem Frostthron hinaus, um einen Champion anzulocken. Es wartete bewacht in einer gefrorenen H\xf6hle in Nordend und trug eine Warnung, dass seine Macht die Seele dessen zeichnen werde, der es ergreife. Prinz Arthas, der verzweifelt die Seuche aufhalten wollte, missachtete die Warnung und packte die Klinge, w\xe4hrend Muradin Bronzebart, von einem Eissplitter getroffen, am Boden lag.","Das Schwert verschlingt die Seelen derer, die es t\xf6tet. Damit t\xf6tete Arthas den Schreckenslord Mal'Ganis, dann seinen eigenen Vater, K\xf6nig Terenas, und seinen alten Mentor Uther. Im Jahr 25 ruht es an der Seite des Lichk\xf6nigs selbst. In sp\xe4teren Geschichten, jenseits von Classic, zerschlug Tirion Fordring es mit dem Aschenbringer."]},"item:ashbringer":{title:"Der Aschenbringer",summary:"Eine heilige Klinge, in Eisenschmiede geschmiedet, um Untote zu Asche zu verbrennen, dann verraten und in den Pestl\xe4ndern verderbt.",body:["Im Zweiten Krieg fand Hochlord Alexandros Mograine von der Silbernen Hand bei einem erschlagenen Hexenmeister der Orcs einen dunklen Kristall. Als die Gei\xdfel Lordaeron bedrohte, versuchten die Anf\xfchrer des Ordens, ihn mit heiliger Magie zu zerst\xf6ren; stattdessen sog der Kristall das Licht in sich auf und begann zu strahlen. K\xf6nig Magni Bronzebart schmiedete ihn auf dem Gro\xdfen Amboss von Eisenschmiede zu einem Schwert, und in Mograines H\xe4nden verwandelte der Aschenbringer die Untoten zu Asche.","Der Schreckenslord Balnazzar und Kel'Thuzad planten seinen Sturz. Mograines Sohn Renault f\xfchrte ihn in Stratholme in einen Hinterhalt der Gei\xdfel und t\xf6tete ihn mit seinem eigenen Schwert, wodurch er es verdarb. Im Jahr 25 dient Alexandros Kel'Thuzad als Todesritter, w\xe4hrend Renault das Scharlachrote Kloster befehligt. Erst in sp\xe4teren Geschichten wurde die Klinge gereinigt."]},"item:skull-of-guldan":{title:"Der Sch\xe4del von Gul'dan",summary:"Der Sch\xe4del des Hexenmeisters, ein d\xe4monisches Relikt, das Portale \xf6ffnete, das Eschental vergiftete und Illidan verwandelte.",body:["Gul'dan wurde im Grabmal des Sargeras von D\xe4monen zerrissen, doch sein Sch\xe4del bewahrte einen Splitter seiner Bosheit. Er ging durch die H\xe4nde mehrerer Orcs, bis Grom H\xf6llschrei ihn zu Ner'zhul brachte, der ihn nutzte, um das Dunkle Portal wieder zu \xf6ffnen. Khadgar schickte ihn sp\xe4ter zusammen mit dem Buch des Medivh nach Dalaran, und die Kirin Tor bewachten beides.","Als Dalaran im Dritten Krieg fiel, stahl der Schreckenslord Tichondrius den Sch\xe4del, und seine Macht verdarb die W\xe4lder des Eschentals und des Teufelswalds. Illidan Sturmgrimm verzehrte seine Magie, wurde zur H\xe4lfte zum D\xe4mon und erschlug Tichondrius mit dieser Macht. Die H\xfclle des Sch\xe4dels blieb bei Illidan."]},"item:gorehowl":{title:"Blutschrei",summary:"Die heulende Axt der Familie H\xf6llschrei, die sowohl Cenarius als auch Mannoroth f\xe4llte.",body:["Blutschrei wurde Generationen vor Grom H\xf6llschrei geschmiedet, der die Axt erbte, und eine Legende der Kriegshymnen besagt, sie sei mit den Herzen m\xe4chtiger Gronn geh\xe4rtet worden. Grom, H\xe4uptling des Kriegshymnenklans, trank als Erster das Blut des Grubenlords Mannoroth und band die Orcs damit an die Brennende Legion. Im Eschental trank er erneut und erschlug mit Blutschrei den Halbgott Cenarius.","Thrall befreite ihn aus dem Griff des D\xe4mons, und gemeinsam stellten sie sich Mannoroth. Grom spaltete die Waffe des Grubenlords und t\xf6tete ihn mit einem einzigen Hieb; so brach er den Fluch, der auf seinem Volk lag, um den Preis seines eigenen Lebens. Thrall bewahrte die Axt danach in Orgrimmar auf."]},"item:horn-of-cenarius":{title:"Das Horn des Cenarius",summary:"Das Horn des Halbgottes, das die Druiden aus ihrem langen Schlaf weckte und am Hyjal die Ahnen der Nachtelfen herbeirief.",body:["Nach dem Fall des Cenarius blieb sein Horn auf der Mondlichtung, bewacht von uralten H\xfctern. Als die Brennende Legion im Dritten Krieg zur\xfcckkehrte, holte die Priesterin Tyrande Wisperwind es zur\xfcck und weckte damit Malfurion Sturmgrimm aus seinem langen Tr\xe4umen. Malfurion wiederum blies es, um die schlafenden Druiden der Kralle und der Klaue zu wecken.","Auf dem H\xf6hepunkt der Schlacht um den Berg Hyjal blies Malfurion das Horn ein weiteres Mal. Tausende Ahnengeister antworteten und fielen \xfcber Archimonde her; sie vernichteten den D\xe4monenf\xfcrsten am Fu\xdf des Weltenbaums, doch die entfesselte Macht lie\xdf Nordrassil verwundet zur\xfcck."]},"item:sulfuras":{title:"Sulfuras, Hand von Ragnaros",summary:"Der brennende Hammer des Feuerf\xfcrsten und die kleinere Nachbildung, die Meisterschmiede nach seinem Vorbild zu schmieden lernten.",body:["Sulfuras ist der gewaltige Hammer von Ragnaros, eine Masse aus flammendem rotem Elementium, die der Feuerf\xfcrst niemals losl\xe4sst. In den Elementarkriegen der fernen Vergangenheit erschlug er damit Thunderaan, den Prinzen der Luft. Seit Thaurissans Beschw\xf6rung herrscht Ragnaros mit dem Hammer in der Hand \xfcber den Geschmolzenen Kern unter dem Schwarzfels.","Die wahre Waffe ist f\xfcr sterbliche H\xe4nde viel zu gewaltig, doch ihr Abbild l\xe4sst sich herstellen. Im urspr\xfcnglichen Spiel verdiente sich ein Meisterschmied bei Lokhtos D\xfcsterfeilsch von der Thoriumbruderschaft in den Schwarzfelstiefen die Pl\xe4ne f\xfcr einen Sulfuronhammer und verband ihn dann mit dem seltenen Auge von Sulfuras, das Ragnaros selbst abgenommen wurde \u2013 so entstand eine Hand von Ragnaros in sterblicher Gr\xf6\xdfe."]},"item:thunderfury":{title:"Donnerzorn, Gesegnete Klinge des Windsuchers",summary:"Ein Schwert, geschmiedet um die letzte Essenz von Thunderaan, dem Prinzen der Luft, den Ragnaros eingekerkert hatte.",body:["In einem uralten Krieg zwischen Feuer und Luft besiegten Ragnaros und seine Leutnants Garr und Baron Geddon Thunderaan, den Prinzen der Luft. Der Feuerf\xfcrst n\xe4hrte sich von seiner Essenz, konnte sie aber nicht ganz verschlingen; also versiegelte er den Rest in einem Talisman, brach ihn entzwei und gab jedem Leutnant eine H\xe4lfte: die Bindungen des Windsuchers.","Im urspr\xfcnglichen Spiel nahmen Schlachtz\xfcgler Garr und Geddon im Geschmolzenen Kern beide H\xe4lften ab und brachten sie zu Hochlord Demitrian in Silithus. Mit der Essenz des Feuerf\xfcrsten selbst und Barren aus verzaubertem Elementium beschworen die Bindungen den geschw\xe4chten Prinzen; nach seiner Niederlage schmiedete Demitrian seine verbliebene Macht zu Donnerzorn, einer Klinge, in der lebendiger Sturm knistert."]},"item:seal-of-ascension":{title:"Siegel des Aufstiegs",summary:"Ein in schwarzem Drachenfeuer geschmiedeter Ring, der die obere Zitadelle der Schwarzfelsspitze \xf6ffnete.",body:["Die oberen Hallen der Schwarzfelsspitze, in denen Rend Schwarzfaust und der schwarze Drachenschwarm Hof hielten, waren gegen Eindringlinge versiegelt. In der unteren Spitze lehrte ein verkleideter Fremder namens Vaelan \u2013 in Wahrheit der rote Drache Vaelastrasz, der geschworen hatte, Nefarian zu jagen \u2013 Abenteurer, einen Schl\xfcssel anzufertigen: ein schmuckloses Siegel, besetzt mit drei Edelsteinen, die man den Anf\xfchrern der Smolderthorn, der Spirestone und der Blutaxt in der Spitze abnahm.","Danach musste das Siegel in schwarzem Drachenfeuer geschmiedet werden. Helden reisten zum Wyrmbog in den D\xfcstermarschen und zwangen den Drachen Glutsturm, es anzuhauchen. Der fertige Ring \xf6ffnete die obere Zitadelle und konnte im Kampf gegen Rend ein Abbild von Vaelastrasz an die Seite der Helden rufen."]},"item:drakefire-amulet":{title:"Drachenfeueramulett",summary:"Onyxias zerbrochener Talisman, mit dem Blut eines schwarzen Drachen zum Schl\xfcssel f\xfcr ihren eigenen Hort umgearbeitet.",body:["Als Lady Katrana Prestor verkleidet, schlich sich Onyxia mit einem Anh\xe4nger namens Drachenauge an den Hof von Sturmwind. Er beherrschte den Geist nicht unmittelbar, weckte aber verborgene Begierden und lenkte den Verdacht von ihr ab. Als Marschall Windsor die Maskerade aufdeckte, zersprang der Anh\xe4nger, und der blaue Drache Haleh f\xfcgte seine Teile mit dem Blut von General Drakkisath zum Drachenfeueramulett zusammen.","Helden der Horde gelangen auf einem anderen Weg zum selben Amulett, \xfcber Rexxar und die Pr\xfcfungen des uralten Drachen Glutsturm. Jeder Schlachtz\xfcgler, der Onyxias Hort betritt, muss es tragen, und Forever beh\xe4lt diese Einstimmung als eigene Questreihe f\xfcr jede Fraktion bei."]},"item:head-of-onyxia":{title:"Kopf von Onyxia",summary:"Der Beweis f\xfcr den Tod der Brutmutter, \xfcber den Toren von Sturmwind oder Orgrimmar als Sammelbanner aufgeh\xe4ngt.",body:["Onyxia, Tochter Todesschwinges und j\xfcngere Schwester Nefarians, bewacht ihre Brut in einer H\xf6hle der D\xfcstermarschen und schmiedet zugleich Pl\xe4ne, die K\xf6nigreiche der Sterblichen auf Azeroth ihrem Willen zu unterwerfen. Ihr Tod beendete eine der l\xe4ngsten T\xe4uschungen des schwarzen Drachenschwarms.","Im urspr\xfcnglichen Spiel wurde ihr Kopf als Troph\xe4e heimgebracht: Champions der Allianz \xfcberreichten ihn in Sturmwind, Champions der Horde Thrall in Orgrimmar. \xdcber den Stadttoren aufgeh\xe4ngt, verlieh er allen in der Stadt den Schlachtruf des Drachent\xf6ters, und die ganze Hauptstadt feierte den Sieg."]},"item:quel-serrar":{title:"Quel'Serrar",summary:"Eine uralte Klinge der Nachtelfen, von den Shen'dralar verwahrt und erst im Atem eines Drachen vollendet.",body:["Quel'Serrar ist eine der prismatischen Klingen, die Schmiede der Nachtelfen vor langer Zeit mit Hilfe der Drachenschw\xe4rme schufen; ihre Zwillingsklinge Quel'Delar wurde den Hochelfen geschenkt. Jahrtausendelang verwahrten die Shen'dralar von Eldre'Thalas sie und warteten auf einen Tr\xe4ger, der stark genug w\xe4re, sie zu erwecken.","Im urspr\xfcnglichen Spiel brachte ein Krieger oder Paladin, der ein altes Kompendium \xfcber die Drachenjagd gefunden hatte, es zu H\xfcter des Wissens Lydros in der Bibliothek von D\xfcsterbruch und erhielt eine ungeh\xe4rtete Klinge. Von Onyxias tiefem Atem erhitzt und in den erschlagenen Drachen gesto\xdfen, wurde der Stahl zu Quel'Serrar, sobald er zu Lydros zur\xfcckgebracht war."]},"item:rhokdelar":{title:"Rhok'delar und Lok'delar",summary:"Ein lebendiger Langbogen und ein Stab, geformt von den verderbten Urtumen des Teufelswalds f\xfcr den J\xe4ger, der sie r\xe4chte.",body:["Als die Brennende Legion \xfcber Kalimdor hinwegfegte, vergiftete sie das Tal, aus dem der Teufelswald wurde. Seine m\xe4chtigsten Urtume verdorrten zu versteinerten H\xfcllen, doch ihre Geister blieben. Ein Blatt eines von ihnen, Vartrus, landete im Schatz des Feuerf\xfcrsten im Geschmolzenen Kern.","Im urspr\xfcnglichen Spiel wurde ein J\xe4ger, der das Blatt zu Vartrus zur\xfcckbrachte, ausgesandt, vier Agenten der Legion allein zu jagen, ohne auch nur ein Tier an seiner Seite. Zum Dank fertigten die Urtume Rhok'delar, einen Langbogen, an dem von selbst Bl\xfcten sprie\xdfen, und seinen Gef\xe4hrten Lok'delar, einen Stab, der mit der Macht der Natur leuchtet."]},"item:taelans-hammer":{title:"Taelans Hammer",summary:"Der Spielzeughammer eines Kindes, der Tirion Fordring half, den Sohn zu erreichen, den ihm der Scharlachrote Kreuzzug genommen hatte.",body:["Zu seinem siebten Geburtstag bekam der junge Taelan von seinem Vater Tirion Fordring einen kleinen Kriegshammer, eine Nachbildung von Tirions eigenem. Nachdem Tirion verbannt worden war, weil er den Orc Eitrigg verteidigt hatte, erz\xe4hlte Taelans Mutter dem Jungen, sein Vater sei tot, und brachte ihn zu einem falschen Grab im Undercroft in den \xd6stlichen Pestl\xe4ndern, wo er den Hammer und mit ihm die Erinnerung begrub.","Jahre sp\xe4ter stieg Taelan zum Hochlord des Scharlachroten Kreuzzugs in Herdweiler auf. Im urspr\xfcnglichen Spiel holten Abenteurer den Hammer f\xfcr den alternden Tirion zur\xfcck und halfen Taelan zu erkennen, was aus dem Kreuzzug geworden war. Als er aus Herdweiler floh, streckte ihn Gro\xdfinquisitor Isillien vor den Augen seines Vaters nieder; Tirion erschlug Isillien und gelobte, die Silberne Hand neu zu schmieden."]},"item:heart-of-hakkar":{title:"Herz von Hakkar",summary:"Das noch immer gl\xfchende Herz des Blutgottes, das zu den Zandalari gebracht wurde, nachdem Hakkar in Zul'Gurub erschlagen worden war.",body:["Etwa f\xfcnfzehn Jahrhunderte vor dem Dunklen Portal wandten sich die hungernden Gurubashitrolle an Hakkar den Seelenschinder, einen Loa des Blutes. Er gab ihnen Macht und ein Reich und verlangte dann immer mehr Leben, bis sich die St\xe4mme gegen ihn erhoben und seine Priester der Atal'ai verbannten. Als die Priester einen Tempel errichteten, um ihn zur\xfcckzuholen, zerschmetterte Ysera ihn und versenkte ihn im Morast der S\xfcmpfe des Elends.","Im urspr\xfcnglichen Spiel zogen die Priester der Hakkari den Seelenschinder schlie\xdflich nach Zul'Gurub. Helden, die der Stamm der Zandalar gesammelt hatte, erschlugen ihn dort und brachten sein noch gl\xfchendes Herz zu Molthor auf der Insel Yojamba, dessen Ritual alle auf der Insel und in Beutebucht mit dem Geist von Zandalar segnete."]},"item:phylactery-of-kelthuzad":{title:"Das Phylakterium von Kel'Thuzad",summary:"Das Gef\xe4\xdf, das die Seele des Erzlichs birgt, nach seiner Niederlage aus Naxxramas geholt.",body:["Kel'Thuzad, einst Erzmagier der Kirin Tor, gr\xfcndete den Kult der Verdammten und verbreitete die Seuche f\xfcr den Lichk\xf6nig. Von Arthas erschlagen und sp\xe4ter zum Sonnenbrunnen gebracht, um als Lich wiedergeboren zu werden, herrschte er schlie\xdflich von der schwebenden Nekropole Naxxramas aus \xfcber die Gei\xdfel in Lordaeron.","Ein Lich besteht fort, solange das Gef\xe4\xdf mit seiner Seele \xfcberdauert. Im urspr\xfcnglichen Spiel bargen Schlachtz\xfcgler, die Kel'Thuzad besiegt hatten, sein Phylakterium und \xfcbergaben es der Argentumd\xe4mmerung zur Verwahrung. Sp\xe4tere Geschichten enth\xfcllten, dass einer ihrer Priester, Vater Inigo Montoy, dieses Vertrauen verriet und es nach Nordend brachte, was dem Erzlich Zeit zur R\xfcckkehr verschaffte."]}}},1729,[]);
__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"terms",{enumerable:!0,get:function(){return n}});const n={"term:argent-dawn":{title:"Argentumd\xe4mmerung",summary:"Ein Orden, der geschworen hat, Azeroth vor der Gei\xdfel zu sch\xfctzen \u2013 ohne den blinden Hass des Scharlachroten Kreuzzugs.",body:["Als die \xdcberlebenden der Silbernen Hand in Lordaeron zum fanatischen Scharlachroten Kreuzzug erstarrten, weigerten sich einige, ihnen zu folgen. Angef\xfchrt von Gestalten wie Lord Maxwell Tyrosus gr\xfcndeten sie die Argentumd\xe4mmerung, die jeden willkommen hei\xdft, der gegen die Untoten k\xe4mpfen will. Von der Kapelle des Hoffnungsvollen Lichts in den \xd6stlichen Pestl\xe4ndern aus beobachtet der Orden die Gei\xdfel und belohnt jene, die helfen, die Front zu halten."]},"term:burning-legion":{title:"Brennende Legion",summary:"Das endlose D\xe4monenheer des gefallenen Titanen Sargeras, das geschworen hat, die gesamte Sch\xf6pfung zu verbrennen.",body:["Einst Champion des Pantheons der Titanen, erfuhr Sargeras, dass die M\xe4chte der Leere die Weltenseelen verderben wollten, und beschloss in seiner Verzweiflung, die Sch\xf6pfung lieber zu verbrennen, als sie ihnen zu \xfcberlassen. Er befreite die D\xe4monen, die er eingekerkert hatte, und gewann die Eredarf\xfcrsten Kil'jaeden und Archimonde daf\xfcr, sie zu befehligen. Die Legion fiel im Krieg der Ahnen und erneut im Dritten Krieg in Azeroth ein, und ihre Handlanger lauern noch immer an Orten wie dem Teufelswald und den Verw\xfcsteten Landen."]},"term:cenarion-circle":{title:"Zirkel des Cenarius",summary:"Der Druidenorden der Nachtelfen und Tauren, der von der Mondlichtung aus das Gleichgewicht der Natur bewahrt.",body:["Benannt nach dem Halbgott Cenarius, der die ersten Druiden lehrte, vereint der Zirkel Druiden der Nachtelfen und der Tauren in einem einzigen Orden. Sein Herz ist das Dorf Nachthafen auf der Mondlichtung, ein Zufluchtsort, an dem K\xe4mpfe verboten sind, und seine Mitglieder wachen au\xdferdem von der Burg Cenarius aus \xfcber die Gefahren von Silithus."]},"term:cult-of-the-damned":{title:"Kult der Verdammten",summary:"Kel'Thuzads Kult des Lichk\xf6nigs, der ewiges Leben versprach und die Seuche brachte.",body:["Der Erzmagier Kel'Thuzad kehrte den Kirin Tor den R\xfccken, um Nekromantie zu studieren, und scharte die Armen und Verzweifelten Lordaerons mit Versprechen eines besseren, todlosen Lebens um sich. Der Kult versteckte die Seuche des Lichk\xf6nigs in Getreidelieferungen und verwandelte ganze D\xf6rfer in Gei\xdfel. Seine Nekromanten lehren noch immer in der Scholomance, in Caer Darrow, der alten Burg der Familie Barov."]},"term:dark-portal":{title:"Das Dunkle Portal",summary:"Das Tor zwischen Draenor und Azeroth, durch das die Horde der Orcs einfiel.",body:["Der orcische Hexenmeister Gul'dan und der besessene W\xe4chter Medivh \xf6ffneten das Dunkle Portal und verbanden Draenor mit dem Schwarzen Morast in Azeroth. Seine \xd6ffnung leitete den Ersten Krieg ein, und die Jahre der Geschichte von Warcraft werden noch heute von ihr an gez\xe4hlt. Die Allianz zerst\xf6rte es nach dem Zweiten Krieg, Ner'zhul riss es erneut auf, und Khadgar brachte es von Draenors Seite aus zum Einsturz. Sein ruhender Rahmen ragt noch immer \xfcber den Verw\xfcsteten Landen auf."]},"term:defias-brotherhood":{title:"Defiasbruderschaft",summary:"Unbezahlte Steinmetze aus Sturmwind, die unter Edwin VanCleef zu Banditen wurden.",body:["Die Steinmetzgilde baute Sturmwind nach dem Zweiten Krieg wieder auf, doch die Adligen weigerten sich, sie zu bezahlen. Ihr Anf\xfchrer Edwin VanCleef f\xfchrte die zornigen Steinmetze in den Westfall und schmiedete sie zur Defiasbruderschaft, einer Bande von Dieben und Saboteuren, die sich in den Todesminen versteckt. In Forever tauchen ihre Mitglieder auch in Alcaz Prison auf, wo sie in einen Kampf mit den Naga verstrickt sind."]},"term:dragon-aspects":{title:"Drachenaspekte",summary:"F\xfcnf gro\xdfe Drachen, von den Titanen mit Macht ausgestattet, um Azeroth zu h\xfcten, und jeder f\xfchrt einen Drachenschwarm an.",body:["Die Titanen erw\xe4hlten f\xfcnf Drachen und gaben jedem einen Teil ihrer Macht: Alexstrasza der Lebensbinderin des roten Schwarms, Ysera der Tr\xe4umerin des gr\xfcnen, Nozdormu dem Zeitlosen des bronzenen, Malygos dem Zauberweber des blauen und Neltharion dem Erdw\xe4chter des schwarzen. Neltharions Verrat machte ihn zu Todesschwinge, und seine Kinder Onyxia und Nefarian schmieden noch immer R\xe4nke in Azeroth."]},"term:elemental-lords":{title:"Elementarf\xfcrsten",summary:"Die vier Herrscher \xfcber Feuer, Erde, Luft und Wasser, einst Diener der Alten G\xf6tter.",body:["Ragnaros des Feuers, Therazane der Erde, Al'Akir der Luft und Neptulon des Wassers f\xfchrten die Elementare im Krieg der Alten G\xf6tter gegen die Diener der Titanen an. Als das Schwarze Imperium fiel, verbannten die H\xfcter sie in die Elementarebene. Schamanen streben danach, die Elemente im Gleichgewicht zu halten, w\xe4hrend ein Fehler des Dunkeleisen-Zauberers Thaurissan Ragnaros unter dem Schwarzfels in die Welt zur\xfcckbrachte."]},"term:elune":{title:"Elune",summary:"Die Mondg\xf6ttin der Nachtelfen, deren Priesterinnen ihr Volk anf\xfchren.",body:["Die Nachtelfen verehren Elune seit den Anf\xe4ngen ihrer Zivilisation und finden F\xfchrung im Licht des Mondes. Die Schwesternschaft der Elune unter der Hohepriesterin Tyrande Wisperwind dient in Darnassus zugleich als Priesterschaft und als F\xfchrung, und die Priester der Nachtelfen beziehen ihre Heilkraft von der G\xf6ttin."]},"term:emerald-dream":{title:"Smaragdgr\xfcner Traum",summary:"Ein tr\xe4umendes Spiegelbild der unber\xfchrten Wildnis Azeroths, \xfcber das Ysera wacht und das Druiden durchwandern.",body:["Der Smaragdgr\xfcne Traum spiegelt die Welt so, wie sie ohne sterbliche H\xe4nde h\xe4tte sein k\xf6nnen. Ysera und ihr gr\xfcner Drachenschwarm bewachen ihn, und Druiden betreten ihn im Geist und schlafen dabei mitunter jahrhundertelang. In Azeroths Gegenwart verdirbt etwas den Traum: Ein schleichender Albtraum verzerrt die Tr\xe4ume von Naralex in den H\xf6hlen des Wehklagens und hat die gr\xfcnen Drachen des Versunkenen Tempels in den Wahnsinn getrieben."]},"term:explorers-league":{title:"Forscherliga",summary:"Eisenschmiedes Gesellschaft zwergischer Arch\xe4ologen, die nach den Geheimnissen der Titanen graben.",body:["Von der Halle der Forscher in Eisenschmiede aus schickt die Liga Zwerge in alle Welt, um nach Relikten zu suchen, die erkl\xe4ren k\xf6nnten, woher ihr Volk stammt. Ihr ber\xfchmtestes Mitglied ist Brann Bronzebart, der rastlose Bruder des K\xf6nigs. Ausgr\xe4ber der Liga legten die Titanengew\xf6lbe von Uldaman frei, und in Forever sind die seltsamen, in der Zeit erstarrten Ruinen jenseits von Whelgar's Excavation Site im Sumpfland genau die Art von R\xe4tsel, der die Liga nachjagt."]},"term:fel":{title:"Teufelsmagie",summary:"Die brennende, verderbende Magie der Brennenden Legion.",body:["Teufelsmagie ist die Magie der D\xe4monen: m\xe4chtig, s\xfcchtig machend und verheerend f\xfcr alles, was sie ber\xfchrt. Gul'dans Hexenmeister saugten mit ihr das Leben aus Draenor und banden die Orcs an die Legion, und ihr Makel f\xe4rbte deren Haut gr\xfcn. Hexenmeister wirken sie noch heute, und ihre Narben zeichnen den Teufelswald, wo d\xe4monische Verderbnis einen uralten Wald vergiftet hat."]},"term:guardian-of-tirisfal":{title:"W\xe4chter von Tirisfal",summary:"Ein Magier, dem die vereinte Macht eines geheimen Rates verliehen wird, um allein gegen die Brennende Legion zu k\xe4mpfen.",body:["Hochelfische und menschliche Magier gr\xfcndeten den geheimen Rat von Tirisfal, um zu verhindern, dass D\xe4monen durch leichtfertige Zauberei in die Welt schl\xfcpfen. In jedem Zeitalter goss der Rat seine Macht in einen einzigen Champion, den W\xe4chter. Aegwynn trug diese Rolle jahrhundertelang; ihr Sohn Medivh, der letzte W\xe4chter, war insgeheim von Sargeras besessen und \xf6ffnete den Orcs den Weg."]},"term:highborne":{title:"Hochgeborene",summary:"Die arkane Aristokratie des alten Nachtelfenreichs, deren Gier nach Magie die Legion herbeirief.",body:["Die Hochgeborenen dienten K\xf6nigin Azshara als Hofstaat und Zauberer und sch\xf6pften immer tiefer aus dem Brunnen der Ewigkeit, bis ihre Zauber die Aufmerksamkeit von Sargeras erregten. Nach der Gro\xdfen Teilung wurden die meisten \xdcberlebenden verbannt und gr\xfcndeten als Hochelfen Quel'Thalas. Andere, die Shen'dralar, blieben verborgen in Eldre'Thalas, der Stadt, die heute D\xfcsterbruch hei\xdft."]},"term:holy-light":{title:"Das Heilige Licht",summary:"Die Macht der Hoffnung und Tugend, die Paladine und Priester kanalisieren.",body:["Die Menschen verehren das Licht durch die Kirche des Heiligen Lichts, deren Geistliche die Verwundeten heilen und deren Kathedralen in Sturmwind aufragen und einst in Lordaeron aufragten. Auch die Zwerge nahmen es an. Im Zweiten Krieg vereinte Erzbischof Alonsus Faol Glauben und Stahl, indem er die Paladine der Silbernen Hand gr\xfcndete, und das Licht ist bis heute der Fluch der Untoten."]},"term:kaldorei":{title:"Kaldorei",summary:"Die Nachtelfen, die \u201eKinder der Sterne\u201c, eine der \xe4ltesten Zivilisationen Kalimdors.",body:["Die Nachtelfen stammen von Trollen ab, die der Brunnen der Ewigkeit verwandelt hatte, und errichteten unter K\xf6nigin Azshara ein glanzvolles Reich, bevor es in der Gro\xdfen Teilung versank. Zehntausend Jahre lang lebten sie als Druiden und Schildwachen, durch Nordrassil alterslos, bis der Dritte Krieg sie ihre Unsterblichkeit kostete. Heute herrschen sie von Darnassus auf Teldrassil aus und stehen an der Seite der Allianz."]},"term:kirin-tor":{title:"Kirin Tor",summary:"Der regierende Rat der Magier, der Dalaran lenkt und gef\xe4hrliche Magie verwahrt.",body:["Gegr\xfcndet in Dalaran, der Stadt der Magier, beaufsichtigen die Kirin Tor das Studium der arkanen Magie und schlie\xdfen Artefakte weg, die f\xfcr die Welt zu gef\xe4hrlich sind. Archimonde lie\xdf Dalaran im Dritten Krieg in Tr\xfcmmern zur\xfcck, und im urspr\xfcnglichen Spiel lag die Stadt unter einer violetten Kuppel verborgen. In Forever ist diese Barriere gefallen und gibt den Blick auf einen Wiederaufbau frei, den fehlgeleitetes arkanes Chaos \xfcberrollt hat."]},"term:ley-lines":{title:"Leylinien",summary:"Str\xf6me arkaner Energie, die Azeroth wie Adern durchziehen.",body:["Leylinien tragen rohe arkane Macht durch die Welt, und wo sie sich kreuzen, sammelt sich die Magie in besonderer St\xe4rke. Die Hochelfen errichteten den Sonnenbrunnen an einem solchen Knotenpunkt, und Magier suchen diese Str\xf6me seit Langem. In Forever k\xf6nnen die Skyborne des High Order sie mit ihrer Volksf\xe4higkeit Read Ley Line anzapfen, die in der N\xe4he einer Leylinie weit l\xe4nger anh\xe4lt."]},"term:lich-king":{title:"Lichk\xf6nig",summary:"Der unsterbliche Herr der Gei\xdfel, der im Eis von Nordend thront.",body:["Kil'jaeden riss den Geist des orcischen Schamanen Ner'zhul aus seinem K\xf6rper und versiegelte ihn in einem Eisblock auf der Eiskrone, dem Frostthron, um Azeroth f\xfcr die Legion vorzubereiten. Von dort aus erweckte der Lichk\xf6nig die Gei\xdfel und verbreitete die Seuche. Nach dem Dritten Krieg erklomm Prinz Arthas den Thron und verschmolz mit ihm, und der vereinte Lichk\xf6nig wartet nun in Nordend."]},"term:loa":{title:"Loa",summary:"Die m\xe4chtigen Tiergeister und G\xf6tter, die die Trolle verehren.",body:["Jeder Trollstamm ehrt die Loa, uralte Geister, die oft die Gestalt gro\xdfer Tiere annehmen, und feilscht mit ihnen um St\xe4rke. Manche sind launisch, aber gerecht, andere grausam. Hakkar der Seelenschinder, der Loa des Blutes, h\xe4tte das Reich der Gurubashi beinahe verschlungen, und seine Anh\xe4nger regen sich noch immer im Schlingendorntal und in den S\xfcmpfen des Elends."]},"term:nathrezim":{title:"Nathrezim",summary:"Die Schreckenslords: gerissene, vampirische D\xe4monen, die der Legion durch T\xe4uschung dienen.",body:["Die Nathrezim ziehen das Fl\xfcstern dem offenen Krieg vor. Die Legion setzte Schreckenslords wie Mal'Ganis, Tichondrius und Balnazzar ein, um \xfcber den Lichk\xf6nig zu wachen und die Eroberung Lordaerons durch die Gei\xdfel zu lenken. Als sich der Lichk\xf6nig von ihnen befreite, zerstreuten sie sich, doch einige verbergen sich noch immer vor aller Augen: Balnazzar tr\xe4gt das Gesicht des Gro\xdfkreuzz\xfcglers des Scharlachroten Kreuzzugs."]},"term:nordrassil":{title:"Nordrassil",summary:"Der Weltenbaum auf dem Berg Hyjal, von den Aspekten gepflanzt, um den zweiten Brunnen der Ewigkeit zu versiegeln.",body:["Nach der Gro\xdfen Teilung goss Illidan heimlich gestohlenes Wasser aus dem Brunnen der Ewigkeit in einen See auf dem Berg Hyjal. Um diesen neuen Brunnen zu versiegeln, pflanzten die Drachenaspekte einen verzauberten Samen, aus dem Nordrassil wuchs, und sein Segen machte die Nachtelfen alterslos. Archimondes Sturz an seinen Wurzeln verwundete den Baum, und der Schlachtzug Hyjal Summit in Forever steigt zum Gipfel an seiner Seite hinauf."]},"term:old-gods":{title:"Alte G\xf6tter",summary:"Uralte Wesen der Leere, die sich in Azeroth eingruben, um seine Weltenseele zu verderben.",body:["Lange bevor Sterbliche die Welt betraten, st\xfcrzten die Alten G\xf6tter, darunter C'Thun, Yogg-Saron, N'Zoth und Y'Shaarj, auf Azeroth herab und errichteten ein Schwarzes Imperium. Das Herausrei\xdfen von Y'Shaarj verwundete die Welt selbst, daher entschieden sich die Titanen, die anderen stattdessen unter der Erde einzukerkern. Ihr Fl\xfcstern treibt noch immer Kulte wie den Schattenhammer an, und C'Thun regt sich unter Ahn'Qiraj in Silithus."]},"term:silver-hand":{title:"Orden der Silbernen Hand",summary:"Der erste Paladinorden, im Zweiten Krieg in Lordaeron gegr\xfcndet.",body:["Erzbischof Alonsus Faol erkannte, dass Geistliche allein die Horde nicht \xfcberleben w\xfcrden, und bildete daher Krieger in den Wegen des Lichts aus. Uther der Lichtbringer wurde der erste der Ritter der Silbernen Hand. Der Orden k\xe4mpfte den ganzen Zweiten Krieg hindurch, doch der Fall von Arthas zerbrach ihn: Uther starb durch die Hand seines fr\xfcheren Sch\xfclers, und viele \xdcberlebende wanderten zum Scharlachroten Kreuzzug ab."]},"term:queldorei":{title:"Quel'dorei",summary:"Die Hochelfen von Quel'Thalas, Erben der verbannten Hochgeborenen.",body:["Fast siebentausend Jahre vor dem Dunklen Portal \xfcberquerten verbannte Hochgeborene das Meer, gr\xfcndeten Quel'Thalas und entfachten den Sonnenbrunnen. In den Trollkriegen verb\xfcndeten sie sich mit den Menschen von Arathor und lehrten sie die Magie. Als die Gei\xdfel von Arthas ihr K\xf6nigreich verw\xfcstete und den Sonnenbrunnen besudelte, nahmen die meisten \xdcberlebenden zum Gedenken an ihre Toten einen neuen Namen an: Sin'dorei, Blutelfen."]},"term:scarlet-crusade":{title:"Scharlachroter Kreuzzug",summary:"Eiferer, die Untote und jeden jagen, den sie der Seuche verd\xe4chtigen, insgeheim angef\xfchrt von einem Schreckenslord.",body:["Hervorgegangen aus \xfcberlebenden Paladinen und Soldaten Lordaerons, schwor der Kreuzzug, die Gei\xdfel auszurotten, wurde aber so fanatisch, dass er die Verlassenen und lebende Reisende gleicherma\xdfen angreift. Sein Gro\xdfkreuzz\xfcgler ist insgeheim der Schreckenslord Balnazzar. Zu seinen Hochburgen geh\xf6ren das Scharlachrote Kloster in Tirisfal, Herdweiler und Tyrs Hand."]},"term:scourge":{title:"Gei\xdfel",summary:"Das Untotenheer des Lichk\xf6nigs, verbreitet durch Seuche und Nekromantie.",body:["Die Gei\xdfel ist an den Willen des Lichk\xf6nigs gebunden: Ghule, Monstrosit\xe4ten, Liche und Todesritter, aus den Gefallenen erhoben. Die Seuche, die sie erschuf, fegte im Dritten Krieg \xfcber Lordaeron hinweg und lie\xdf die Pestl\xe4nder zur\xfcck. Unter Kel'Thuzad h\xe4lt die Gei\xdfel noch immer Stratholme und die Scholomance, und ihr Arm reicht bis zum H\xfcgel der Klingenhauer im Brachland."]},"term:skywall":{title:"Skywall",summary:"Die Elementarebene der Luft, das Reich von Al'Akir, dem Windf\xfcrsten.",body:["Als die Diener der Titanen die Elementare banden, wurden die F\xfcrsten der Luft nach Skywall verbannt, in ein Reich endlosen Himmels, \xfcber das Al'Akir herrscht. In Forever ist Skywall auch die Heimat von Zephras Isle, dem schwebenden Startgebiet der Skyborne. Die Luftelementare der Insel verschwanden vor Jahrhunderten, und die Magie, die sie in der Luft h\xe4lt, l\xe4sst langsam nach."]},"term:sunwell":{title:"Sonnenbrunnen",summary:"Die Quelle arkaner Macht im Herzen von Quel'Thalas.",body:["Dath'Remar Sonnenwanderer goss ein gestohlenes Fl\xe4schchen aus dem Brunnen der Ewigkeit in einen See, an dem sich Leylinien treffen, und der Sonnenbrunnen erstrahlte zum Leben. Jahrtausendelang n\xe4hrte er die Magie und Kultur der Hochelfen. Im Dritten Krieg nutzte Arthas sein Wasser, um Kel'Thuzad als Lich zu erwecken, und sch\xe4ndete die Quelle; ihr Verlust hinterlie\xdf bei den \xdcberlebenden einen bleibenden Hunger nach Magie."]},"term:titan-forged":{title:"Titanengeschmiedete",summary:"Die H\xfcter und anderen Diener, die die Titanen erschufen, um Azeroth Ordnung zu bringen.",body:["Die Titanen formten Diener, die ihr Werk vollenden sollten: hoch aufragende H\xfcter und V\xf6lker aus Stein und Metall wie die Irdenen und die Mechagnome. Im Lauf der Zeitalter machte der Fluch des Fleisches der Alten G\xf6tter viele von ihnen sterblich, und die Zwerge und Gnome stammen von ihnen ab. Titanengeschmiedete W\xe4chter h\xfcten noch immer Gew\xf6lbe wie Uldaman, und Forever f\xfcgt weitere St\xe4tten der Titanen hinzu, von der Grabung im Sumpfland bis zu Shaper's Terrace im Krater von Un'Goro."]},"term:titans":{title:"Titanen",summary:"Kolossale Weltenseelen, die dem Kosmos Ordnung bringen wollten und Azeroth formten.",body:["Die Titanen sind zu gottgleichen Wesen erwachte Weltenseelen. Ihr Pantheon, angef\xfchrt von Aman'Thul, durchsuchte den Kosmos nach schlafenden Weltenseelen und fand in Azeroth eine von gro\xdfer Verhei\xdfung. Sie rissen den Alten Gott Y'Shaarj aus der Welt, kerkerten die \xfcbrigen ein und \xfcberlie\xdfen es ihren Dienern, das Land zu formen. Ihr m\xe4chtigster Champion, Sargeras, fiel sp\xe4ter und gr\xfcndete die Brennende Legion."]},"term:twilights-hammer":{title:"Schattenhammer",summary:"Einst ein Orcclan, heute ein Weltuntergangskult im Dienst der Alten G\xf6tter.",body:["Angef\xfchrt vom zweik\xf6pfigen Ogermagier Cho'gall k\xe4mpfte der Schattenhammer im Zweiten Krieg als Orcclan, bevor er sich in einen Kult verwandelte, der sich nach dem Ende der Welt sehnt. Seine Mitglieder, aus allen V\xf6lkern stammend, versammeln sich an Orten wie der Tiefschwarzen Grotte und Silithus. In Forever h\xe4lt der Kult au\xdferdem die Ruinen von Sunnyglade in den Riverglades."]},"term:well-of-eternity":{title:"Brunnen der Ewigkeit",summary:"Der See aus roher arkaner Macht im Herzen des alten Kalimdor, dessen Implosion die Welt zerriss.",body:["Der Brunnen entstand dort, wo die Titanen Y'Shaarj aus der Welt rissen, und die H\xfcter beruhigten die blutende Wunde zu einem See reiner Macht. Die Nachtelfen errichteten ihr Reich an seinen Ufern, und die r\xfccksichtslosen Zauber der Hochgeborenen lockten die Legion durch ihn herbei. Sein Zusammenbruch im Krieg der Ahnen verursachte die Gro\xdfe Teilung, und wo er einst lag, tost heute der Mahlstrom."]}}},1730,[]);